const check = (label: string, fn: () => void): void => {
  if (!matchesFilter(label)) {
    skipped += 1;
    return;
  }
  const startedAt = performance.now();
  fn();
  checks += 1;
  console.log(`  ok: ${label}${timingSuffix(startedAt)}`);
};
/** A `check` that costs seconds — see the slow-tier note above. */
const checkSlow = (label: string, fn: () => void): void => {
  if (!slowEnabled) {
    slowSkipped += 1;
    return;
  }
  check(label, fn);
};
const checkAsync = async (label: string, fn: () => Promise<void>): Promise<void> => {
  if (!matchesFilter(label)) {
    skipped += 1;
    return;
  }
  const startedAt = performance.now();
  await fn();
  checks += 1;
  console.log(`  ok: ${label}${timingSuffix(startedAt)}`);
};

function listPublicFiles(root: string): string[] {
  const files: string[] = [];
  for (const entry of readdirSync(root, { withFileTypes: true })) {
    if (entry.name.startsWith(".")) continue;
    const path = `${root}/${entry.name}`;
    if (entry.isDirectory()) {
      files.push(...listPublicFiles(path));
    } else if (entry.isFile() && statSync(path).isFile()) {
      files.push(path.replace(/^public\//, "").replace(/\\/g, "/"));
    }
  }
  return files.sort((a, b) => a.localeCompare(b));
}

function findManifestStaticMeshFixture(manifest: AssetManifest): AssetRecord {
  const fixture = manifest.assets.find(
    (asset) =>
      assetType(asset) === "staticMesh" &&
      assetPath(asset).endsWith(".glb") &&
      asset.runtime &&
      typeof asset.runtime.loadGroup === "string" &&
      typeof asset.runtime.bytes === "number",
  );
  if (!fixture) throw new Error("Expected at least one static mesh fixture in the asset manifest.");
  return fixture;
}

