// P4 Boot / Loading UX: pure progress aggregator.
check("load progress: counts loaded/failed/pending and derives fraction + done", () => {
  const tracker = new LoadProgressTracker();
  // Empty is immediately complete (nothing to wait for).
  assert.deepEqual(tracker.snapshot(), {
    total: 0,
    loaded: 0,
    failed: 0,
    pending: 0,
    fraction: 1,
    done: true,
    failedIds: [],
  });

  tracker.expectAll(["model-a", "model-b", { id: "tex-c", label: "Texture C" }, "audio-d"]);
  let snap = tracker.snapshot();
  assert.equal(snap.total, 4);
  assert.equal(snap.pending, 4);
  assert.equal(snap.fraction, 0);
  assert.equal(snap.done, false);

  tracker.markLoaded("model-a");
  tracker.markLoaded("model-b");
  snap = tracker.snapshot();
  assert.equal(snap.loaded, 2);
  assert.equal(snap.fraction, 0.5);
  assert.equal(snap.done, false);

  tracker.markFailed("tex-c", "404 Not Found");
  snap = tracker.snapshot();
  assert.equal(snap.failed, 1);
  assert.deepEqual(snap.failedIds, ["tex-c"]);
  // Settled (loaded+failed) counts toward the bar even though one failed.
  assert.equal(snap.fraction, 0.75);
  assert.equal(snap.done, false);

  tracker.markLoaded("audio-d");
  snap = tracker.snapshot();
  assert.equal(snap.done, true);
  assert.equal(snap.fraction, 1);
  assert.equal(snap.pending, 0);

  // Label from expectAll survives; the failed item carries its reason.
  const failed = tracker.entries().find((item) => item.id === "tex-c");
  assert.equal(failed?.label, "Texture C");
  assert.equal(failed?.error, "404 Not Found");
});

check("load progress: transitions are idempotent and retry moves failed -> loaded", () => {
  const tracker = new LoadProgressTracker();
  tracker.expect("m1");

  // Auto-registration: reporting an undeclared id grows the total.
  tracker.markLoaded("m2");
  let snap = tracker.snapshot();
  assert.equal(snap.total, 2);
  assert.equal(snap.loaded, 1);

  // Re-reporting a loaded item does not double-count.
  tracker.markLoaded("m2");
  assert.equal(tracker.snapshot().loaded, 1);

  tracker.markFailed("m1", "network");
  snap = tracker.snapshot();
  assert.equal(snap.failed, 1);
  assert.equal(snap.loaded, 1);

  // resetFailed rewinds failed items to pending for a retry pass.
  tracker.resetFailed();
  snap = tracker.snapshot();
  assert.equal(snap.failed, 0);
  assert.equal(snap.pending, 1);
  assert.deepEqual(snap.failedIds, []);

  // Retry succeeds: the same id settles as loaded, completing the set.
  tracker.markLoaded("m1");
  snap = tracker.snapshot();
  assert.equal(snap.loaded, 2);
  assert.equal(snap.done, true);
});

check("load progress: formatLoadDetail renders settled/total with a failure suffix", () => {
  const tracker = new LoadProgressTracker();
  assert.equal(formatLoadDetail(tracker.snapshot()), "");
  tracker.expectAll(["a", "b", "c"]);
  assert.equal(formatLoadDetail(tracker.snapshot()), "0 / 3");
  tracker.markLoaded("a");
  assert.equal(formatLoadDetail(tracker.snapshot()), "1 / 3");
  tracker.markFailed("b", "boom");
  assert.equal(formatLoadDetail(tracker.snapshot()), "2 / 3 · 1 failed");
});

check("load progress: subscribe fires immediately and on each change, clear resets", () => {
  const tracker = new LoadProgressTracker();
  tracker.expect("only");
  const seen: number[] = [];
  const unsubscribe = tracker.subscribe((snap) => seen.push(snap.loaded));
  // Immediate fire with the current snapshot.
  assert.deepEqual(seen, [0]);
  tracker.markLoaded("only");
  assert.deepEqual(seen, [0, 1]);
  // No-op transition does not notify.
  tracker.markLoaded("only");
  assert.deepEqual(seen, [0, 1]);
  unsubscribe();
  tracker.clear();
  // After unsubscribe, no further notifications; tracker is empty again.
  assert.deepEqual(seen, [0, 1]);
  assert.deepEqual(tracker.snapshot(), {
    total: 0,
    loaded: 0,
    failed: 0,
    pending: 0,
    fraction: 1,
    done: true,
    failedIds: [],
  });
});

// ---------------------------------------------------------------------------
// P5 Performance Infrastructure: subsystem profiler, perf budget, asset report.
// ---------------------------------------------------------------------------

check("subsystem profiler: rolling average sorts worst-first with last + peak", () => {
  const profiler = new SubsystemProfiler(4); // small window for the test
  // physics is consistently the most expensive; behavior cheapest.
  profiler.record("physics", 2);
  profiler.record("behavior", 0.5);
  profiler.record("animation", 1);
  profiler.endFrame();
  profiler.record("physics", 4);
  profiler.record("behavior", 0.5);
  profiler.record("animation", 1);
  profiler.endFrame();

  const snapshot = profiler.snapshot();
  assert.equal(snapshot.frames, 2);
  assert.deepEqual(
    snapshot.subsystems.map((s) => s.id),
    ["physics", "animation", "behavior"],
  );
  const physics = snapshot.subsystems[0]!;
  assert.equal(physics.averageMs, 3); // (2 + 4) / 2
  assert.equal(physics.lastMs, 4);
  assert.equal(physics.maxMs, 4);
  assert.equal(physics.samples, 2);
  // totalAverageMs sums every subsystem's rolling average (3 + 1 + 0.5).
  assert.equal(snapshot.totalAverageMs, 4.5);
});

check("subsystem profiler: window drops old samples, clamps negatives, top(n) + clear", () => {
  const profiler = new SubsystemProfiler(2); // window of 2 frames
  profiler.record("a", 10);
  profiler.record("a", 20);
  profiler.record("a", 30); // evicts the 10 → window holds [20, 30]
  assert.equal(profiler.snapshot().subsystems[0]!.averageMs, 25);
  assert.equal(profiler.snapshot().subsystems[0]!.maxMs, 30);

  // Negative (clock skew) samples clamp to 0 rather than corrupting the mean.
  const skew = new SubsystemProfiler(2);
  skew.record("s", -5);
  skew.record("s", 5);
  assert.equal(skew.snapshot().subsystems[0]!.averageMs, 2.5);

  const many = new SubsystemProfiler();
  many.record("x", 1);
  many.record("y", 9);
  many.record("z", 5);
  assert.deepEqual(
    many.top(2).map((t) => t.id),
    ["y", "z"],
  );
  many.clear();
  assert.deepEqual(many.snapshot(), { subsystems: [], totalAverageMs: 0, frames: 0 });
});

check("subsystem profiler: registry times each subsystem with an injected clock", () => {
  const app = new EngineApp();
  const ticks: string[] = [];
  const makeSubsystem = (id: string): Subsystem => ({
    id,
    update: () => {
      ticks.push(id);
    },
  });
  app.registerSubsystem(makeSubsystem("first"));
  app.registerSubsystem(makeSubsystem("second"));

  // Deterministic clock: each now() call advances 1ms, so every subsystem's
  // measured (end - start) is exactly 1ms.
  let clock = 0;
  const profiler = app.enableProfiling(() => (clock += 1));
  assert.equal(profiler instanceof SubsystemProfiler, true);
  // Idempotent: a second enable returns the same profiler.
  assert.equal(app.enableProfiling(), profiler);

  app.update(0.016);
  assert.deepEqual(ticks, ["first", "second"]);
  const snapshot = app.getProfileSnapshot();
  assert.ok(snapshot);
  assert.equal(snapshot!.frames, 1);
  assert.deepEqual(
    snapshot!.subsystems.map((s) => [s.id, s.lastMs]),
    [
      ["first", 1],
      ["second", 1],
    ],
  );
});

check("perf budget: flags over-budget metrics and keeps a stable row order", () => {
  const metrics = evaluatePerfBudget(
    { drawCalls: 120, triangles: 2_000_000, textures: 200 },
    DEFAULT_PERF_BUDGET,
  );
  assert.deepEqual(
    metrics.map((m) => m.key),
    ["drawCalls", "triangles", "textures"],
  );
  assert.deepEqual(
    metrics.map((m) => m.over),
    [false, true, true],
  );
  assert.equal(isOverBudget(metrics), true);

  const withinBudget = evaluatePerfBudget({ drawCalls: 10, triangles: 100, textures: 4 });
  assert.equal(isOverBudget(withinBudget), false);
});

check("perf budget: formatByteSize renders decimal units with a placeholder for bad input", () => {
  assert.equal(formatByteSize(512), "512 B");
  assert.equal(formatByteSize(1500), "1.5 kB");
  assert.equal(formatByteSize(2_000_000), "2.0 MB");
  assert.equal(formatByteSize(3_500_000_000), "3.5 GB");
  assert.equal(formatByteSize(-1), "—");
  assert.equal(formatByteSize(Number.NaN), "—");
});

check("frame metrics: windowed average and spike counts over raw deltas", () => {
  const monitor = new FrameMetricsMonitor({ windowSeconds: 5, spikeThresholdMs: 33.3 });
  // 100 steady 16 ms frames = 1.6 s < 5 s window → all in-window.
  for (let i = 0; i < 100; i += 1) monitor.record(16);
  const steady = monitor.metrics();
  assert.equal(steady.sampleCount, 100);
  assert.ok(Math.abs(steady.averageFrameTimeMs - 16) < 1e-9);
  assert.equal(steady.p95FrameTimeMs, 16);
  assert.equal(steady.spikeCount, 0);
  assert.ok(Math.abs(steady.sampleWindowSeconds - 1.6) < 1e-9);
  assert.equal(steady.frameTimeMs, 16);

  // Inject spikes at the three thresholds. spikeCount catches all three, but the
  // average stays fine and — key point — P95 does NOT move: 3 hitches in 103
  // frames sit above the 95th percentile, which is exactly why spikeCount is a
  // separate signal from P95 (plan §3.1 / §7.1).
  monitor.record(40); // > 33.3
  monitor.record(60); // > 50
  monitor.record(120); // > 100 major hitch
  const spiked = monitor.metrics();
  assert.equal(spiked.spikeCount, 3);
  assert.equal(spiked.p95FrameTimeMs, 16); // rare spikes stay above the P95 tail
  assert.ok(spiked.averageFrameTimeMs < 20); // 3 spikes buried in 100 good frames
  assert.deepEqual(monitor.spikeCounts(), { over33ms: 3, over50ms: 2, over100ms: 1 });
});

check("frame metrics: P95 uses nearest-rank over the window", () => {
  const monitor = new FrameMetricsMonitor({ windowSeconds: 5 });
  // Frame times 1..20 ms. Nearest-rank P95: ceil(0.95 * 20) = 19 → 19th value.
  for (let ms = 1; ms <= 20; ms += 1) monitor.record(ms);
  const m = monitor.metrics();
  assert.equal(m.sampleCount, 20);
  assert.equal(m.averageFrameTimeMs, 10.5); // mean of 1..20
  assert.equal(m.p95FrameTimeMs, 19);
  assert.equal(m.spikeCount, 0); // none exceed the 33.3 ms default threshold
});

check("frame metrics: window is time-bounded and estimates refresh from the low percentile", () => {
  const monitor = new FrameMetricsMonitor({ windowSeconds: 1 });
  // 200 frames of 16 ms = 3.2 s of history, but the 1 s window keeps only the
  // most recent ~63 (walk stops once cumulative time crosses 1000 ms).
  for (let i = 0; i < 200; i += 1) monitor.record(16);
  const m = monitor.metrics();
  assert.ok(m.sampleWindowSeconds >= 1 && m.sampleWindowSeconds < 1.05);
  assert.ok(m.sampleCount <= 64 && m.sampleCount >= 62);
  // A 60 Hz cadence estimates a ~16 ms refresh interval.
  assert.equal(m.estimatedRefreshIntervalMs, 16);
  assert.equal(monitor.frames, 200);

  // A lone hitch after a reset is still reported (newest sample always kept).
  monitor.reset();
  const empty = monitor.metrics();
  assert.equal(empty.sampleCount, 0);
  assert.equal(empty.averageFrameTimeMs, 0);
  monitor.record(250);
  const hitch = monitor.metrics();
  assert.equal(hitch.sampleCount, 1);
  assert.equal(hitch.p95FrameTimeMs, 250);
  assert.equal(monitor.frames, 201); // lifetime counter survives reset
});

check("frame metrics: clamps skew and drops non-finite deltas", () => {
  const monitor = new FrameMetricsMonitor({ windowSeconds: 5 });
  monitor.record(Number.NaN); // dropped
  monitor.record(Number.POSITIVE_INFINITY); // dropped
  monitor.record(-5); // clamps to 0
  monitor.record(20);
  const m = monitor.metrics();
  assert.equal(m.sampleCount, 2);
  assert.equal(m.averageFrameTimeMs, 10); // (0 + 20) / 2
  assert.equal(monitor.frames, 2); // only the two finite deltas counted
});

check("quality profiles: resolve returns fresh copies and layers custom over a base", () => {
  // Concrete levels return a copy, never the shared profile object.
  const high = resolveQualitySettings("high");
  assert.notEqual(high, QUALITY_PROFILES.high);
  assert.deepEqual(high, QUALITY_PROFILES.high);
  high.renderScale = 0.1; // mutating the copy must not corrupt the template
  assert.equal(QUALITY_PROFILES.high.renderScale, 1.0);

  // The ladder runs highest → lowest for adaptive stepping.
  assert.deepEqual(QUALITY_LEVELS, ["ultra", "high", "medium", "low"]);
  // Render scale and pixel-ratio cap are monotonically non-increasing.
  const scales = QUALITY_LEVELS.map((l) => QUALITY_PROFILES[l].renderScale);
  const caps = QUALITY_LEVELS.map((l) => QUALITY_PROFILES[l].maxPixelRatio);
  for (let i = 1; i < scales.length; i += 1) {
    assert.ok(scales[i]! <= scales[i - 1]!);
    assert.ok(caps[i]! <= caps[i - 1]!);
  }

  // Custom layers overrides onto the base (default medium); untouched fields keep the base.
  const custom = resolveQualitySettings("custom", { renderScale: 0.5, aoAllowed: true });
  assert.equal(custom.renderScale, 0.5);
  assert.equal(custom.aoAllowed, true);
  assert.equal(custom.shadowMapSize, QUALITY_PROFILES.medium.shadowMapSize);
  // An explicit base level can override the default.
  const fromLow = resolveQualitySettings("custom", { bloomAllowed: true }, "low");
  assert.equal(fromLow.shadowsEnabled, false); // low's shadows stay off
  assert.equal(fromLow.bloomAllowed, true);
});

check("quality profiles: effective pixel ratio caps the DPR then folds in render scale", () => {
  // Ultra (cap 2, scale 1) equals min(dpr, 2) — the renderer's MAX_PIXEL_RATIO,
  // so applying Ultra is a no-op regardless of device DPR.
  assert.equal(effectiveDevicePixelRatio(3, QUALITY_PROFILES.ultra), 2);
  assert.equal(effectiveDevicePixelRatio(1, QUALITY_PROFILES.ultra), 1);
  // Low: cap 1, scale 0.7 → min(dpr, 1) * 0.7.
  assert.ok(Math.abs(effectiveDevicePixelRatio(3, QUALITY_PROFILES.low) - 0.7) < 1e-9);
  // Medium: cap 1.5, scale 0.85 → on a 2x display, 1.5 * 0.85.
  assert.ok(Math.abs(effectiveDevicePixelRatio(2, QUALITY_PROFILES.medium) - 1.275) < 1e-9);
  // Bad DPR falls back to 1; a zero cap falls back to the DPR (never zero out).
  assert.ok(effectiveDevicePixelRatio(Number.NaN, QUALITY_PROFILES.ultra) > 0);
  assert.ok(effectiveDevicePixelRatio(0, QUALITY_PROFILES.low) > 0);
});

check("quality profiles: post-process merge only gates off, never re-authors (Principle #2)", () => {
  const authoredOn = {
    ...POST_PROCESS_DEFAULTS,
    antialias: "smaa" as const,
    bloom: { ...POST_PROCESS_DEFAULTS.bloom, enabled: true, intensity: 2.5 },
    dof: { ...POST_PROCESS_DEFAULTS.dof, enabled: true },
    ao: { ...POST_PROCESS_DEFAULTS.ao, enabled: true },
  };
  // Low disallows AO/DoF/SMAA (bloom too); all authored-on effects gate off.
  const gated = applyQualityToPostProcess(authoredOn, QUALITY_PROFILES.low);
  assert.equal(gated.ao.enabled, false);
  assert.equal(gated.dof.enabled, false);
  assert.equal(gated.bloom.enabled, false);
  assert.equal(gated.antialias, "none");
  // Numeric authored params pass through untouched (gate, don't re-author).
  assert.equal(gated.bloom.intensity, 2.5);
  // Ultra allows everything, so authored-on stays on.
  const full = applyQualityToPostProcess(authoredOn, QUALITY_PROFILES.ultra);
  assert.equal(full.ao.enabled, true);
  assert.equal(full.dof.enabled, true);
  assert.equal(full.bloom.enabled, true);
  assert.equal(full.antialias, "smaa");

  // Author left everything OFF: even Ultra must NOT turn anything on.
  const allowMax = applyQualityToPostProcess(POST_PROCESS_DEFAULTS, QUALITY_PROFILES.ultra);
  assert.equal(allowMax.ao.enabled, false);
  assert.equal(allowMax.dof.enabled, false);
  assert.equal(allowMax.bloom.enabled, false);
  assert.equal(allowMax.antialias, "none");
});

check("hardware hints: no signals default to Medium; strong/weak devices split apart", () => {
  // No hints at all → neutral Medium, zero confidence (plan §4).
  const blank = suggestStartingQualityLevel({});
  assert.equal(blank.level, "medium");
  assert.equal(blank.confidence, 0);

  // A gaming desktop lands on Ultra.
  const desktop = suggestStartingQualityLevel({
    hardwareConcurrency: 16,
    deviceMemoryGb: 8,
    webglRenderer: "ANGLE (NVIDIA, NVIDIA GeForce RTX 4070 Direct3D11 vs_5_0 ps_5_0, D3D11)",
    isTouch: false,
  });
  assert.equal(desktop.level, "ultra");
  assert.ok(desktop.confidence > 0);

  // A mid laptop (8 cores, integrated Iris) lands around High.
  const laptop = suggestStartingQualityLevel({
    hardwareConcurrency: 8,
    deviceMemoryGb: 8,
    webglRenderer: "ANGLE (Intel, Intel(R) Iris(R) Xe Graphics Direct3D11, D3D11)",
  });
  assert.equal(laptop.level, "high");

  // A phone (touch + Mali) drops to Low.
  const phone = suggestStartingQualityLevel({
    hardwareConcurrency: 8,
    isTouch: true,
    webglRenderer: "Mali-G78",
  });
  assert.equal(phone.level, "low");

  // A software renderer is decisive → Low, higher confidence.
  const software = suggestStartingQualityLevel({
    hardwareConcurrency: 16,
    webglRenderer: "Google SwiftShader",
  });
  assert.equal(software.level, "low");
  assert.ok(software.confidence >= 0.7);
});

check("quality ladder: stepQualityLevel moves one rung and clamps at the ends", () => {
  assert.equal(stepQualityLevel("high", "down"), "medium");
  assert.equal(stepQualityLevel("high", "up"), "ultra");
  assert.equal(stepQualityLevel("ultra", "up"), "ultra"); // clamp top
  assert.equal(stepQualityLevel("low", "down"), "low"); // clamp bottom
  assert.equal(stepQualityLevel("medium", "none"), "medium");
});

check("measurement calibration: steps down when over budget, up with headroom, holds otherwise", () => {
  const metrics = (avg: number, p95: number, sampleCount = 300): FrameMetrics => ({
    frameTimeMs: avg,
    averageFrameTimeMs: avg,
    p95FrameTimeMs: p95,
    spikeCount: 0,
    sampleWindowSeconds: 5,
    sampleCount,
    estimatedRefreshIntervalMs: 8.3,
  });

  // Over budget at 60 FPS (target 16.7, avg 30 > 20.9) → one step down.
  const down = calibrateFromMeasurement({
    currentLevel: "high",
    metrics: metrics(30, 40),
    targetFrameRate: 60,
  });
  assert.equal(down.direction, "down");
  assert.equal(down.level, "medium");
  assert.equal(down.changed, true);

  // Comfortable headroom (avg 10 < 12.5, p95 within budget) → one step up.
  const up = calibrateFromMeasurement({
    currentLevel: "medium",
    metrics: metrics(10, 15),
    targetFrameRate: 60,
  });
  assert.equal(up.direction, "up");
  assert.equal(up.level, "high");

  // Good average but hitchy P95 → do not raise (holds).
  const hitchy = calibrateFromMeasurement({
    currentLevel: "medium",
    metrics: metrics(10, 30),
    targetFrameRate: 60,
  });
  assert.equal(hitchy.direction, "none");
  assert.equal(hitchy.changed, false);

  // Near target → hold.
  const hold = calibrateFromMeasurement({
    currentLevel: "high",
    metrics: metrics(16, 22),
    targetFrameRate: 60,
  });
  assert.equal(hold.changed, false);

  // A clamp at the ladder end reports as held even when the frame is slow.
  const floor = calibrateFromMeasurement({
    currentLevel: "low",
    metrics: metrics(50, 70),
    targetFrameRate: 60,
  });
  assert.equal(floor.level, "low");
  assert.equal(floor.changed, false);
  assert.equal(floor.direction, "none");

  // Too few samples → decline to act regardless of the numbers.
  const sparse = calibrateFromMeasurement({
    currentLevel: "high",
    metrics: metrics(30, 40, 5),
    targetFrameRate: 60,
  });
  assert.equal(sparse.changed, false);
});

check("bottleneck classifier: passive signals separate spike / cpu / gpu / draw-call / unknown", () => {
  const frame = (avg: number, p95: number, sampleCount = 300): FrameMetrics => ({
    frameTimeMs: avg,
    averageFrameTimeMs: avg,
    p95FrameTimeMs: p95,
    spikeCount: 0,
    sampleWindowSeconds: 5,
    sampleCount,
    estimatedRefreshIntervalMs: 8.3,
  });
  const subs = (total: number, topId: string): SubsystemProfileSnapshot => ({
    subsystems: [{ id: topId, lastMs: total, averageMs: total, maxMs: total, samples: 60 }],
    totalAverageMs: total,
    frames: 60,
  });
  const base = { budget: null, targetFrameTimeMs: 16.7 } satisfies Partial<BottleneckInput>;

  // Smooth average, hitchy P95 → transient spike (don't touch steady quality).
  const spike = classifyBottleneck({ ...base, metrics: frame(15, 40), subsystems: null });
  assert.equal(spike.type, "transient-spike");
  // The same spike during a load → asset-loading (higher confidence).
  const load = classifyBottleneck({
    ...base,
    metrics: frame(15, 40),
    subsystems: null,
    recentAssetActivity: true,
  });
  assert.equal(load.type, "asset-loading");
  assert.ok(load.confidence > spike.confidence);
  // The same spike under heap pressure → memory-pressure.
  const mem = classifyBottleneck({
    ...base,
    metrics: frame(15, 40),
    subsystems: null,
    memoryPressure: true,
  });
  assert.equal(mem.type, "memory-pressure");

  // Sustained over-budget frame + subsystems explain most of it → CPU bound,
  // naming the worst subsystem to target first.
  const cpu = classifyBottleneck({ ...base, metrics: frame(30, 34), subsystems: subs(22, "ai") });
  assert.equal(cpu.type, "cpu");
  assert.equal(cpu.suspectSubsystemId, "ai");

  // Over budget but subsystems explain little → GPU; a positive probe confirms it.
  const gpu = classifyBottleneck({
    ...base,
    metrics: frame(30, 34),
    subsystems: subs(6, "physics"),
    gpuProbe: { improvedFraction: 0.2 },
  });
  assert.equal(gpu.type, "gpu");
  assert.ok(gpu.confidence >= 0.8); // probe-confirmed
  // Without a profile the GPU verdict still stands (frame high, cpu unknown).
  const gpuNoProfile = classifyBottleneck({ ...base, metrics: frame(30, 34), subsystems: null });
  assert.equal(gpuNoProfile.type, "gpu");

  // Over budget with draw calls over budget and a mid CPU share → draw-call.
  const drawBudget = evaluatePerfBudget({ drawCalls: 800, triangles: 100, textures: 4 });
  const draw = classifyBottleneck({
    metrics: frame(30, 34),
    subsystems: subs(12, "vfx"),
    budget: drawBudget,
    targetFrameTimeMs: 16.7,
  });
  assert.equal(draw.type, "draw-call");

  // Within budget, no hitch → unknown ("within budget"); a controller does nothing.
  const fine = classifyBottleneck({ ...base, metrics: frame(15, 18), subsystems: subs(5, "ai") });
  assert.equal(fine.type, "unknown");

  // Over budget but ambiguous CPU share, no probe → unknown (safe small step).
  const ambiguous = classifyBottleneck({ ...base, metrics: frame(30, 34), subsystems: subs(15, "ai") });
  assert.equal(ambiguous.type, "unknown");

  // describeBottleneck is a compact one-liner.
  assert.equal(describeBottleneck(cpu), `cpu (conf ${cpu.confidence.toFixed(2)})`);
});

