check("validateLandscapeData accepts a valid flat heightfield and rejects malformed sidecars", () => {
  const size = { verticesX: 65, verticesZ: 65, spacing: 1, heightScale: 1 };
  const heights = new Array(65 * 65).fill(0);
  const data = validateLandscapeData({
    schema: 1,
    type: "landscape",
    size,
    chunks: { quadsPerChunk: 32 },
    heights,
    layers: [],
  });
  assert.equal(data.schema, 1);
  assert.equal(data.type, "landscape");
  assert.deepEqual(data.size, size);
  assert.equal((data.heights as number[]).length, 65 * 65);

  // Wrong schema/type rejects.
  assert.throws(() =>
    validateLandscapeData({ schema: 2, type: "landscape", size, heights, layers: [] }),
  );
  assert.throws(() =>
    validateLandscapeData({ schema: 1, type: "not-landscape", size, heights, layers: [] }),
  );
  // Grid size outside 65..257 rejects.
  assert.throws(() =>
    validateLandscapeData({
      schema: 1,
      type: "landscape",
      size: { ...size, verticesX: 32 },
      heights: new Array(32 * 65).fill(0),
      layers: [],
    }),
  );
  // Mismatched heights length rejects.
  assert.throws(() =>
    validateLandscapeData({
      schema: 1,
      type: "landscape",
      size,
      heights: heights.slice(0, 10),
      layers: [],
    }),
  );
  // A layer weights array of the wrong length rejects.
  assert.throws(() =>
    validateLandscapeData({
      schema: 1,
      type: "landscape",
      size,
      heights,
      layers: [{ id: "grass", name: "Grass", weights: [0, 1] }],
    }),
  );

  // Missing dataRef path / wrong extension rejects the save payload.
  assert.throws(() =>
    validateSaveLandscapePayload({ path: "landscapes/x.json", landscape: data }),
  );
  const payload = validateSaveLandscapePayload({
    path: "landscapes/landscape-1.landscape.json",
    landscape: data,
  });
  assert.equal(payload.path, "landscapes/landscape-1.landscape.json");
  assert.deepEqual(payload.landscape, data);
});

check("landscape layer material is allowlisted, round-trips, and survives normalization", () => {
  const size = { verticesX: 65, verticesZ: 65, spacing: 1, heightScale: 1 };
  const heights = new Array(65 * 65).fill(0);
  const weights = new Array(65 * 65).fill(0);
  const validated = validateLandscapeData({
    schema: 1,
    type: "landscape",
    size,
    heights,
    layers: [
      { id: "grass", name: "Grass", material: "mat-rocky-soil", weights: weights.map(() => 1) },
      { id: "dirt", name: "Dirt", weights },
    ],
  });
  const layers = validated.layers as Array<Record<string, unknown>>;
  assert.equal(layers[0]!.material, "mat-rocky-soil");
  assert.equal("material" in layers[1]!, false);

  // A non-string, non-null material rejects.
  assert.throws(() =>
    validateLandscapeData({
      schema: 1,
      type: "landscape",
      size,
      heights,
      layers: [{ id: "grass", name: "Grass", material: 5, weights }],
    }),
  );

  // ensureLandscapeLayers backfills the four presets while preserving assignments.
  const data = createFlatLandscapeData("small");
  data.layers[1]!.material = "mat-desert-sand";
  data.layers = [data.layers[1]!, data.layers[0]!]; // reorder to prove id-keyed preservation
  ensureLandscapeLayers(data);
  assert.equal(data.layers.length, 4);
  assert.equal(data.layers.find((layer) => layer.id === "dirt")?.material, "mat-desert-sand");
  assert.equal(data.layers.find((layer) => layer.id === "grass")?.material, undefined);
});

check("createLandscapeColliderPrimitive builds a centered up-facing heightfield trimesh", () => {
  const data = createFlatLandscapeData("small");
  data.size = { verticesX: 3, verticesZ: 3, spacing: 2, heightScale: 1 };
  data.heights = [
    0, 0, 0,
    0, 1, 0,
    0, 0, 0,
  ];
  data.layers = [];
  const primitive = createLandscapeColliderPrimitive(data);
  assert.equal(primitive.shape, "trimesh");
  assert.equal(primitive.vertices.length, 9);
  assert.equal(primitive.indices.length, 24);
  assert.deepEqual(primitive.vertices[0], [-2, 0, -2]);
  assert.deepEqual(primitive.vertices[4], [0, 1, 0]);
  assert.deepEqual(primitive.size, [4, 1, 4]);
  assert.deepEqual(primitive.center, [0, 0.5, 0]);
  assert.deepEqual(primitive.indices.slice(0, 6), [0, 3, 1, 1, 3, 4]);

  const physics = new PhysicsSubsystem();
  physics.setEntities([
    {
      id: "landscape:unit",
      components: {
        Transform: { position: [10, 2, -3], rotation: [0, 0, 0], scale: [1, 1, 1] },
        Collider: {
          shape: "box",
          size: primitive.size,
          center: primitive.center,
          isStatic: true,
          isSensor: false,
          navigationRole: "walkable",
          primitives: [primitive],
        },
      },
    },
  ]);
  assert.equal(physics.staticBlockerAabbs().length, 0, "walkable landscape triangles are not wall blockers");
  const surfaces = physics.staticSurfaceTriangles();
  assert.equal(surfaces.length, 8);
  assert.ok(surfaces.every((surface) => surface.normalY > 0.6), "landscape surfaces are up-facing");
  assert.equal(physics.staticNavigationSurfaceTriangles().length, 8);
});

check("physics subsystem spatially narrows static landscape surface candidates for ground probes", () => {
  const data = createFlatLandscapeData("small");
  data.size = { verticesX: 9, verticesZ: 9, spacing: 1, heightScale: 1 };
  data.heights = new Array(81).fill(0);
  data.layers = [];
  const primitive = createLandscapeColliderPrimitive(data);
  const physics = new PhysicsSubsystem();
  physics.setEntities([
    {
      id: "landscape:spatial-index",
      components: {
        Transform: { position: [0, 0, 0], rotation: [0, 0, 0], scale: [1, 1, 1] },
        Collider: {
          shape: "box",
          size: primitive.size,
          center: primitive.center,
          isStatic: true,
          isSensor: false,
          primitives: [primitive],
        },
      },
    },
  ]);
  const all = physics.staticSurfaceTriangles();
  const near = physics.staticSurfaceTrianglesNear(0, 0);
  assert.equal(all.length, 128);
  assert.ok(near.length > 0 && near.length < all.length, `near candidates=${near.length} all=${all.length}`);
  assert.equal(physics.staticSurfaceTrianglesNear(20, 20).length, 0, "outside the terrain has no candidates");
});

check("resolveBlockingVolume fills defaults and overrides per field", () => {
  assert.deepEqual(resolveBlockingVolume(null), BLOCKING_VOLUME_DEFAULTS);
  const resolved = resolveBlockingVolume({
    id: "bv",
    position: [0, 0, 0],
    brushShape: "cylinder",
    size: [3, 5, 3],
    renderInGame: true,
    color: "#102030",
  });
  assert.equal(resolved.brushShape, "cylinder");
  assert.deepEqual(resolved.size, [3, 5, 3]);
  assert.equal(resolved.brushSides, BLOCKING_VOLUME_DEFAULTS.brushSides);
  assert.equal(resolved.renderInGame, true);
  assert.equal(resolved.color, "#102030");
  // Unset fields fall back to defaults; an invalid shape falls back to box.
  assert.equal(resolved.name, BLOCKING_VOLUME_DEFAULTS.name);
  assert.equal(
    resolveBlockingVolume({ id: "x", position: [0, 0, 0], brushShape: "stairs" as never }).brushShape,
    "box",
  );
  // A cylinder's stored size is canonicalised to [diameter, height, diameter] so
  // the brush and its collider agree; brushSides is clamped to [3, 128].
  const cyl = resolveBlockingVolume({
    id: "c",
    position: [0, 0, 0],
    brushShape: "cylinder",
    size: [4, 9, 7],
    brushSides: 6,
  });
  assert.deepEqual(cyl.size, [4, 9, 4]);
  assert.equal(cyl.brushSides, 6);
  assert.equal(
    resolveBlockingVolume({ id: "s", position: [0, 0, 0], brushShape: "sphere", size: [5, 2, 3] }).size[1],
    5,
  );
  assert.equal(
    resolveBlockingVolume({ id: "n", position: [0, 0, 0], brushShape: "cone", brushSides: 500 }).brushSides,
    128,
  );
});

