// --- Editor↔game DI seam (gameEditorRegistry) --------------------------------
// Guards the inversion that keeps the editor generic: the editor reads game data
// through the injected catalog, never importing @/game. The throw-before-inject
// check must run before the register call below (module-singleton state).

check("gameEditorRegistry throws until the composition root injects a catalog", () => {
  assert.throws(() => getGameEditorCatalog(), /was not registered/);
});

check("GAME_EDITOR_CATALOG satisfies the editor catalog contract once injected", () => {
  setGameEditorCatalog(GAME_EDITOR_CATALOG);
  const catalog = getGameEditorCatalog();
  // Game Modes: the default camera mode leads the World Settings dropdown.
  assert.ok(catalog.gameModeOptions.length >= 1);
  assert.equal(catalog.gameModeOptions[0]?.id, "forge.defaultCamera");
  // Behavior ids offered as Event Binding suggestions.
  assert.ok(catalog.behaviorScriptIds.includes("input-move"));
  // Input helpers resolve real bindings for the Actor Script montage→input panel.
  assert.equal(catalog.formatInputCode("KeyQ"), "Q");
  assert.ok(catalog.keysForAction("jump").includes("Space"));
  // Montage resolver is pure and safe on empty/absent input.
  assert.deepEqual(catalog.resolveMontageBindings(undefined), []);
  assert.deepEqual(catalog.resolveMontageBindings([]), []);

  // Data Table editor: the units balance is registered as an editable table, and
  // its `validate` is the real runtime validator wrapped — null for the shipped
  // file, a field message for a broken edit. This is what stops the editor from
  // ever writing balance the `?rts` boot would reject.
  const unitsTable = catalog.dataTables?.find((table) => table.id === "units")
    ?? assert.fail("units data table is not registered in the editor catalog");
  assert.equal(unitsTable.path, "game-data/balance/units.json");
  assert.equal(
    unitsTable.fields?.find((field) => field.path === "projectileSpeed")?.label,
    "Ok uçuş hızı (birim/sn)",
    "the Archer's visual speed has a Turkish authoring label",
  );
  assert.equal(
    unitsTable.resetEntryDefaults?.archer_placeholder?.projectileSpeed,
    25,
    "reset restores the Archer visual Arrow speed even though git HEAD predates the field",
  );
  const realUnits = JSON.parse(readFileSync("public/game-data/balance/units.json", "utf8")) as unknown;
  assert.equal(unitsTable.validate(realUnits), null, "the shipped units file validates");
  const broken = JSON.parse(JSON.stringify(realUnits)) as Record<string, any>;
  broken.guard_placeholder.maxHealth = -5;
  assert.equal(
    typeof unitsTable.validate(broken),
    "string",
    "an out-of-range edit is refused with a field message, not accepted",
  );

  // Every registered table is wired to the right validator for its own file: the
  // shipped file must validate, which catches a copy-paste that pairs (say) the
  // buildings path with the units validator.
  for (const table of catalog.dataTables ?? []) {
    // The same fence the dev save endpoint applies, asserted at the registration
    // site so a table can never be pointed outside the authoring scope.
    assert.match(table.path, /^game-data\/[a-z-]+\/[a-z-]+\.json$/, `${table.id} path is a game-data file`);
    const real = JSON.parse(readFileSync(`public/${table.path}`, "utf8")) as unknown;
    assert.equal(table.validate(real), null, `the shipped ${table.id} file validates through its registered validator`);
    // A section-scoped table must actually resolve, or the editor would open
    // empty and its field metadata would silently match nothing.
    if (table.section === undefined) continue;
    let cursor: unknown = real;
    for (const key of table.section.split(".")) {
      assert.ok(
        cursor !== null && typeof cursor === "object" && !Array.isArray(cursor),
        `${table.id} section "${table.section}" resolves`,
      );
      cursor = (cursor as Record<string, unknown>)[key];
    }
    assert.ok(
      cursor !== null && typeof cursor === "object" && !Array.isArray(cursor),
      `${table.id} section "${table.section}" is an editable object`,
    );
  }
});

check("the Data Table form groups repeated blocks and never splinters a scalar array", () => {
  // The defect this pins: grouping used to key off any numeric path segment, so
  // an `offset: [x, y, z]` triple rendered as three anonymous "Seviye" blocks and
  // the slot's own name never appeared. A block is a repeated *object* — an array
  // element, or a child of a path the game opted in through `groups`.
  const catalog = getGameEditorCatalog();
  const table = catalog.dataTables?.find((t) => t.id === "rts-damage-defaults")
    ?? assert.fail("rts-damage-defaults is not registered in the editor catalog");
  const content = JSON.parse(readFileSync(`public/${table.path}`, "utf8")) as any;
  const slotsEntry = content.damage.defaults.slots as Record<string, unknown>;
  const blockParents = new Set((table.groups ?? []).map((group) => group.path));

  const groups = partitionLeaves(collectLeaves(slotsEntry, "", "", blockParents));
  // One group per slot, in the file's own order — and nothing else. No group may
  // come from an array index, which is what an `effects`/`offset` split looked like.
  assert.deepEqual(
    groups.map((group) => group.key),
    Object.keys(slotsEntry),
    "each damage slot is one block; the arrays inside them are not",
  );
  for (const group of groups) {
    assert.equal(group.index, -1, `${group.key} is an object block, not an array element`);
    assert.ok(!group.isBase, `${group.key} is a real block`);
  }

  // Every slot is titled by the name an author reads, never a raw key or a level.
  const meta = (table.groups ?? []).find((group) => group.path === "");
  for (const group of groups) {
    const title = groupTitle(slotsEntry, group, meta);
    assert.ok(title.length > 0 && !title.includes("Seviye"), `${group.key} is titled, not levelled`);
    assert.equal(title, meta?.keyLabels?.[group.childKey], `${group.key} uses its authored label`);
  }

  // The offset triple stays inside its slot and its members are told apart, so
  // three number boxes are never left carrying one identical caption.
  const fields = new Map((table.fields ?? []).map((field) => [field.path, field]));
  const first = groups[0] ?? assert.fail("no damage slot groups");
  const offsets = first.leaves.filter((leaf) => leaf.path.includes("anchor.offset"));
  assert.equal(offsets.length, 3, "the anchor offset is x/y/z, all in the slot's own block");
  assert.deepEqual(
    offsets.map((leaf) => leafLabel(leaf, fields.get(templatePath(leaf.path)))),
    ["Kayma — X", "Kayma — Y", "Kayma — Z"],
  );

  // The tier case the grouping was built for still holds: an array of objects
  // groups per element and reads as a level.
  const buildings = catalog.dataTables?.find((t) => t.id === "buildings")
    ?? assert.fail("buildings data table is not registered");
  const buildingsDoc = JSON.parse(readFileSync(`public/${buildings.path}`, "utf8")) as any;
  const entryId = Object.keys(buildingsDoc).find((id) =>
    Array.isArray(buildingsDoc[id]?.progression?.settlement)
  ) ?? assert.fail("no building entry carries a settlement progression");
  const entry = buildingsDoc[entryId] as Record<string, unknown>;
  const tierGroups = partitionLeaves(
    collectLeaves(entry, "", "", new Set((buildings.groups ?? []).map((group) => group.path))),
  ).filter((group) => group.containerPath === "progression.settlement");
  assert.ok(tierGroups.length >= 1, "settlement tiers still group per element");
  const tierMeta = (buildings.groups ?? []).find((group) => group.path === "progression.settlement");
  assert.match(groupTitle(entry, tierGroups[0]!, tierMeta), /^Yerleşim çağı — Seviye \d+$/);
});

check("the damage tables pick effects from the manifest, list-wise", () => {
  // What this pins: an `effects` entry is a *picker over the whole array*, not a
  // text box per existing index. Typed ids were the failure mode — an author had
  // to recall `rts-fx-collapse-dust` exactly — and an index-wise field left a
  // slot the file ships empty with no row at all, so it could not be filled from
  // the editor. Both follow from the field naming the array and carrying
  // `assetOptions`; the runtime rule that the id must resolve is checked
  // separately (`rtsDamageEffectGaps`).
  const catalog = getGameEditorCatalog();
  const tables = (catalog.dataTables ?? []).filter((table) => table.id.startsWith("rts-damage-"));
  assert.ok(tables.length >= 1, "the damage tables are registered in the editor catalog");
  for (const table of tables) {
    const effectFields = (table.fields ?? []).filter((field) => field.path.endsWith(".effects"));
    assert.equal(
      effectFields.length,
      RTS_DAMAGE_SLOTS.length,
      `${table.id} names an effects field for every damage slot`,
    );
    for (const field of effectFields) {
      assert.equal(field.assetOptions, "effect", `${table.id}:${field.path} picks effect assets`);
      assert.ok(!field.path.includes("[]"), `${table.id}:${field.path} names the array, not its indices`);
    }
  }

  // Walked the way the editor walks it: one list leaf per slot, pointing at the
  // array itself — and the anchor offset still splinters into its three numbers,
  // so opting one array into list editing never swallows the others.
  const defaults = tables.find((table) => table.id === "rts-damage-defaults")
    ?? assert.fail("rts-damage-defaults is not registered in the editor catalog");
  const content = JSON.parse(readFileSync(`public/${defaults.path}`, "utf8")) as any;
  const slotsEntry = content.damage.defaults.slots as Record<string, unknown>;
  const listPaths = new Set(
    (defaults.fields ?? []).filter((field) => field.assetOptions).map((field) => field.path),
  );
  const leaves = collectLeaves(
    slotsEntry,
    "",
    "",
    new Set((defaults.groups ?? []).map((group) => group.path)),
    listPaths,
  );
  assert.deepEqual(
    leaves.filter((leaf) => leaf.type === "stringList").map((leaf) => leaf.path),
    RTS_DAMAGE_SLOTS.map((slot) => `${slot}.effects`),
    "every slot's effects render as one list, in slot order",
  );
  for (const leaf of leaves.filter((entry) => entry.type === "stringList")) {
    const array = (leaf.container as Record<string, unknown>)[leaf.key as string];
    assert.ok(Array.isArray(array), `${leaf.path} points at the array the widget mutates`);
  }
  assert.equal(
    leaves.filter((leaf) => leaf.path.startsWith(`${RTS_DAMAGE_SLOTS[0]}.anchor.offset`)).length,
    3,
    "the offset triple is still three numbered fields",
  );

  // An empty list keeps its leaf — that row is the only way to fill a slot the
  // file ships silent, which is exactly the case an index-wise field lost.
  const emptyLeaves = collectLeaves(
    { ruinSmoke: { effects: [] } },
    "",
    "",
    new Set([""]),
    new Set(["ruinSmoke.effects"]),
  );
  assert.deepEqual(
    emptyLeaves.map((leaf) => [leaf.path, leaf.type]),
    [["ruinSmoke.effects", "stringList"]],
  );
});

check("validateSaveGameDataPayload fences writes to game-data JSON and rejects the rest", () => {
  // The dev endpoint's guard is generic on purpose: path scope + a keyed object,
  // no balance rules (those ride on the injected validator above and the runtime
  // loader). Accepts a real balance path; refuses escapes and non-objects.
  const ok = validateSaveGameDataPayload({ path: "game-data/balance/units.json", data: { a: {} } });
  assert.equal(ok.path, "game-data/balance/units.json");
  assert.deepEqual(ok.data, { a: {} });
  // A leading slash is normalised rather than rejected.
  assert.equal(
    validateSaveGameDataPayload({ path: "/game-data/balance/units.json", data: {} }).path,
    "game-data/balance/units.json",
  );
  for (const bad of [
    { path: "src/main.ts", data: {} },
    { path: "game-data/../secret.json", data: {} },
    { path: "game-data/balance/units.json", data: [] },
    { path: "game-data/balance/units.json", data: "x" },
    { path: 42, data: {} },
    null,
  ]) {
    assert.throws(() => validateSaveGameDataPayload(bad), /gameData payload/);
  }
});

// Runtime `?debug` snapshot builders (P2.5): pure, side-effect-free, so the
// null-branching + default-fallback logic is exercised without a live scene.
check("buildPerfMemorySnapshot passes render memory through and reads the JS heap", () => {
  const render = { geometries: 3, textures: 4, programs: 2 } as unknown as Parameters<
    typeof buildPerfMemorySnapshot
  >[0];
  const snapshot = buildPerfMemorySnapshot(render);
  assert.equal(snapshot.render, render);
  // performance.memory is Chrome-only; under node it is absent → null heap fields.
  const hasPerfMemory =
    typeof performance !== "undefined" &&
    typeof (performance as { memory?: unknown }).memory !== "undefined";
  if (!hasPerfMemory) {
    assert.equal(snapshot.jsHeapBytes, null);
    assert.equal(snapshot.jsHeapLimitBytes, null);
  }
});

