  assert.equal(formatInventoryAmount(78.34832000000674), 78);
  assert.equal(formatInventoryAmount(67.321711111104), 67);
  assert.equal(formatInventoryAmount(0.99), 0);
  assert.equal(formatInventoryAmount(Number.NaN), 0);
