check("RTS resource costs read in HUD order and name every resource (plan §51)", () => {
  // Costs arrive in whatever order the JSON author wrote them; the player reads
  // them next to a HUD bar that is always food-wood-stone-gold.
  assert.equal(
    formatResourceCost({ gold: 20, food: 50, stone: 10 }),
    "50 Yiyecek · 10 Taş · 20 Altın",
  );
  // A zero is not a cost; printing "0 Altın" invents a requirement.
  assert.equal(formatResourceCost({ food: 50, gold: 0 }), "50 Yiyecek");
  assert.equal(formatResourceCost({}), "Ücretsiz");
  // An unlabelled resource stays visible rather than vanishing from a cost line.
  assert.equal(formatResourceCost({ mythril: 5 }), "5 mythril");
  assert.equal(resourceLabel("stone"), "Taş");
});

check("RTS notifications refresh rather than stack, and mute after expiry (plan §52)", () => {
  const notifications = new RtsNotificationCenter();

  // §52 "Aynı uyarı sürekli spam oluşturmuyor": population-full is a *polled*
  // condition, so RtsApp posts it on every tick it holds. One line, not sixty.
  assert.equal(notifications.post({ kind: "population-full", text: "Nüfus dolu" }), "posted");
  for (let tick = 0; tick < 60; tick += 1) {
    notifications.advance(1 / 60);
    assert.equal(notifications.post({ kind: "population-full", text: "Nüfus dolu" }), "refreshed");
  }
  assert.equal(notifications.active().length, 1, "a re-posted live notice never stacks");
  // A refresh is not a raise. Counting refreshes made a single unroaded farm
  // read "×378" in a real match — the tick rate, not anything the player did.
  assert.equal(notifications.active()[0]?.raises, 1, "61 refreshes are still the first raise");

  // A refreshed notice does not expire while the condition holds: the notice
  // disappearing is what tells the player the problem is gone.
  notifications.advance(5);
  assert.equal(notifications.active().length, 1, "still true, still shown");
  notifications.advance(2);
  assert.equal(notifications.active().length, 0, "nothing refreshed it, so it retired");

  // Expiry arms a cooldown: a condition flickering across the boundary must not
  // re-post forever. population-full mutes for 20s.
  assert.equal(notifications.post({ kind: "population-full", text: "Nüfus dolu" }), "suppressed");
  notifications.advance(19);
  assert.equal(notifications.post({ kind: "population-full", text: "Nüfus dolu" }), "suppressed");
  notifications.advance(2);
  assert.equal(
    notifications.post({ kind: "population-full", text: "Nüfus dolu" }),
    "posted",
    "once the cooldown lapses the player is told again",
  );
  // *This* is what the counter is for: the same problem raised a second time,
  // which is a recurring failure rather than a busy simulation tick.
  assert.equal(notifications.active()[0]?.raises, 2, "history survives expiry and the cooldown");
});

check("RTS notifications separate subjects and bound the feed (plan §51/§52)", () => {
  const notifications = new RtsNotificationCenter();

  // Depleted stone and depleted gold are two decisions, not one repeat.
  assert.equal(
    notifications.post({ kind: "resource-depleted", subject: "stone", text: "Taş bitti" }),
    "posted",
  );
  assert.equal(
    notifications.post({ kind: "resource-depleted", subject: "gold", text: "Altın bitti" }),
    "posted",
  );
  assert.equal(notifications.active().length, 2);
  // ...but the same subject twice still collapses.
  assert.equal(
    notifications.post({ kind: "resource-depleted", subject: "stone", text: "Taş bitti" }),
    "refreshed",
  );
  assert.equal(notifications.active().length, 2);

  // §52 "UI haritanın kritik alanlarını aşırı kapatmıyor": the feed is a corner
  // overlay, so it drops the oldest instead of growing down over the map.
  for (const structureId of ["1", "2", "3", "4"]) {
    notifications.post({ kind: "logistics-cut", subject: structureId, text: `Kesildi ${structureId}` });
  }
  const active = notifications.active();
  assert.equal(active.length, MAX_ACTIVE_NOTIFICATIONS);
  assert.deepEqual(
    active.map((entry) => entry.text),
    ["Kesildi 1", "Kesildi 2", "Kesildi 3", "Kesildi 4"],
    "the oldest notices are the ones the player has had longest to read",
  );

  // Severity is data, not a caller's choice: the feed colours an alert from the
  // kind alone, so a "logistics cut" can never be posted as a friendly info.
  assert.equal(active[0]?.severity, "alert");

  // A restart is a new match: no carried cooldown, no carried raise history,
  // nothing left on screen. A fresh match's first cut is "×1", not "×2".
  notifications.reset();
  assert.equal(notifications.active().length, 0);
  assert.equal(notifications.post({ kind: "logistics-cut", subject: "1", text: "Kesildi" }), "posted");
  assert.equal(notifications.active()[0]?.raises, 1);

  assert.throws(() => notifications.advance(-1), RangeError);
});

check("RTS a restored logistics link clears its cut warning at once and reads as good news (plan §51/§52)", () => {
  const notifications = new RtsNotificationCenter();

  // A producer's road-to-depot link is severed: the alert is raised.
  assert.equal(
    notifications.post({ kind: "logistics-cut", subject: "7", text: "Odun üretimi durdu" }),
    "posted",
  );
  assert.equal(notifications.active()[0]?.severity, "alert", "a cut is red");

  // The player builds the connecting depot. The warning must leave immediately,
  // not linger for its full display time beside the recovery notice.
  assert.equal(notifications.dismiss({ kind: "logistics-cut", subject: "7" }), true);
  assert.equal(notifications.active().length, 0, "the stale warning is gone the moment the link returns");
  assert.equal(notifications.dismiss({ kind: "logistics-cut", subject: "7" }), false, "nothing left to dismiss");

  // The recovery is its own subject-keyed, info-severity (green) notice.
  assert.equal(
    notifications.post({ kind: "logistics-restored", subject: "7", text: "Odun lojistiği bağlandı" }),
    "posted",
  );
  const restored = notifications.active()[0] ?? assert.fail("recovery notice missing");
  assert.equal(restored.severity, "info", "a restored link is green, not a fresh warning");
  assert.equal(restored.kind, "logistics-restored");

  // Dismiss applies no cooldown: if the very next check finds the link cut again,
  // the player is warned again rather than muted — and it counts as a repeat.
  assert.equal(
    notifications.post({ kind: "logistics-cut", subject: "7", text: "Odun üretimi yine durdu" }),
    "posted",
    "a re-cut right after a dismiss is not swallowed",
  );
  assert.equal(notifications.active().find((entry) => entry.kind === "logistics-cut")?.raises, 2, "the re-cut counts as a repeat");
});

check("RTS command answers keep one line per family and never mute a second press", () => {
  const notifications = new RtsNotificationCenter();

  // These used to live on the build palette's message line, which put "Muhafız
  // siparişi iptal edildi" under a panel about placing buildings. Here they are
  // keyed by command family, so a burst of orders in one family replaces its own
  // line rather than evicting the feed's other four notices.
  assert.equal(notifications.post({ kind: "command", subject: "production", text: "Muhafız kuyruğa alındı (1/5)." }), "posted");
  assert.equal(notifications.post({ kind: "command", subject: "production", text: "Muhafız kuyruğa alındı (2/5)." }), "refreshed");
  assert.equal(notifications.active().length, 1, "five Üret presses are one line, not five");
  assert.equal(notifications.active()[0]?.text, "Muhafız kuyruğa alındı (2/5).", "and the line is the latest answer");
  assert.equal(notifications.active()[0]?.severity, "info");

  // A refusal is its own line and its own colour, so "kuyruk dolu" cannot be
  // mistaken for a confirmation at a glance.
  assert.equal(notifications.post({ kind: "command-refused", subject: "production", text: "Kuyruk dolu (5/5)." }), "posted");
  const refused = notifications.active().find((entry) => entry.kind === "command-refused") ?? assert.fail("refusal missing");
  assert.equal(refused.severity, "warning");

  // Another family is a different problem and keeps its own line.
  assert.equal(notifications.post({ kind: "command-refused", subject: "trade", text: "Altın yetersiz." }), "posted");
  assert.equal(notifications.active().length, 3);

  // No cooldown: an answer the player asked for twice must arrive twice, even
  // across an expiry — a muted second press would read as a dead button.
  notifications.advance(10);
  assert.equal(notifications.active().length, 0, "command answers are short-lived");
  assert.equal(notifications.post({ kind: "command", subject: "production", text: "Muhafız kuyruğa alındı (1/5)." }), "posted");
  assert.equal(notifications.active()[0]?.raises, 2, "and the repeat is counted, not swallowed");
});

check("RTS attack watch reports health losses, not placements or rebuilds (plan §51)", () => {
  const watch = new RtsAttackWatch();

  // First sight is a baseline: placing a building is not damage to it.
  assert.deepEqual(watch.observe([{ id: "center", health: 300 }]), []);
  assert.deepEqual(watch.observe([{ id: "center", health: 300 }]), [], "an untouched centre is silent");
  assert.deepEqual(watch.observe([{ id: "center", health: 288 }]), ["center"]);
  // Still damaged is not still *being* damaged — the notice must be able to end.
  assert.deepEqual(watch.observe([{ id: "center", health: 288 }]), []);
  // Repairs and upgrades raise health; neither is an attack.
  assert.deepEqual(watch.observe([{ id: "center", health: 300 }]), []);

  // Two outposts under attack are two places the player must choose between.
  watch.observe([{ id: "outpost:1", health: 100 }, { id: "outpost:2", health: 100 }]);
  assert.deepEqual(
    watch.observe([{ id: "outpost:1", health: 90 }, { id: "outpost:2", health: 80 }]),
    ["outpost:1", "outpost:2"],
  );

  // A destroyed structure's baseline must not survive it: ids are reused, and a
  // stale 90 would make a freshly rebuilt outpost read as already under attack.
  assert.deepEqual(watch.observe([{ id: "outpost:2", health: 80 }]), [], "outpost:1 is gone");
  assert.deepEqual(
    watch.observe([{ id: "outpost:1", health: 100 }, { id: "outpost:2", health: 80 }]),
    [],
    "the rebuilt outpost starts a fresh baseline rather than reporting damage",
  );

  watch.reset();
  assert.deepEqual(watch.observe([{ id: "center", health: 1 }]), [], "a reset watch re-baselines");
});

check("the shipped preset loads and startingTier stays validated", () => {
  const proof = validateGamePreset(readPresetJson("gameplay_proof"), "gameplay_proof");
  assert.equal(proof.id, "gameplay_proof");
  // The shipped default since `core_match` was retired, so its opening stockpile
  // is what every unqualified `/?rts` boot plays — and what the story tur's own
  // budget invariant is measured against.
  assert.equal(proof.flags.prosperity ?? false, false, "the shipped default keeps optional prosperity disabled");
  assert.ok((proof.startingResources?.gold ?? 0) > 0, "the tur's Market step needs gold to trade with");
  assert.ok(proof.gameSpeed > 0, "a preset must name a real-time-or-faster sim speed");
  // A shipped balance preset must never carry the handicap.
  assert.equal(proof.startingTier, undefined);

  // `startingTier` no longer has a preset on disk that uses it (the `siege_test`
  // and `debug_fast` scratch scenarios were retired once they stopped being
  // played), but the field is still read by the boot path, so its validation is
  // pinned against a literal rather than a file. Dropping the checks with the
  // files would leave the next preset that opens past Settlement unguarded.
  const base = readPresetJson("gameplay_proof") as object;
  assert.deepEqual(
    validateGamePreset({ ...base, startingTier: { age: "town", level: 1 } }, "gameplay_proof").startingTier,
    { age: "town", level: 1 },
    "a fully stated opening tier survives validation",
  );
  assert.throws(
    () => validateGamePreset({ ...base, startingTier: { age: "town" } }),
    GameDataError,
    "a half-stated tier would pick a level for the author",
  );
  assert.throws(
    () => validateGamePreset({ ...base, startingTier: { age: "town", level: 4 } }),
    GameDataError,
    "there are six playable tiers, not seven",
  );
  assert.throws(
    () => validateGamePreset({ ...base, startingTier: { age: "empire", level: 1 } }),
    GameDataError,
    "an unknown age must not slip in through a test preset",
  );
});

check("preset startingUnits carries every playable unit count through validation", () => {
  // `validateStartingUnits` copies an allowlist of keys, so an opening-force
  // role it does not name is dropped without a word — the preset would boot
  // looking correct and simply field no unit. Pin the whole roster, not
  // any one preset's magnitude, so tuning stays free.
  const base = readPresetJson("gameplay_proof") as object;
  const parsed = validateGamePreset(
    { ...base, startingUnits: { guard: 1, worker: 1, archer: 1, siege: 1 } },
    "gameplay_proof",
  );
  assert.deepEqual(
    parsed.startingUnits,
    { guard: 1, worker: 1, archer: 1, siege: 1 },
    "every opening-force role survives validation",
  );

  // Absent means "none", which keeps a normal preset from inheriting ranged
  // units or artillery.
  const none = validateGamePreset({ ...base, startingUnits: { guard: 1 } }, "gameplay_proof");
  assert.equal(none.startingUnits.archer, undefined);
  assert.equal(none.startingUnits.siege, undefined);

  for (const bad of [-1, 1.5, "2"]) {
    assert.throws(
      () => validateGamePreset({ ...base, startingUnits: { archer: bad } }, "gameplay_proof"),
      GameDataError,
      `an archer count of ${JSON.stringify(bad)} must be refused, not rounded`,
    );
  }
});

