check("RTS single-click selects one unit and double-click selects every matching type", () => {
  const units = new UnitSystem();
  const guards = [
    units.spawn("player", -3, 0, RTS_TEST_UNIT_STATS),
    units.spawn("player", -1, 0, RTS_TEST_UNIT_STATS),
  ];
  // A second unit sharing `role: "guard"`. Double-click must not sweep it up
  // with the plain Guards: the gesture is the in-world twin of clicking that
  // unit's HUD chip, and the two disagreeing would make one of them a trap.
  const heavyGuardStats = { ...RTS_TEST_UNIT_STATS, id: "heavy_guard", label: "Ağır Muhafız" } as const;
  const heavyGuards = [
    units.spawn("player", -3, 6, heavyGuardStats),
    units.spawn("player", -1, 6, heavyGuardStats),
  ];
  const archers = [
    units.spawn("player", 1, 0, RTS_TEST_ARCHER_STATS),
    units.spawn("player", 3, 0, RTS_TEST_ARCHER_STATS),
  ];
  const rams = [
    units.spawn("player", -2, -4, RTS_TEST_SIEGE_STATS),
    units.spawn("player", 2, -4, RTS_TEST_SIEGE_STATS),
  ];
  const workers = [
    units.spawn("player", -2, 4, RTS_TEST_WORKER_STATS),
    units.spawn("player", 2, 4, RTS_TEST_WORKER_STATS),
  ];
  units.spawn("enemy", -5, 0, RTS_TEST_UNIT_STATS);
  units.root.updateMatrixWorld(true);

  const camera = new PerspectiveCamera(60, 1, 0.1, 100);
  camera.position.set(0, 12, 14);
  camera.lookAt(0, 0, 0);
  camera.updateMatrixWorld(true);
  const canvas = { clientWidth: 100, clientHeight: 100 } as HTMLCanvasElement;
  const marquee = { show: () => {}, hide: () => {} } as unknown as MarqueeOverlay;
  const selection = new SelectionSystem(
    canvas,
    camera,
    units,
    marquee,
    new PlacedStructureSystem(),
    new CommandCenterSystem(),
  );
  const screenPointFor = (unit: Unit) => {
    const projected = new Vector3(unit.position.x, 1, unit.position.z).project(camera);
    return { x: (projected.x * 0.5 + 0.5) * 100, y: (-projected.y * 0.5 + 0.5) * 100 };
  };

  for (const group of [guards, archers, rams, heavyGuards]) {
    const point = screenPointFor(group[0]!);
    selection.onSelectDoubleClick(point.x, point.y, false);
    assert.deepEqual(
      new Set(selection.selected()),
      new Set(group),
      "a double-click selects that unit's type and stops there",
    );
  }

  const workerPoint = screenPointFor(workers[0]!);
  selection.onSelectClick(workerPoint.x, workerPoint.y, false);
  assert.deepEqual(new Set(selection.selected()), new Set([workers[0]]), "a worker click selects only that worker");
  selection.onSelectDoubleClick(workerPoint.x, workerPoint.y, false);
  assert.deepEqual(new Set(selection.selected()), new Set(workers), "a worker double-click selects the whole worker line");
});

check("RTS health clamps damage and healing while exposing current/max/ratio", () => {
  const health = new HealthComponent(100);
  assert.equal(health.current, 100);
  assert.equal(health.max, 100);
  assert.equal(health.ratio, 1);
  assert.equal(health.depleted, false);

  const hit = health.damage(35);
  assert.deepEqual(hit, { applied: 35, previous: 100, current: 65, depleted: false });
  assert.equal(health.ratio, 0.65);

  const lethal = health.damage(100);
  assert.deepEqual(lethal, { applied: 65, previous: 65, current: 0, depleted: true });
  assert.equal(health.depleted, true);

  const healed = health.heal(200);
  assert.deepEqual(healed, { applied: 100, previous: 0, current: 100, depleted: false });
  assert.throws(() => health.damage(-1), RangeError);
  assert.throws(() => new HealthComponent(0), RangeError);

  // upgradeMax carries current health up by the *delta*, so the damage already
  // taken is preserved as an absolute figure (30 down before, 30 down after);
  // setMax may lower and clamps instead. Raising the ceiling alone would make an
  // undamaged 700/700 building read as 700/1000 — see health.ts.
  health.damage(30);
  health.upgradeMax(160);
  assert.deepEqual([health.current, health.max], [130, 160], "a raised ceiling keeps the damage already taken, not the ratio");
  assert.throws(() => health.upgradeMax(150), RangeError, "upgradeMax refuses to lower the maximum");
  health.setMax(50);
  assert.deepEqual([health.current, health.max], [50, 50], "setMax lowers the ceiling and clamps current into range");
  health.setMax(120);
  assert.deepEqual([health.current, health.max], [50, 120], "raising the ceiling again does not heal");
  assert.throws(() => health.setMax(0), RangeError);
});

check("RTS structure damage presentation uses the authored 66/31/0 health thresholds", () => {
  assert.equal(structureDamageStage(1), "normal");
  assert.equal(structureDamageStage(0.66), "normal", "66% remains normal");
  assert.equal(structureDamageStage(0.659), "light", "65% enters light damage");
  assert.equal(structureDamageStage(0.31), "light", "31% remains light damage");
  assert.equal(structureDamageStage(0.3), "heavy", "30% enters heavy damage");
  assert.equal(structureDamageStage(0.001), "heavy");
  assert.equal(structureDamageStage(0), "destroyed");
});

check("RTS structure damage presentation emits each health transition once and signals collapse", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const house = buildings.house ?? assert.fail("house balance missing");
  const structures = new PlacedStructureSystem();
  const structure = structures.place("player", house, 0, 0);
  structures.advanceConstruction(structure, house.constructionSeconds);
  const stages: string[] = [];
  let collapseCount = 0;
  structures.setDamagePresentationHandler({
    onDamageStageChanged: (_structure, previous, next) => stages.push(`${previous}->${next}`),
    onCollapse: () => { collapseCount += 1; },
  });

  structures.updateVisualAnimations(0);
  structure.health.damage(structure.health.max * 0.35);
  structures.updateVisualAnimations(0.1);
  structures.updateVisualAnimations(0.1);
  structure.health.damage(structure.health.max * 0.35);
  structures.updateVisualAnimations(0.1);
  assert.deepEqual(stages, ["normal->light", "light->heavy"]);

  structure.health.damage(structure.health.max);
  updateStructureDestruction(structures);
  assert.equal(collapseCount, 1, "the visual collapse is announced exactly once");
  structures.clear();
});

check("RTS structure collapse keeps an opaque, non-blocking ruin after the fall", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const house = buildings.house ?? assert.fail("house balance missing");
  const structures = new PlacedStructureSystem();
  const structure = structures.place("player", house, 0, 0);
  structures.advanceConstruction(structure, house.constructionSeconds);

  assert.equal(structures.destroy(structure), true);
  assert.equal(structures.all().includes(structure), false, "gameplay releases the structure immediately");
  structures.updateVisualAnimations(1);

  assert.equal(structure.object.parent, structures.root, "the fallen visual remains as a ruin");
  assert.equal(structure.object.position.y, 0, "the ruin does not sink beneath the ground");
  assert.ok(Math.abs(structure.object.rotation.z) > 0.1, "the shared collapse leaves a visible tilt");
  structures.clear();
  assert.equal(structure.object.parent, null, "match cleanup disposes the presentation-only ruin");
});

check("RTS collapse style comes from the damage table, not from the structure system", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const farm = buildings.farm ?? assert.fail("farm balance missing");
  const outpost = buildings.outpost ?? assert.fail("outpost balance missing");
  const structures = new PlacedStructureSystem();
  // Authored here rather than read out of `rts-content.json`. The contract is
  // that the *table* decides the husk's motion, and the table is meant to be
  // retuned — pinning which shipped building is currently authored `inPlace`
  // would turn an ordinary authoring pass into a red build. The style→motion
  // wiring is the invariant; the assignment is content.
  const authoredStyle: Readonly<Record<string, RtsCollapseStyle>> = {
    [farm.id]: "inPlace",
    [outpost.id]: "topple",
  };
  structures.setDamagePresentationHandler({
    collapsesInPlace: (structure) => authoredStyle[structure.stats.id] === "inPlace",
  });

  const field = structures.place("player", farm, 0, 0);
  const tower = structures.place("player", outpost, 20, 0);
  structures.advanceConstruction(field, farm.constructionSeconds);
  structures.advanceConstruction(tower, outpost.constructionSeconds);
  const uprightRotation = field.object.rotation.z;

  structures.destroy(field);
  structures.destroy(tower);
  structures.updateVisualAnimations(1);

  assert.equal(
    field.object.rotation.z,
    uprightRotation,
    "an inPlace building ends its collapse upright, with no residual tilt",
  );
  assert.ok(Math.abs(tower.object.rotation.z) > 0.1, "a topple building still falls");
  assert.equal(field.object.position.y, 0, "collapsing in place never sinks the husk");
  structures.clear();

  // With no handler at all — a fork that ships no content catalog — every
  // building takes the shared topple rather than silently freezing upright.
  const bare = new PlacedStructureSystem();
  const unmanaged = bare.place("player", farm, 0, 0);
  bare.advanceConstruction(unmanaged, farm.constructionSeconds);
  bare.destroy(unmanaged);
  bare.updateVisualAnimations(1);
  assert.ok(Math.abs(unmanaged.object.rotation.z) > 0.1, "the default is to topple");
  bare.clear();
});

/**
 * Run a material's `onBeforeCompile` against a stub of three's shader object, so
 * the deformation patch's uniforms can be inspected without a GL context. An
 * unpatched material runs the prototype no-op and leaves the stub empty, which
 * is what makes "this material is not patched" assertable.
 */
function compileStructureDeformPatch(material: Material): {
  uniforms: Record<string, unknown>;
  vertexShader: string;
} {
  const shader = {
    uniforms: {} as Record<string, unknown>,
    vertexShader: ["void main() {", "#include <beginnormal_vertex>", "#include <begin_vertex>", "}"].join("\n"),
    fragmentShader: "void main() {}",
  };
  (material.onBeforeCompile as unknown as (s: unknown, r: unknown) => void)(shader, undefined);
  return shader;
}

/** Every mesh material under an object, flattened, in traversal order. */
function structureVisualMaterials(root: Object3D): Material[] {
  const materials: Material[] = [];
  root.traverse((child) => {
    if (!(child instanceof Mesh)) return;
    for (const material of Array.isArray(child.material) ? child.material : [child.material]) {
      materials.push(material);
    }
  });
  return materials;
}

check("RTS collapse staggers by height, so a single-material baked model still comes down as a structure", () => {
  // The stagger used to be a per-mesh lookup on the material name, which went
  // silent the moment a building shipped as one baked mesh named "material.007".
  // The contract now is a ramp: the top of a building gives way earlier and
  // further than its base, evaluated per vertex.
  assert.ok(
    HEIGHT_RESPONSE.topDelay < HEIGHT_RESPONSE.baseDelay,
    "the upper structure starts moving before the mass under it",
  );
  assert.ok(
    HEIGHT_RESPONSE.topGive > HEIGHT_RESPONSE.baseGive,
    "and gives way further once it does",
  );
  assert.ok(HEIGHT_RESPONSE.baseGive > 0, "the base still compresses rather than standing rigid");

  // Vertices must not overtake each other: the top is compressed by `give`
  // against the height beneath it, and past this ratio the ramp folds the model
  // through itself. Resolved per building rather than read off the defaults, so
  // a per-building override cannot slip past, and derived from the same
  // constants the shader reads, so retuning either side stays green while safe.
  const catalog = shippedRtsContentCatalog();
  const buildingIds = Object.keys(catalog.buildings);
  assert.ok(buildingIds.length > 0, "the catalog maps buildings to check");
  for (const buildingId of buildingIds) {
    const squash = rtsBuildingDamagePresentation(catalog, buildingId).collapseDeformation.squash;
    assert.ok(
      squash < MAX_SAFE_SQUASH,
      `${buildingId}: collapse squash ${squash} must stay under ${MAX_SAFE_SQUASH} or the ramp inverts the model`,
    );
  }
});

check("RTS collapse response no longer depends on what a model's materials are called", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const house = buildings.house ?? assert.fail("house balance missing");
  const structures = new PlacedStructureSystem();
  const structure = structures.place("player", house, 0, 0);
  structures.advanceConstruction(structure, house.constructionSeconds);
  const visual = structure.object.getObjectByName("rts-complete-building-placeholder")
    ?? assert.fail("the completed visual is missing");

  // Rename the materials to the two extremes the old classifier cared about. If
  // anything still reads the name, these two husks get different responses.
  const materials = structureVisualMaterials(visual);
  assert.ok(materials.length > 0, "the building has materials to rename");
  materials.forEach((material, index) => {
    material.name = index % 2 === 0 ? "Wood" : "Stone";
  });

  structures.destroy(structure);
  const responses = structureVisualMaterials(visual).map((material) => {
    const uniform = compileStructureDeformPatch(material).uniforms.rtsDeformResponse as {
      value: { x: number; y: number; z: number; w: number };
    };
    return `${uniform.value.x},${uniform.value.y},${uniform.value.z},${uniform.value.w}`;
  });
  structures.clear();

  assert.equal(
    new Set(responses).size,
    1,
    `every material of one husk carries the same height ramp, got ${[...new Set(responses)].join(" | ")}`,
  );
  assert.equal(
    responses[0],
    `${HEIGHT_RESPONSE.baseDelay},${HEIGHT_RESPONSE.topDelay},${HEIGHT_RESPONSE.baseGive},${HEIGHT_RESPONSE.topGive}`,
    "and it is the authored ramp, in base-then-top order",
  );
});

check("RTS wildlife sidecars name clips the shipped animal models actually carry", () => {
  // Two rig families ship under Animals/ and their clip names differ in *case*
  // as well as in meaning — the ungulates carry `Jump_toIdle` / `Idle_Headlow`,
  // the canines `Jump_ToIdle` / `Idle_2_HeadLow`, and only the canines have a
  // bare `Attack`. A sidecar copied from the wrong family resolves to nothing,
  // and an animal whose clip never resolves stands frozen in its bind pose
  // rather than erroring. That is the silent failure this pins.
  const directory = "public/assets/ThreeAges/Animals";
  const sidecars = readdirSync(directory).filter((name) => name.endsWith(".skeleton.json"));
  assert.ok(sidecars.length > 0, "at least one animal skeleton sidecar is authored");

  for (const sidecarName of sidecars) {
    const modelName = sidecarName.replace(/\.skeleton\.json$/, ".gltf");
    const model = JSON.parse(
      readFileSync(`${directory}/${modelName}`, "utf8"),
    ) as { animations?: { name?: string }[] };
    const shipped = new Set((model.animations ?? []).map((clip) => clip.name ?? ""));
    assert.ok(shipped.size > 0, `${modelName} ships animation clips`);

    const skeleton = normalizeAssetSkeleton(
      JSON.parse(readFileSync(`${directory}/${sidecarName}`, "utf8")),
    );
    for (const clip of skeletonClipNames(skeleton)) {
      assert.ok(shipped.has(clip), `${sidecarName}: "${clip}" is a clip ${modelName} actually ships`);
    }

    // The six roles `classifyRtsAnimation` can return. An unmapped role falls
    // back silently, so a hunted deer would die standing up or graze mid-stride.
    for (const role of ["idle", "walk", "run", "work", "attack", "death"] as const) {
      assert.ok(skeleton.animationSet[role], `${sidecarName}: RTS role "${role}" is mapped`);
    }
  }

  // The naming convention is the only thing pairing a model with its sidecar.
  assert.equal(
    skeletonSidecarPath("assets/ThreeAges/Animals/Deer.gltf"),
    "assets/ThreeAges/Animals/Deer.skeleton.json",
  );
});

const shippedAnimalBalance = () => validateAnimalBalance(
  JSON.parse(readFileSync("public/game-data/balance/animals.json", "utf8")) as unknown,
);

check("V3 Faz 2: fear is typed by what an animal is, not by who is nearby", () => {
  const animals = shippedAnimalBalance();
  // One den and one deer herd, close enough that the wolves are inside the
  // deer's flee radius from the first tick. Cattle stand on the same ground so
  // "livestock fears nothing" is tested against a real predator, not an absence.
  const wildlife = new WildlifeSystem(animals, [
    { id: "den", species: "wolf", x: 0, z: 0, count: 2 },
    { id: "prey", species: "deer", x: 4, z: 0, count: 2 },
    { id: "cattle", species: "cow", x: -4, z: 0, count: 2 },
  ]);
  const wolves = wildlife.all().filter((animal) => animal.stats.id === "wolf");
  const deer = wildlife.all().filter((animal) => animal.stats.id === "deer");
  const cattle = wildlife.all().filter((animal) => animal.stats.id === "cow");
  // Penned where they stand: a stall on the spot each cow is already standing
  // on, so this changes ownership without moving anybody.
  for (const cow of cattle) {
    assert.ok(
      wildlife.tame(cow.id, "player", { x: cow.position.x, z: cow.position.z, facing: cow.facing }),
      "cattle pen",
    );
  }

  const startedAt = new Map(wildlife.all().map((animal) => [animal.id, animal.position.clone()]));
  // A worker standing among all three. The wolf must ignore him; the deer must
  // not, and neither may the deer ignore the wolves.
  const worker = [{ x: 0, z: 0 }];
  for (let tick = 0; tick < 40; tick += 1) wildlife.update(1 / 30, worker);

  const moved = (animal: (typeof deer)[number]) =>
    Math.hypot(
      animal.position.x - (startedAt.get(animal.id)?.x ?? 0),
      animal.position.z - (startedAt.get(animal.id)?.z ?? 0),
    );

  // A predator standing on a worker is not a frightened animal. Its patrol keeps
  // it near the den; a bolt would have carried it out to its own roam rim.
  for (const wolf of wolves) {
    assert.ok(
      Math.hypot(wolf.position.x, wolf.position.z) <= animals.wolf!.roamRadius + 1e-6,
      "a wolf standing on a worker patrols rather than bolts",
    );
  }
  // The prey moved, and it moved *away* from the danger it started beside.
  assert.ok(deer.some((animal) => moved(animal) > 0), "deer react to what is standing beside them");
  // Livestock: unmoved by the worker and unmoved by the pack (V2's rule kept,
  // and V2 Faz 8 makes it literal — a stalled animal does not move at all, so
  // "it did not flee" is the same measurement as "it stood exactly still").
  for (const cow of cattle) {
    assert.equal(moved(cow), 0, "penned livestock is frightened by nothing, predator included");
  }
});

check("V3 Faz 2: a chase leaves the patrol circle but never the leash", () => {
  const animals = shippedAnimalBalance();
  const wolf = animals.wolf ?? assert.fail("wolf balance missing");
  const predator = wolf.predator ?? assert.fail("wolf predator block missing");
  const profile = wildProfileFor(wolf, 0, 0);
  const random = makeWildlifeRng(wildlifeSeed("chase"));
  const state = initialRoamState(profile, random);

  // The quarry stands past the leash, which is the case that decides both rules:
  // the predator has to cross its own rim to give chase, and stop at the leash.
  const quarry = { x: predator.pursuitRadius * 3, z: 0, pursuitRadius: predator.pursuitRadius };
  let pose = { x: 0, z: 0, facing: 0 };
  let leftTheCircle = false;
  for (let tick = 0; tick < 600; tick += 1) {
    const next = advanceHunt(state, pose, profile, 1 / 30, quarry);
    pose = { x: next.x, z: next.z, facing: next.facing };
    const fromDen = Math.hypot(pose.x, pose.z);
    if (fromDen > wolf.roamRadius) leftTheCircle = true;
    assert.ok(
      fromDen <= predator.pursuitRadius + 1e-6,
      `a chase reached ${fromDen}, past the leash of ${predator.pursuitRadius}`,
    );
  }
  assert.ok(leftTheCircle, "a chase crosses the patrol rim the roam mode may never leave");
  // Held at the leash, the reported speed is what the body covered — zero — so
  // the Gallop clip is not played over a stationary wolf.
  const held = advanceHunt(state, pose, profile, 1 / 30, quarry);
  assert.equal(held.speed, 0, "a predator at the end of its leash reports no ground speed");

  // And a chase is not a bolt: both flight timers are cleared, or a predator
  // that walked through a threat would spend the chase running the other way.
  state.fleeSeconds = 5;
  state.recoverySeconds = 5;
  advanceHunt(state, pose, profile, 1 / 30, quarry);
  assert.equal(state.fleeSeconds, 0);
  assert.equal(state.recoverySeconds, 0);
});

/**
 * One den, one kingdom's control circle, and whatever workers a test spawns.
 *
 * The wolf is planted on its den rather than left wherever the herd RNG
 * scattered it: every assertion below is about *which* worker it went for, and a
 * randomised starting distance would make that a question about the seed.
 */
function predatorFieldFixture(control: readonly { x: number; z: number; radius: number }[]) {
  const animals = shippedAnimalBalance();
  const stats = animals.wolf ?? assert.fail("wolf balance missing");
  const predator = stats.predator ?? assert.fail("wolf predator block missing");
  const wildlife = new WildlifeSystem(animals, [{ id: "den", species: "wolf", x: 0, z: 0, count: 1 }]);
  const wolf = wildlife.all()[0] ?? assert.fail("no wolf spawned");
  wolf.position.set(0, 0, 0);
  const units = new UnitSystem();
  const territory = new TerritoryControlSystem(
    () => control.map((circle) => ({ owner: "player" as const, ...circle })),
  );
  territory.refresh();
  const predators = new PredatorSystem(units, wildlife, (x, z) => territory.ownerAt(x, z));
  const strikes: PredatorStrike[] = [];
  const step = 0.25;
  const tick = (): void => {
    strikes.push(...predators.update(step));
    wildlife.update(step, units.all().map((unit) => unit.position));
  };
  return { animals, stats, predator, wildlife, wolf, units, territory, predators, strikes, step, tick };
}

check("V3 Faz 3: a wolf takes the worker on unowned ground and never the one inside the control area", () => {
  // KARAR 1, set up so that only the rule can explain the outcome: the sheltered
  // worker is *nearer* the den than the exposed one and both are well inside the
  // wolf's acquisition circle. If distance decided, the wolf would take the one
  // it must never touch.
  // Every distance below is a fraction of the wolf's own acquisition circle, so
  // the geometry survives a table-wide rescale rather than quietly putting both
  // workers out of range.
  const reach = (shippedAnimalBalance().wolf?.predator ?? assert.fail("wolf predator block missing"))
    .acquisitionRadius;
  const shelterRadius = reach * 0.3;
  assert.ok(
    shelterRadius >= RTS_PLACEMENT_GRID_SIZE,
    "a control circle narrower than one territory cell cannot hold anybody, and the grid is not balance data",
  );
  const field = predatorFieldFixture([{ x: -reach * 0.4, z: 0, radius: shelterRadius }]);
  const { wolf, units, territory, predator, stats, strikes } = field;
  const sheltered = units.spawn("player", -reach * 0.4, 0, RTS_TEST_WORKER_STATS);
  const exposed = units.spawn("player", reach * 0.65, 0, RTS_TEST_WORKER_STATS);
  assert.equal(territory.ownerAt(sheltered.position.x, sheltered.position.z), "player");
  assert.equal(territory.ownerAt(exposed.position.x, exposed.position.z), "neutral");
  assert.ok(
    Math.hypot(sheltered.position.x, sheltered.position.z) < Math.hypot(exposed.position.x, exposed.position.z),
    "the protected worker is the nearer of the two, or the test proves nothing about territory",
  );
  assert.ok(
    Math.hypot(exposed.position.x, exposed.position.z) < predator.acquisitionRadius,
    "and the exposed one is inside the acquisition circle, so this is a choice rather than a range check",
  );

  // Far enough to draw blood, and no further: how hard a bite is and how long a
  // worker lasts are exactly the tuning this phase exists to let somebody choose.
  for (let tick = 0; tick < 2000 && strikes.length < 3; tick += 1) field.tick();

  assert.ok(strikes.length > 0, "a lone worker on unowned ground is hunted");
  assert.ok(strikes.every((strike) => strike.victim === exposed), "every bite landed on the exposed worker");
  assert.equal(
    sheltered.health.current,
    sheltered.health.max,
    "and the worker standing in his kingdom's control area was never touched",
  );
  // Derived from the table rather than pinned: whatever the bite is retuned to,
  // the wound is the bites that landed times that number. Compared with a
  // tolerance because a retuned `damage` need not be a whole number, and the
  // difference between summing it and multiplying it is one float ulp.
  const wound = exposed.health.max - exposed.health.current;
  assert.ok(
    Math.abs(wound - strikes.length * predator.damage) < 1e-9,
    `the wound is ${wound}, not the ${strikes.length} bites of ${predator.damage} the wolf actually landed`,
  );
  // The V2 presentation rule: one `Attack` clip per landed blow, driven by the
  // blow rather than by a duration the animation guessed for itself.
  assert.equal(wolf.strikeCount, strikes.length, "presentation is told about each bite");
  assert.equal(wolf.attacking, true, "and the wolf reads as attacking while it is biting");
  assert.ok(
    Math.hypot(wolf.position.x - exposed.position.x, wolf.position.z - exposed.position.z) <= CAUGHT_DISTANCE,
    "it closed to contact rather than biting from across the field",
  );
  assert.ok(
    Math.hypot(wolf.position.x - exposed.position.x, wolf.position.z - exposed.position.z) > 0,
    "and stands beside its victim rather than inside him",
  );

  // V1 §3.9, measured rather than assumed, and still true after Faz 4 widened
  // the answer: this system never hands a worker a target. `updateUnitEngagement`
  // skips workers outright, so nothing here opens a worker-versus-wildlife war by
  // acquisition. The *answer* to a bite already taken is the composition root's
  // one call, and it is pinned separately below ("the wolf's bite is answered").
  assert.equal(exposed.attackTarget, null, "the predator system alone never puts a worker into combat");
  assert.equal(exposed.autoAcquired, false, "and a worker acquires nothing on his own account");

  // And he dies rather than being nibbled forever: §2.5's "nothing disappears
  // quietly" needs a body at the end of it.
  for (let tick = 0; tick < 4000 && !exposed.health.depleted; tick += 1) field.tick();
  assert.equal(exposed.health.depleted, true, "the worker the wolf picked actually falls");
  assert.equal(sheltered.health.current, sheltered.health.max, "the sheltered one still stands, untouched");
  // With nobody left to take, the pack goes back to patrolling instead of
  // standing over the corpse with `attacking` stuck on.
  field.tick();
  assert.equal(wolf.attacking, false, "a wolf with no victim is not mid-bite");
  assert.equal(stats.tameable, false, "and it was never a candidate for a pasture either");
  field.territory.dispose();
});

check("V3 Faz 3: a chase that ends walks the wolf home instead of snapping it back", () => {
  // The failure this pins is a teleport, not a rule. `advanceHunt` lets a
  // predator cross its patrol rim, but the grazing mode *clamps* an animal to
  // that rim — so a wolf simply released at the end of a chase would be yanked
  // most of the leash back to its circle in a single frame. Nothing about the
  // balance table says so; only running it does.
  const field = predatorFieldFixture([]);
  const { wolf, units, stats, predator, step } = field;
  // Standing at the edge of its patrol so the quarry it can see is outside the
  // circle — the case where crossing the rim is the only way to reach anybody.
  wolf.position.set(stats.roamRadius * 0.7, 0, 0);
  // Halfway between the patrol rim and the leash: outside one and inside the
  // other by the data contract itself (`pursuitRadius > roamRadius`), at any
  // rescale of the table.
  const victim = units.spawn("player", (stats.roamRadius + predator.pursuitRadius) / 2, 0, RTS_TEST_WORKER_STATS);
  assert.ok(
    Math.hypot(victim.position.x, victim.position.z) > stats.roamRadius,
    "the victim stands outside the patrol circle",
  );
  assert.ok(
    Math.hypot(victim.position.x, victim.position.z) < predator.pursuitRadius,
    "but inside the leash, so the chase is one the wolf may finish",
  );
  assert.ok(
    Math.abs(victim.position.x - wolf.position.x) < predator.acquisitionRadius,
    "and close enough to be noticed, or nothing would ever start",
  );

  let furthest = 0;
  let longestStep = 0;
  const trackedTick = (): void => {
    const before = { x: wolf.position.x, z: wolf.position.z };
    field.tick();
    longestStep = Math.max(longestStep, Math.hypot(wolf.position.x - before.x, wolf.position.z - before.z));
    furthest = Math.max(furthest, Math.hypot(wolf.position.x, wolf.position.z));
  };

  for (let tick = 0; tick < 400 && field.strikes.length === 0; tick += 1) trackedTick();
  assert.ok(field.strikes.length > 0, "the wolf reached a victim outside its patrol circle");
  assert.ok(furthest > stats.roamRadius, "which means it really did leave the circle to do it");

  // Kill the victim outright — how it ends is not the point, that it ends is.
  victim.health.damage(victim.health.max);
  for (let tick = 0; tick < 4000 && Math.hypot(wolf.position.x, wolf.position.z) > stats.roamRadius; tick += 1) {
    trackedTick();
  }
  assert.ok(
    Math.hypot(wolf.position.x, wolf.position.z) <= stats.roamRadius + 1e-6,
    "a wolf whose chase ended finds its way back to its own ground",
  );
  // One more tick to read the flag: the walk home is aimed at the top of a tick
  // and travelled at the bottom of it, so the step that brings the wolf inside is
  // by construction the step before the one that notices.
  trackedTick();
  assert.equal(wolf.hunt, null, "and stops hunting once it is home");
  // The whole point: it *walked*. Computed from the species' own top speed, so
  // this holds at any tuning — a clamp would show up as one impossible step.
  assert.ok(
    longestStep <= stats.moveSpeed * step + 1e-6,
    `the wolf covered ${longestStep.toFixed(2)} in one step, past the ${(stats.moveSpeed * step).toFixed(2)} its speed allows`,
  );
  // And the leash held for the whole affair, den-relative as the risk table asks.
  assert.ok(
    furthest <= predator.pursuitRadius + 1e-6,
    `the chase reached ${furthest.toFixed(2)}, past the leash of ${predator.pursuitRadius}`,
  );
  // Home is still where it was authored. Re-homing the pack at the end of every
  // chase would have been the cheap fix and would let a den drift across the map
  // one worker at a time — which is exactly what the Faz 2 placement and
  // fairness tests measure against.
  assert.equal(wolf.homeX, 0);
  assert.equal(wolf.homeZ, 0);
  field.territory.dispose();
});

check("V3 Faz 4: the army is offered a hunting wolf and never a grazing herd", () => {
  // §3.4's finding and §9's first risk in one test. Wildlife already satisfies
  // `CombatTarget` and `nearestHostile` compares nothing but owners, so the
  // tempting one-liner — hand the engagement system the roster — would make every
  // deer on the map hostile to both kingdoms and break an army off a raid to
  // chase venison. What enters the list is therefore a **state**, not a species.
  // The last block proves the distinction is load-bearing rather than decorative.
  const animals = shippedAnimalBalance();
  const stats = animals.wolf ?? assert.fail("wolf balance missing");
  const predator = stats.predator ?? assert.fail("wolf predator block missing");
  const deerStats = animals.deer ?? assert.fail("deer balance missing");
  const cowStats = animals.cow ?? assert.fail("cow balance missing");
  // The meadow is the den's leash plus both herds' circles plus two Guard
  // acquisition circles away, all read off the tables — so "the Guard ignored the
  // deer" can never turn out to have been a statement about how far the wolf was.
  const meadowX = -(predator.pursuitRadius + deerStats.roamRadius + cowStats.roamRadius
    + RTS_TEST_UNIT_STATS.acquisitionRange * 2);
  const wildlife = new WildlifeSystem(animals, [
    { id: "den", species: "wolf", x: 0, z: 0, count: 1 },
    { id: "meadow", species: "deer", x: meadowX, z: 0, count: 3 },
    { id: "cattle", species: "cow", x: meadowX, z: 0, count: 2 },
  ]);
  const wolf = wildlife.all().find((animal) => animal.stats.id === "wolf")
    ?? assert.fail("no wolf spawned");
  wolf.position.set(0, 0, 0);
  const units = new UnitSystem();
  const territory = new TerritoryControlSystem(() => []);
  territory.refresh();
  const predators = new PredatorSystem(units, wildlife, (x, z) => territory.ownerAt(x, z));
  const navigation = new RtsNavigation();
  const step = 0.25;
  // The composition root's own calls, in its own order: acquisition reads the
  // list the previous pass left behind, which is the one frame of lag `RtsApp`
  // accepts to keep a chase from trailing the worker it is aimed at.
  const tick = (): void => {
    updateUnitEngagement(units.all(), { navigation, targets: [...units.all(), ...predators.hostile()] });
    predators.update(step);
    wildlife.update(step, units.all().map((unit) => unit.position));
  };

  const herder = units.spawn("player", meadowX, 0, RTS_TEST_UNIT_STATS);
  for (let index = 0; index < 40; index += 1) tick();
  assert.deepEqual(
    [...predators.hostile()],
    [],
    "a pack hunting nobody, on nobody's ground, is nobody's enemy",
  );
  assert.equal(herder.attackTarget, null, "and a Guard standing inside a herd acquires nothing");

  // Now give the wolf a reason: a worker on unowned ground inside its
  // acquisition circle, which is the whole of KARAR 1.
  const worker = units.spawn("player", predator.acquisitionRadius * 0.6, 0, RTS_TEST_WORKER_STATS);
  assert.equal(territory.ownerAt(worker.position.x, worker.position.z), "neutral");
  for (let index = 0; index < 400 && predators.hostile().length === 0; index += 1) tick();
  assert.deepEqual([...predators.hostile()], [wolf], "the one animal hunting somebody is the one on offer");
  assert.equal(
    predators.hostile().some((animal) => animal.stats.predator === undefined),
    false,
    "and nothing that merely grazes ever joins it",
  );
  assert.equal(herder.attackTarget, null, "the meadow Guard still has nothing to shoot");

  // The wolf drops off the list on the pass after it gives its victim up: the
  // state is the current one, not a mark it carries for the rest of the match.
  worker.health.damage(worker.health.max);
  tick();
  assert.deepEqual([...predators.hostile()], [], "a wolf that has given up is off the list again");

  // Vacuity guard: hand the same Guard the naive list §3.4 warns about and it
  // picks an animal at once. So the meadow was safe because of the *state* rule
  // and not because the test happened to place it out of reach.
  updateUnitEngagement(units.all(), { navigation, targets: [...units.all(), ...wildlife.all()] });
  assert.equal(
    herder.attackTarget?.owner,
    "wild",
    "offered the whole roster a Guard does exactly what §9 warns about — which is why it is never offered",
  );
  territory.dispose();
});

check("V3 Faz 4: the wolf's bite is answered — the worker turns on it and an unordered Guard comes", () => {
  // V1 §3.9's debt, closed. Every other blow in the match reaches
  // `resolveCombatHit` and provokes a defensive answer out of it; the wolf's is
  // landed by `PredatorSystem` instead, so without the call mirrored below a
  // worker would be eaten without ever reacting — "işçiler sessizce kurban gider".
  const animals = shippedAnimalBalance();
  const stats = animals.wolf ?? assert.fail("wolf balance missing");
  const predator = stats.predator ?? assert.fail("wolf predator block missing");
  const wildlife = new WildlifeSystem(animals, [{ id: "den", species: "wolf", x: 0, z: 0, count: 1 }]);
  const wolf = wildlife.all()[0] ?? assert.fail("no wolf spawned");
  wolf.position.set(0, 0, 0);
  const units = new UnitSystem();
  const territory = new TerritoryControlSystem(() => []);
  territory.refresh();
  const predators = new PredatorSystem(units, wildlife, (x, z) => territory.ownerAt(x, z));
  const navigation = new RtsNavigation();
  const step = 0.25;
  let bites = 0;
  const tick = (): void => {
    updateUnitEngagement(units.all(), { navigation, targets: [...units.all(), ...predators.hostile()] });
    updateUnitMovement(units.all(), step, { navigation });
    for (const strike of predators.update(step)) {
      // Exactly what `RtsApp.updateSimulation` does with the strikes it gets back.
      retaliateAgainstAttack(strike.victim, strike.predator, navigation);
      bites += 1;
    }
    wildlife.update(step, units.all().map((unit) => unit.position));
    updateUnitCombat(units.all(), step);
  };

  const worker = units.spawn("player", predator.acquisitionRadius * 0.6, 0, RTS_TEST_WORKER_STATS);
  // The escort stands with his worker, which is the entire point of an escort.
  const escort = units.spawn("player", predator.acquisitionRadius * 0.6 + 2, 0, RTS_TEST_UNIT_STATS);
  // And a second soldier who was told to be somewhere else. §8's "muhafizin
  // komutu yoksa": a transit order outranks an automatic defensive chase, so this
  // one has to walk past a fight it could otherwise have joined.
  const courier = units.spawn("player", predator.acquisitionRadius * 0.6 - 2, 0, RTS_TEST_UNIT_STATS);
  courier.setMoveTarget(courier.position.x, predator.pursuitRadius * 4);

  // The Guard answers a wolf that is still *closing* — the escort has to be
  // allowed to meet the charge rather than wait for the first bite to land — so
  // this is read before the mauling, not after it.
  for (let index = 0; index < 400 && !escort.attackTarget; index += 1) tick();
  assert.equal(escort.attackTarget, wolf, "the Guard beside the worker answers the wolf");
  assert.equal(escort.autoAcquired, true, "and did it on his own account, so the chase leash applies to him");
  assert.equal(courier.attackTarget, null, "the soldier under a movement order keeps walking");
  assert.equal(worker.attackTarget, null, "and the worker, un-bitten so far, is still just working");

  // The bitten worker fights back — the one door into combat a worker has, and it
  // only opens on a hit already taken.
  for (let index = 0; index < 400 && bites === 0; index += 1) tick();
  assert.ok(bites > 0, "the wolf actually reached the worker and drew blood");
  assert.ok(worker.health.current < worker.health.max, "which cost him health");
  assert.equal(worker.attackTarget, wolf, "a mauled worker turns on what is mauling him");
  assert.equal(worker.autoAcquired, true, "through the defensive path, exactly as a raider's blow would provoke");

  // §2.6: one soldier is enough. A wolf has to want an escort without wanting an
  // army, so this asserts the kill rather than how long it took.
  for (let index = 0; index < 4000 && !wolf.dead; index += 1) tick();
  assert.equal(wolf.dead, true, "a single Guard brings a wolf down; no army is needed");
  // One more pass to read the list: the kill lands at the bottom of a tick, after
  // the predator pass that published the list has already run.
  tick();
  assert.equal(predators.hostile().length, 0, "and a carcass is nobody's target either");
  territory.dispose();
});

check("Kurt alarmı: bir işçi ısırıldığında en yakın iki boştaki asker olay yerine gider", () => {
  // The complaint this answers: a garrison watching a worker be mauled from what
  // the player reads as arm's length. Both existing answers are passive — the
  // struck worker turns on the wolf, and a soldier who happens to be standing
  // idle inside his nine-unit acquisition circle joins in — so every soldier
  // posted just outside that circle does nothing at all. Every responder below
  // is deliberately placed beyond it, so nothing here can be explained by the
  // passive path: if the alarm does not carry, none of them move.
  const animals = shippedAnimalBalance();
  const stats = animals.wolf ?? assert.fail("wolf balance missing");
  const predator = stats.predator ?? assert.fail("wolf predator block missing");
  const wildlife = new WildlifeSystem(animals, [{ id: "den", species: "wolf", x: 0, z: 0, count: 1 }]);
  const wolf = wildlife.all()[0] ?? assert.fail("no wolf spawned");
  wolf.position.set(0, 0, 0);
  const units = new UnitSystem();
  const territory = new TerritoryControlSystem(() => []);
  territory.refresh();
  const predators = new PredatorSystem(units, wildlife, (x, z) => territory.ownerAt(x, z));
  const navigation = new RtsNavigation();
  const response = new PredatorResponseSystem(units, navigation);
  const step = 0.25;
  let bites = 0;
  const tick = (): void => {
    updateUnitEngagement(units.all(), { navigation, targets: [...units.all(), ...predators.hostile()] });
    updateUnitMovement(units.all(), step, { navigation });
    const strikes = predators.update(step);
    for (const strike of strikes) retaliateAgainstAttack(strike.victim, strike.predator, navigation);
    bites += strikes.length;
    // Exactly where `RtsApp.updateSimulation` runs it: on the same strikes the
    // worker's own retaliation was fed, every tick so the walk home is driven too.
    response.update(strikes);
    wildlife.update(step, units.all().map((unit) => unit.position));
    updateUnitCombat(units.all(), step);
  };

  const worker = units.spawn("player", 8, 0, RTS_TEST_WORKER_STATS);
  // A soldier already under a movement order — nearest of all, and the one that
  // must not answer: a transit order outranks an automatic response, here
  // exactly as it does in the passive path.
  const courier = units.spawn("player", 8, 10, RTS_TEST_UNIT_STATS);
  courier.setMoveTarget(8, 60);
  const near = units.spawn("player", 8, 13, RTS_TEST_UNIT_STATS);
  const second = units.spawn("player", 8, 15, RTS_TEST_UNIT_STATS);
  const third = units.spawn("player", 8, 20, RTS_TEST_UNIT_STATS);
  // Out of earshot: the alarm is a radius, not the whole roster.
  const deaf = units.spawn("player", 8, PREDATOR_ALARM_RADIUS + 6, RTS_TEST_UNIT_STATS);
  const posts = [near, second, third, deaf].map((unit) => ({ unit, post: unit.position.clone() }));
  for (const { unit, post } of posts) {
    assert.ok(
      post.distanceTo(worker.position) > unit.attack.acquisitionRange,
      `${post.z} is inside the passive acquisition circle, so this test proves nothing`,
    );
  }

  for (let index = 0; index < 400 && bites === 0; index += 1) tick();
  assert.ok(bites > 0, "the wolf reached the worker and drew blood");
  assert.equal(near.attackTarget, wolf, "the nearest unoccupied soldier answers the bite");
  assert.equal(second.attackTarget, wolf, "and so does the second nearest");
  assert.equal(
    [near, second, third, deaf, courier].filter((unit) => unit.attackTarget === wolf).length,
    PREDATOR_RESPONDER_LIMIT,
    "two answer a wolf, not the garrison: a den must not be able to drain a barracks",
  );
  assert.equal(third.attackTarget, null, "the third nearest is left at his post");
  assert.equal(deaf.attackTarget, null, "and the one out of earshot never heard it");
  assert.equal(courier.attackTarget, null, "the soldier under a movement order keeps walking");

  // §2.6 with the escort actually arriving: the worker is saved rather than
  // avenged, which is the whole difference between this and the passive answer.
  for (let index = 0; index < 4000 && !wolf.dead; index += 1) tick();
  assert.equal(wolf.dead, true, "the responders brought the wolf down");
  assert.ok(!worker.health.depleted, "and reached him in time — the worker lives");
  for (const { unit, post } of posts.filter((entry) => entry.unit === third || entry.unit === deaf)) {
    assert.ok(
      unit.position.distanceTo(post) < 1e-6,
      "a soldier who was not called never left his post",
    );
  }

  // The walk back: a rescue that stripped the ground it was called from would
  // simply move the problem, so the responders return to where they stood.
  const called = posts.filter((entry) => entry.unit === near || entry.unit === second);
  for (let index = 0; index < 4000; index += 1) {
    tick();
    if (called.every((entry) => entry.unit.position.distanceTo(entry.post) < 2)) break;
  }
  for (const { unit, post } of called) {
    assert.ok(
      unit.position.distanceTo(post) < 2,
      `a responder ended ${unit.position.distanceTo(post).toFixed(2)} from the post he was called off`,
    );
  }
  territory.dispose();
});

check("Kurt alarmı: çağrılan asker kurdun kaydığı yere kadar takip eder", () => {
  // An attack order is pathed once, when it is issued, and a wolf does not wait
  // where it was when the call went out. Without the responder's own re-plan the
  // rescue ends as a soldier standing on the spot the wolf used to be, target in
  // hand, doing nothing — which is the exact silhouette being complained about.
  const animals = shippedAnimalBalance();
  const stats = animals.wolf ?? assert.fail("wolf balance missing");
  const wildlife = new WildlifeSystem(animals, [{ id: "den", species: "wolf", x: 0, z: 0, count: 1 }]);
  const wolf = wildlife.all()[0] ?? assert.fail("no wolf spawned");
  wolf.position.set(0, 0, 0);
  const units = new UnitSystem();
  const territory = new TerritoryControlSystem(() => []);
  territory.refresh();
  const predators = new PredatorSystem(units, wildlife, (x, z) => territory.ownerAt(x, z));
  const navigation = new RtsNavigation();
  const response = new PredatorResponseSystem(units, navigation);
  const step = 0.25;

  const worker = units.spawn("player", 8, 0, RTS_TEST_WORKER_STATS);
  const guard = units.spawn("player", 8, 14, RTS_TEST_UNIT_STATS);
  assert.ok(
    guard.position.distanceTo(worker.position) > guard.attack.acquisitionRange,
    "the guard has to be out of passive range for this to be the response's doing",
  );

  let dispatched = false;
  for (let index = 0; index < 400 && !dispatched; index += 1) {
    updateUnitEngagement(units.all(), { navigation, targets: [...units.all(), ...predators.hostile()] });
    updateUnitMovement(units.all(), step, { navigation });
    const strikes = predators.update(step);
    response.update(strikes);
    wildlife.update(step, units.all().map((unit) => unit.position));
    dispatched = guard.attackTarget === wolf;
  }
  assert.equal(dispatched, true, "the bite dispatched the guard");

  // Now move the wolf out from under the planned route, as a chase after the
  // next worker would. The guard's baked path is stale from this frame on.
  wolf.position.set(-14, 0, 6);
  wolf.hunt = null;
  let closed = false;
  for (let index = 0; index < 4000 && !closed; index += 1) {
    updateUnitMovement(units.all(), step, { navigation });
    response.update([]);
    closed = combatDistance(guard.position, wolf) <= guard.attack.range;
  }
  assert.equal(closed, true, "the responder re-planned and closed on where the wolf actually is");
  territory.dispose();
});

check("V3 Faz 4: the Karakol shoots a hunting wolf with the arrows it already had", () => {
  // §3.13's claim, verified rather than assumed: the Karakol needs **zero** new
  // defensive code, because `structureDefense` already reads the same
  // `combatTargets()` list the army does and `resolveDamage` already looks the
  // wolf's armour class up in the building's own counter table.
  //
  // This is the *hunting* half of the state, and on its own it is nearly
  // unreachable in a real match: a hunting wolf stands, by KARAR 1, beside a
  // worker on unowned ground, while the tower owns every point inside
  // `controlRadius` (16) and only shoots to `attackRange` (12). The tower's
  // useful case is the trespass half, pinned in the test below this one.
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const outpostStats = buildings.outpost ?? assert.fail("outpost definition missing");
  const defense = outpostStats.defense ?? assert.fail("outpost defense missing");
  const animals = shippedAnimalBalance();
  const stats = animals.wolf ?? assert.fail("wolf balance missing");
  const predator = stats.predator ?? assert.fail("wolf predator block missing");
  const wildlife = new WildlifeSystem(animals, [
    { id: "den", species: "wolf", x: 0, z: 0, count: 1 },
    { id: "meadow", species: "deer", x: 0, z: 0, count: 2 },
  ]);
  const wolf = wildlife.all().find((animal) => animal.stats.id === "wolf")
    ?? assert.fail("no wolf spawned");
  wolf.position.set(0, 0, 0);
  const units = new UnitSystem();
  const territory = new TerritoryControlSystem(() => []);
  territory.refresh();
  const predators = new PredatorSystem(units, wildlife, (x, z) => territory.ownerAt(x, z));
  const structures = new PlacedStructureSystem();
  const outpost = structures.place("player", outpostStats, 0, 0);
  structures.advanceConstruction(outpost, outpostStats.constructionSeconds);
  const defenseSystem = new StructureDefenseSystem();
  const step = 0.25;

  // Bait inside the tower's reach, placed as a fraction of the tower's own range
  // so the geometry survives a retuning of either table.
  const worker = units.spawn("player", defense.attackRange * 0.5, 0, RTS_TEST_WORKER_STATS);
  assert.ok(
    defense.attackRange * 0.5 < predator.acquisitionRadius,
    "and inside the wolf's acquisition circle, or nothing would ever start",
  );
  for (let index = 0; index < 400 && predators.hostile().length === 0; index += 1) {
    predators.update(step);
    wildlife.update(step, units.all().map((unit) => unit.position));
  }
  assert.equal(predators.hostile().length, 1, "the wolf is hunting, so the tower may see it");
  assert.ok(combatDistance(outpost.position, wolf) <= defense.attackRange, "and it stands inside the volley");

  const before = wolf.health.current;
  defenseSystem.update(
    structures.all(),
    [...units.all(), ...structures.all(), ...predators.hostile()],
    0,
  );
  // Derived from both tables: the volley is worth what the Karakol's own counter
  // column says against the armour class the wolf actually carries.
  const expected = defense.attackDamage * defense.damageMultipliers[wolf.armorClass] * defense.arrowsPerVolley;
  assert.ok(
    Math.abs((before - wolf.health.current) - expected) < 1e-9,
    `the Karakol took ${before - wolf.health.current} off the wolf, not the ${expected} its own table says`,
  );
  assert.equal(worker.health.current, worker.health.max, "and never loosed an arrow at its own worker");
  for (const deer of wildlife.all().filter((animal) => animal.stats.id === "deer")) {
    assert.equal(deer.health.current, deer.health.max, "a deer grazing under the tower is not a target");
  }
  structures.clear();
  territory.dispose();
});

check("V3 Faz 4: a Karakol raised beside a den clears it — a wolf on owned ground is answerable", () => {
  // The half of the state that makes §2.7 true in a match rather than on paper,
  // and it was found by playing: with only "is it hunting" on the list, a tower
  // built next to a den never loosed an arrow and the pack stood around ignoring
  // the workers walking past it — KARAR 1 protects them, so the wolves read as
  // having been tamed by the building. Trespass is the answer, and it is still a
  // *state*: the animal walks out of it by walking off your ground.
  //
  // Nothing here spawns a worker. That is the point — the tower must not need
  // bait to defend the ground it owns.
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const outpostStats = buildings.outpost ?? assert.fail("outpost definition missing");
  const defense = outpostStats.defense ?? assert.fail("outpost defense missing");
  const control = outpostStats.territory ?? assert.fail("outpost territory missing");
  const animals = shippedAnimalBalance();
  const stats = animals.wolf ?? assert.fail("wolf balance missing");
  // The finding itself, as an assertion rather than a memory: the tower owns
  // further than it shoots, which is why the hunting state alone could not fire.
  assert.ok(
    control.controlRadius > defense.attackRange,
    "a Karakol owns further than it shoots, so a wolf kept outside its territory is out of its reach too",
  );
  // The bystanders are cattle rather than deer, and Faz 5 is why: a deer standing
  // in a den is *prey*, so a wound on one would no longer say anything about the
  // tower — the wolves would have eaten it. Cattle are outside the wolf's
  // `preySpecies` (KARAR 5), which leaves the arrow as the only thing that could
  // possibly have hurt them.
  const bystander = "cow";
  assert.equal(
    (stats.predator ?? assert.fail("wolf predator block missing")).preySpecies.includes(bystander),
    false,
    `the wolf hunts ${bystander}, so a wound on one proves nothing about the tower`,
  );
  const wildlife = new WildlifeSystem(animals, [
    { id: "den", species: "wolf", x: 0, z: 0, count: 3 },
    { id: "meadow", species: bystander, x: 0, z: 0, count: 2 },
  ]);
  const units = new UnitSystem();
  const structures = new PlacedStructureSystem();
  const outpost = structures.place("player", outpostStats, 0, 0);
  structures.advanceConstruction(outpost, outpostStats.constructionSeconds);
  const territory = new TerritoryControlSystem(
    () => [{ owner: "player" as const, x: 0, z: 0, radius: control.controlRadius }],
  );
  territory.refresh();
  const predators = new PredatorSystem(units, wildlife, (x, z) => territory.ownerAt(x, z));
  const defenseSystem = new StructureDefenseSystem();
  const step = 0.25;
  const wolves = wildlife.all().filter((animal) => animal.stats.id === "wolf");
  assert.equal(wolves.length, 3, "a den is a pack, and the tower has to see all of it");
  // The patrol circle sits inside the control area by the data itself, so every
  // wolf is on the player's ground wherever the herd RNG scattered it.
  assert.ok(
    stats.roamRadius < control.controlRadius,
    "the den's patrol circle fits inside the tower's ground at this tuning",
  );

  predators.update(step);
  assert.equal(predators.hostile().length, wolves.length, "every wolf on the player's ground is answerable");
  assert.equal(
    predators.hostile().some((animal) => animal.stats.predator === undefined),
    false,
    "and the cattle grazing on the same ground are not — livestock you have not caught is not a threat",
  );

  for (let index = 0; index < 4000 && wolves.some((wolf) => !wolf.dead); index += 1) {
    predators.update(step);
    wildlife.update(step, units.all().map((unit) => unit.position));
    defenseSystem.update(
      structures.all(),
      [...units.all(), ...structures.all(), ...predators.hostile()],
      step,
    );
  }
  assert.ok(wolves.every((wolf) => wolf.dead), "the Karakol clears the den it was built against");
  for (const grazer of wildlife.all().filter((animal) => animal.stats.id === bystander)) {
    assert.equal(grazer.health.current, grazer.health.max, "and never turned an arrow on the herd beside them");
  }
  // KARAR 3's promise, now that the tower can actually keep it: cleared ground
  // stays cleared, and with nothing left alive there is nothing left to answer.
  predators.update(step);
  assert.deepEqual([...predators.hostile()], [], "a cleared den is nobody's target");
  structures.clear();
  territory.dispose();
});

/**
 * A den with game standing in it, and nobody on the field — V3 Faz 5.
 *
 * No units at all, deliberately: §2.8's claim is that the map does something
 * while the player is looking elsewhere, so a fixture that needed a worker to
 * start the hunt would be proving a different sentence. Every distance comes
 * from the two species' own radii, so a table-wide rescale moves the herd and
 * the eye together instead of quietly putting one out of the other's reach.
 */
function predatorMeadowFixture(extra: readonly RtsHerdDefinition[] = []) {
  const animals = shippedAnimalBalance();
  const stats = animals.wolf ?? assert.fail("wolf balance missing");
  const predator = stats.predator ?? assert.fail("wolf predator block missing");
  const preyId = predator.preySpecies[0] ?? assert.fail("the wolf names no prey");
  const preyStats = animals[preyId] ?? assert.fail(`unknown prey "${preyId}"`);
  // The herd shares the den's centre, so wherever the herd RNG scatters it every
  // animal is inside the wolf's eye. Stated as an assertion rather than assumed:
  // a species whose meadow outgrew the predator's acquisition circle would make
  // every result below a question about the seed.
  assert.ok(
    preyStats.roamRadius < predator.acquisitionRadius,
    `a ${preyId} meadow (${preyStats.roamRadius}) is wider than the wolf's eye (${predator.acquisitionRadius})`,
  );
  const wildlife = new WildlifeSystem(animals, [
    { id: "den", species: "wolf", x: 0, z: 0, count: 1 },
    { id: "meadow", species: preyId, x: 0, z: 0, count: 3 },
    ...extra,
  ]);
  const wolf = wildlife.all().find((animal) => animal.stats.id === "wolf") ?? assert.fail("no wolf");
  wolf.position.set(0, 0, 0);
  const units = new UnitSystem();
  // Nobody owns any ground here: the whole map is neutral, so the only rule that
  // can explain a bite is the prey rule.
  const territory = new TerritoryControlSystem(() => []);
  territory.refresh();
  const predators = new PredatorSystem(units, wildlife, (x, z) => territory.ownerAt(x, z));
  const step = 0.25;
  const tick = (): void => {
    predators.update(step);
    wildlife.update(step, units.all().map((unit) => unit.position));
  };
  const preyOf = (species: string) => wildlife.all().filter((animal) => animal.stats.id === species);
  return { animals, stats, predator, preyId, preyStats, wildlife, wolf, units, territory, predators, step, tick, preyOf };
}

check("V3 Faz 5: a wolf pulls down the game it names as prey and nothing else", () => {
  // KARAR 5, and the two halves of it are refused by different rules, so both are
  // measured. A species the table never listed is safe because `preySpecies` says
  // so; an animal a kingdom owns is safe because ownership takes it out of the
  // wild economy entirely — the same line the hunting camp reads, so a penned
  // animal is no more a wolf's dinner than it is a hunter's.
  //
  // The owned animal is a *deer* on purpose. The validator forbids listing a
  // tameable species as prey, so the only way to put an owned animal in front of
  // a wolf that genuinely wants it is to hand it a pen it would never have been
  // driven into — which is exactly the case the ownership check exists for.
  const shipped = shippedAnimalBalance();
  const bystanderId = Object.values(shipped)
    .find((entry) => !entry.predator
      && !(shipped.wolf?.predator?.preySpecies ?? []).includes(entry.id))
    ?.id ?? assert.fail("no species outside the wolf's prey list");
  const field = predatorMeadowFixture([{ id: "bystanders", species: bystanderId, x: 0, z: 0, count: 1 }]);
  const { wildlife, wolf, predator, preyId, preyStats, tick, preyOf } = field;

  const penned = preyOf(preyId)[0] ?? assert.fail("no prey spawned");
  assert.ok(
    wildlife.tame(penned.id, "player", { x: penned.position.x, z: penned.position.z, facing: 0 }),
    "the fixture needs one owned animal standing in the wolf's own circle",
  );
  const bystander = preyOf(bystanderId)[0] ?? assert.fail("no bystander spawned");
  assert.equal(
    predator.preySpecies.includes(bystanderId),
    false,
    `the bystander species "${bystanderId}" is meant to be off the wolf's list`,
  );

  // Long enough for a chase and a kill at this tuning, and no longer: the wolf
  // bites `damage` at `attacksPerMinute`, so what a kill costs in seconds is
  // arithmetic on the table rather than a number typed in here.
  const secondsPerKill = (preyStats.maxHealth / predator.damage) * (60 / predator.attacksPerMinute);
  const budget = Math.ceil((secondsPerKill * 8) / field.step);
  let ticks = 0;
  while (ticks < budget && !preyOf(preyId).some((animal) => animal.owner === "wild" && animal.dead)) {
    tick();
    ticks += 1;
  }

  assert.ok(
    preyOf(preyId).some((animal) => animal.owner === "wild" && animal.dead),
    `the wolf never brought down a ${preyId} in ${(ticks * field.step).toFixed(1)} seconds`,
  );
  assert.equal(
    penned.health.current,
    penned.health.max,
    "a kingdom's animal is nobody's prey, whatever species it is (KARAR 5)",
  );
  assert.equal(
    bystander.health.current,
    bystander.health.max,
    `a ${bystanderId} is not on the list, so it grazed through the whole hunt untouched`,
  );
  assert.equal(wolf.dead, false, "and the hunt cost the hunter nothing — game does not fight back");
  field.territory.dispose();
});

check("V3 Faz 5: what a wolf kills is meat a hunting camp can still take", () => {
  // The free half of §2.8, and it is free because nothing in the hunt knows how
  // an animal died: `remainingNear` counts carcasses, a claim resolves one, and
  // `harvest` butchers it. This pins that it stayed free — a wolf that consumed
  // what it killed, or one whose kill left the wild roster, would turn the pack
  // into a food *sink* instead of a competitor the player can rob.
  const field = predatorMeadowFixture();
  const { wildlife, predator, preyId, preyStats, tick, preyOf } = field;
  const secondsPerKill = (preyStats.maxHealth / predator.damage) * (60 / predator.attacksPerMinute);
  const budget = Math.ceil((secondsPerKill * 8) / field.step);
  let ticks = 0;
  while (ticks < budget && !preyOf(preyId).some((animal) => animal.dead)) {
    tick();
    ticks += 1;
  }
  const carcass = preyOf(preyId).find((animal) => animal.dead) ?? assert.fail("the wolf killed nothing");

  assert.equal(
    carcass.remainingMeat,
    preyStats.meatCapacity,
    "the wolf's meal is time, not meat: the carcass is worth what the animal was",
  );
  // A camp built over the den, sized from the herd it would have been built for.
  const reach = { x: 0, z: 0, radius: preyStats.roamRadius + predator.pursuitRadius };
  assert.ok(
    wildlife.remainingNear(reach) >= carcass.remainingMeat,
    "the camp counts a wolf-killed carcass exactly as it counts one of its own",
  );
  const claim = wildlife.reserveNearest(1, reach) ?? assert.fail("a hunter could claim nothing");
  const claimed = wildlife.animalById(claim.id) ?? assert.fail("the claim resolves to nothing");
  // Claim whatever is nearest, then insist the *carcass* itself can be worked:
  // the hunter's own claim register is what decides which, and it has no opinion
  // about who did the killing.
  wildlife.releaseReservation(1);
  carcass.reservedByWorkerId = 1;
  const taken = wildlife.harvest({
    workerId: 1,
    sourceId: carcass.id,
    amount: preyStats.meatCapacity,
    deltaSeconds: field.step,
  });
  assert.equal(taken.amount, preyStats.meatCapacity, "and it butchers for the full carcass in one load");
  assert.equal(carcass.spent, true, "which leaves nothing on it");
  assert.ok(claimed, "the claim resolved to a real animal");
  field.territory.dispose();
});

check("V3 Faz 5: a wolf eats what it killed before it hunts again, and its den never moves", () => {
  // Two rules in one run, both about *pace*. The pause is what makes §2.8 read as
  // a meadow thinning rather than as a meadow vanishing — without it the pack
  // starts its next kill on the frame the last body drops. And the den staying
  // put is Faz 3's rejected `rehome`, re-weighed where §3.6 asked for it: over a
  // finished kill. It got stronger, not weaker — a den that walked to each
  // carcass would carry the pack off the ground it was placed to hold.
  const field = predatorMeadowFixture();
  const { wolf, predator, preyId, preyStats, tick, preyOf } = field;
  const den = { x: wolf.homeX, z: wolf.homeZ };
  const secondsPerKill = (preyStats.maxHealth / predator.damage) * (60 / predator.attacksPerMinute);
  const budget = Math.ceil((secondsPerKill * 8) / field.step);
  let ticks = 0;
  while (ticks < budget && !wolf.feeding) {
    tick();
    ticks += 1;
  }
  assert.ok(wolf.feeding, `the wolf never settled onto a kill in ${(ticks * field.step).toFixed(1)} seconds`);
  assert.equal(
    preyOf(preyId).filter((animal) => animal.dead).length,
    1,
    "one kill, one meal",
  );

  // While it eats it holds still, on its kill, and takes nothing else down. The
  // pause is the species' own `restSeconds`, so its length is read off the table
  // rather than pinned here.
  const woundedBefore = preyOf(preyId)
    .filter((animal) => !animal.dead)
    .map((animal) => animal.health.current);
  const strikesBefore = wolf.strikeCount;
  const restedAt = { x: wolf.position.x, z: wolf.position.z };
  let mealTicks = 0;
  while (wolf.feeding && mealTicks < budget) {
    assert.equal(wolf.speed, 0, "a wolf on its kill stands over it");
    assert.equal(wolf.activity, "grazing", "and reads as eating, which is what puts it on the Eating clip");
    assert.equal(wolf.attacking, false, "it is not biting anything while it eats");
    // Checked here rather than after the loop: the tick that *ends* the meal is
    // allowed to move the wolf, because finishing a meal hands it straight back
    // to the hunt — which is the behaviour the sweep below relies on.
    assert.ok(
      Math.hypot(wolf.position.x - restedAt.x, wolf.position.z - restedAt.z) < 1e-6,
      "it never drifted off the body it was eating",
    );
    tick();
    mealTicks += 1;
  }
  assert.ok(
    mealTicks * field.step >= preyStats.restSeconds.min - field.step,
    `the meal lasted ${(mealTicks * field.step).toFixed(2)}s, under the species' own shortest pause`,
  );
  assert.equal(wolf.strikeCount, strikesBefore, "and nothing else was bitten during it");
  assert.deepEqual(
    preyOf(preyId).filter((animal) => !animal.dead).map((animal) => animal.health.current),
    woundedBefore,
    "the rest of the herd is untouched while the wolf is busy",
  );

  // The herd empties in the end, but one at a time — and the den is where it was.
  let sweep = 0;
  while (sweep < budget * 6 && preyOf(preyId).some((animal) => !animal.dead)) {
    tick();
    sweep += 1;
  }
  assert.ok(preyOf(preyId).every((animal) => animal.dead), "left alone, the pack does empty the meadow");
  assert.equal(wolf.homeX, den.x, "the den did not walk with the wolf");
  assert.equal(wolf.homeZ, den.z, "the den did not walk with the wolf");
  assert.ok(
    Math.hypot(wolf.position.x - den.x, wolf.position.z - den.z) <= predator.pursuitRadius + 1e-6,
    "and the wolf itself never left the leash it hunts on",
  );
  field.territory.dispose();
});

check("a bolt commits to one heading instead of re-aiming at whoever is nearest", () => {
  // Found by running the game, then measured rather than guessed. `advanceRoam`
  // recomputed the escape direction from the *current* nearest threat on every
  // tick, so with a crowd around a herd the direction flipped between people and
  // the deer reversed at full gallop several times a second — which is what
  // "their animations scramble and they suddenly dart somewhere else" was. Over a
  // 400-second run with six people standing about, 14.6% of all moving ticks
  // turned the body more than 90 degrees; with one person on the field, 3.4%.
  // That gap is what named the cause.
  const deer = shippedAnimalBalance().deer ?? assert.fail("deer balance missing");
  const profile = wildProfileFor(deer, 0, 0);
  const random = makeWildlifeRng(wildlifeSeed("bolt"));
  const state = initialRoamState(profile, random);
  const step = 1 / 30;

  // Frightened by somebody just inside its flee radius on the -x side, so the
  // bolt heads toward +x.
  let pose = { x: 0, z: 0, facing: 0 };
  const first = advanceRoam(state, pose, profile, step, random, { x: -deer.fleeRadius * 0.5, z: 0 });
  assert.ok(first.speed > 0, "the deer took fright and ran");
  // Measured on the *ground track* rather than on `facing`, and that is a real
  // distinction since the locomotion polish plan's Faz 1: facing is now stepped
  // toward where the body is going at `turnRateDegPerSecond`, so it lags for a
  // few ticks after the animal takes fright. What must not change is where the
  // bolt is carrying it — the commitment lives in `fleeDirX/Z`, and the heading
  // it travels is the only thing that ever showed the re-aiming bug.
  const committed = Math.atan2(first.x - pose.x, first.z - pose.z);
  pose = { x: first.x, z: first.z, facing: first.facing };

  // Now a *nearer* body appears on the far side, outside the caught range. The
  // old code turned the deer around here, mid-stride. Kept short on purpose: the
  // bolt must not reach the rim, where turning along it is the correct answer.
  for (let tick = 0; tick < 5; tick += 1) {
    const nearer = { x: pose.x + CAUGHT_DISTANCE * 1.5, z: 0 };
    const next = advanceRoam(state, pose, profile, step, random, nearer);
    const travelled = Math.atan2(next.x - pose.x, next.z - pose.z);
    assert.ok(
      Math.abs(travelled - committed) < 1e-6,
      `a bolt in progress turned from ${committed} to ${travelled} because something closer appeared`,
    );
    assert.ok(next.speed > 0, "and it is still running");
    pose = { x: next.x, z: next.z, facing: next.facing };
  }
  assert.ok(
    Math.hypot(pose.x, pose.z) < profile.roamRadius,
    "the run stayed clear of the rim, so nothing above was the rim's doing",
  );
});

check("an animal bolting straight at its own rim runs along it rather than standing still", () => {
  // The other half of the same report, and the more visible one: the plain clamp
  // projects an escaping step back down its own radius, so an animal running
  // dead-outward lands exactly where it started. Presentation reads `speed === 0`
  // as standing, which puts a fleeing deer on its *eating* clip at full gallop.
  // Measured, 400 ticks of a 400-second run; after the fix, 1.
  const deer = shippedAnimalBalance().deer ?? assert.fail("deer balance missing");
  const profile = wildProfileFor(deer, 0, 0);
  const random = makeWildlifeRng(wildlifeSeed("rim"));
  const state = initialRoamState(profile, random);
  const step = 1 / 30;

  // On the rim, with the danger directly between it and its herd's centre: the
  // only way out is straight outward, which is the case that used to freeze.
  let pose = { x: profile.roamRadius, z: 0, facing: 0 };
  const threat = { x: profile.roamRadius - deer.fleeRadius * 0.5, z: 0 };
  assert.ok(deer.fleeRadius * 0.5 > CAUGHT_DISTANCE, "the threat frightens rather than catches, or this tests the wrong branch");

  for (let tick = 0; tick < 10; tick += 1) {
    const next = advanceRoam(state, pose, profile, step, random, threat);
    assert.ok(next.speed > 0, "a cornered animal keeps running rather than galloping on the spot");
    assert.ok(
      Math.hypot(next.x, next.z) <= profile.roamRadius + 1e-6,
      "and it stays on its herd's ground, which is what makes it huntable at all",
    );
    // The speed it reports is the speed it travelled — the whole reason the clip
    // plays at rate 1 instead of sliding.
    assert.ok(
      Math.abs(next.speed - Math.hypot(next.x - pose.x, next.z - pose.z) / step) < 1e-9,
      "and reports the ground speed it actually covered",
    );
    pose = { x: next.x, z: next.z, facing: next.facing };
  }
});

/** Shortest turn between two wildlife facings (radians in, degrees out). */
const wildlifeTurnDeg = (fromRad: number, toRad: number): number => {
  const delta = (toRad - fromRad) * (180 / Math.PI);
  return Math.abs(((((delta + 180) % 360) + 360) % 360) - 180);
};

check("locomotion Faz 1: no movement branch turns a body faster than its species' rate", () => {
  // The plan's first contract, and it is checked against the table rather than
  // against a number written here: scale every `turnRateDegPerSecond` in
  // `animals.json` and this still holds, because the budget is computed from
  // whatever the file says. What it refuses is the thing §3.1 measured — a body
  // swinging 120 degrees inside one tick, on 80% of departures.
  //
  // All three branches, because the fault was one line repeated three times
  // (`facing: Math.atan2(...)` in the roam walk, the drive and the chase), and a
  // test that only covered grazing would have let two of them come back.
  const animals = shippedAnimalBalance();
  const step = 1 / 30;
  for (const stats of Object.values(animals)) {
    const profile = wildProfileFor(stats, 0, 0);
    // A hair of slack for the radian/degree round trip, not for the rule.
    const budget = stats.turnRateDegPerSecond * step + 1e-9;
    const random = makeWildlifeRng(wildlifeSeed(`turn:${stats.id}`));
    const state = initialRoamState(profile, random);

    // Grazing, with somebody moving about inside the flee radius so the caught,
    // bolting, resting and walking branches are all exercised in one run.
    let pose = { x: 0, z: 0, facing: 0 };
    for (let tick = 0; tick < 3000; tick += 1) {
      const angle = tick * 0.31;
      const threat = { x: Math.cos(angle) * 3, z: Math.sin(angle) * 3 };
      const next = advanceRoam(state, pose, profile, step, random, threat);
      assert.ok(
        wildlifeTurnDeg(pose.facing, next.facing) <= budget,
        `${stats.id} grazing turned ${wildlifeTurnDeg(pose.facing, next.facing).toFixed(2)} deg in one tick, past its ${budget.toFixed(2)} budget`,
      );
      pose = { x: next.x, z: next.z, facing: next.facing };
    }

    // Being driven: the shepherd is deliberately teleported to the far side, the
    // input that used to spin a cow through 180 degrees in a frame.
    pose = { x: 0, z: 0, facing: 0 };
    for (let tick = 0; tick < 200; tick += 1) {
      const side = tick % 20 < 10 ? 1 : -1;
      const next = advanceLed(pose, { x: side * 5, z: side * 5, follow: true }, profile, step);
      assert.ok(
        wildlifeTurnDeg(pose.facing, next.facing) <= budget,
        `${stats.id} being driven turned past its budget`,
      );
      pose = { x: next.x, z: next.z, facing: next.facing };
    }

    // Chasing, with the quarry jumping across the predator every few ticks.
    pose = { x: 0, z: 0, facing: 0 };
    const chaseState = initialRoamState(profile, random);
    for (let tick = 0; tick < 200; tick += 1) {
      const side = tick % 20 < 10 ? 1 : -1;
      const next = advanceHunt(chaseState, pose, profile, step, {
        x: side * 6,
        z: side * 6,
        pursuitRadius: profile.roamRadius * 2,
      });
      assert.ok(
        wildlifeTurnDeg(pose.facing, next.facing) <= budget,
        `${stats.id} chasing turned past its budget`,
      );
      pose = { x: next.x, z: next.z, facing: next.facing };
    }
  }
});

check("locomotion Faz 1: a turn finishes, and takes the short way round", () => {
  // The other half of a rate: a cap that never converges is a body that arcs
  // forever and never reaches the spot it set out for. Neither the duration nor
  // the heading is pinned — what is asserted is that the animal *gets there*.
  const deer = shippedAnimalBalance().deer ?? assert.fail("deer balance missing");
  const profile = wildProfileFor(deer, 0, 0);
  const step = 1 / 30;

  // Facing due +z with the target dead behind it: the worst turn there is, and
  // the one §3.1 says happens on four departures in five.
  const random = makeWildlifeRng(wildlifeSeed("turn-completes"));
  const state = initialRoamState(profile, random);
  state.targetX = 0;
  state.targetZ = -4;
  state.restSeconds = 0;
  let pose = { x: 0, z: 0, facing: 0 };
  // Generous enough to cover the worst turn plus the walk, and derived from the
  // table so a retune cannot make it too tight: half a turn at this species'
  // rate, then the distance at its own grazing pace.
  const ticks = Math.ceil(
    ((180 / deer.turnRateDegPerSecond) + (4 / profile.walkSpeed)) / step,
  ) + 30;
  let moved = false;
  for (let tick = 0; tick < ticks; tick += 1) {
    const next = advanceRoam(state, pose, profile, step, random, null);
    if (next.speed > 0) moved = true;
    pose = { x: next.x, z: next.z, facing: next.facing };
    if (state.targetX !== 0 || state.targetZ !== -4) break; // arrived and re-targeted
  }
  assert.ok(moved, "the animal did set off rather than pivoting forever");
  assert.ok(
    Math.hypot(pose.x - 0, pose.z - -4) < 0.2,
    `a turn rate must not stop an animal reaching its spot; it stopped ${Math.hypot(pose.x, pose.z + 4).toFixed(2)} away`,
  );

  // Shortest path. Facing 0 with the target 10 degrees *anticlockwise*: the
  // animal turns back through 10, never forward through 350.
  const shortWay = makeWildlifeRng(wildlifeSeed("short-way"));
  const shortState = initialRoamState(profile, shortWay);
  const target = -10 * (Math.PI / 180);
  shortState.targetX = Math.sin(target) * 4;
  shortState.targetZ = Math.cos(target) * 4;
  shortState.restSeconds = 0;
  const stepped = advanceRoam(shortState, { x: 0, z: 0, facing: 0 }, profile, step, shortWay, null);
  assert.ok(
    stepped.facing < 0,
    `a 350-degree target is a 10-degree turn back, not a 350-degree turn forward (got ${stepped.facing})`,
  );
  assert.ok(
    wildlifeTurnDeg(stepped.facing, target) < wildlifeTurnDeg(0, target),
    "and the step closed the gap rather than opening it",
  );
});

check("locomotion Faz 2: every arrival earns a pause, the one after a bolt included", () => {
  // §3.2, as a test. `advanceRoam` used to write `restSeconds = 0` when a bolt
  // ended, and the arrival tick decremented that straight past zero — so the
  // animal picked its next spot in the same frame it reached this one. Measured
  // over 1200 seconds, a threatened deer took no pause on 53 of 85 arrivals,
  // which is every herd in a real match because a real match has people in it.
  const deer = shippedAnimalBalance().deer ?? assert.fail("deer balance missing");
  const profile = wildProfileFor(deer, 0, 0);
  const step = 1 / 30;
  const random = makeWildlifeRng(wildlifeSeed("post-bolt-rest"));
  const state = initialRoamState(profile, random);

  // Drive one whole bolt: frightened from just inside the flee radius, then run
  // until the flight timer expires.
  let pose = { x: 0, z: 0, facing: 0 };
  const threat = { x: -deer.fleeRadius * 0.5, z: 0 };
  assert.ok(deer.fleeRadius * 0.5 > CAUGHT_DISTANCE, "the threat frightens rather than catches");
  for (let tick = 0; tick < Math.ceil(deer.fleeSeconds / step) + 2; tick += 1) {
    const next = advanceRoam(state, pose, profile, step, random, threat);
    pose = { x: next.x, z: next.z, facing: next.facing };
    if (state.fleeSeconds <= 0) break;
  }
  assert.equal(state.fleeSeconds, 0, "the bolt ran its course");
  assert.ok(
    state.restSeconds > 0,
    "an animal that has just bolted owes itself a pause when it arrives, not a zero timer",
  );
  // The breather, derived rather than pinned: the pause banked after a bolt is
  // this species' own shortest pause plus the time it spends winded, so a
  // retuning of either moves the expectation with it.
  assert.ok(
    state.restSeconds >= deer.restSeconds.min + deer.fleeRecoverySeconds - 1e-9,
    "and it is longer than an ordinary one, because it is blown",
  );

  // End to end: over a long threatened run no arrival takes a zero pause.
  const longRandom = makeWildlifeRng(wildlifeSeed("no-zero-pause"));
  const longState = initialRoamState(profile, longRandom);
  const ring = [{ x: 14, z: 0 }, { x: -14, z: 0 }, { x: 0, z: 14 }, { x: 0, z: -14 }];
  let longPose = { x: 0, z: 0, facing: 0 };
  let standing = 0;
  let arrivals = 0;
  let zeroPauses = 0;
  // Long enough for a useful number of arrivals *at any tuning*: one cycle is a
  // pause (its longest, plus the post-bolt breather) and a walk across the herd's
  // ground, all read from the table. A fixed tick count would silently stop
  // sampling the moment somebody lengthened `restSeconds`.
  const cycleSeconds = deer.restSeconds.max + deer.fleeRecoverySeconds
    + (profile.roamRadius * 2) / profile.walkSpeed;
  const runTicks = Math.ceil((40 * cycleSeconds) / step);
  for (let tick = 0; tick < runTicks; tick += 1) {
    const nearest = ring.reduce((best, point) =>
      Math.hypot(point.x - longPose.x, point.z - longPose.z)
        < Math.hypot(best.x - longPose.x, best.z - longPose.z) ? point : best);
    const beforeX = longState.targetX;
    const beforeZ = longState.targetZ;
    const wasFleeing = longState.fleeSeconds > 0;
    const next = advanceRoam(longState, longPose, profile, step, longRandom, nearest);
    if (!wasFleeing && (longState.targetX !== beforeX || longState.targetZ !== beforeZ)) {
      arrivals += 1;
      if (standing === 0) zeroPauses += 1;
      standing = 0;
    }
    standing = next.speed <= 0 ? standing + 1 : 0;
    longPose = { x: next.x, z: next.z, facing: next.facing };
  }
  assert.ok(arrivals > 20, `the run has to contain arrivals to say anything (${arrivals})`);
  assert.equal(zeroPauses, 0, `${zeroPauses} of ${arrivals} arrivals took no pause at all`);
});

check("locomotion Faz 2: how long an animal stands comes from its species", () => {
  // §2.5 for the pause half: the shared `2.5..7` constant made a cow settle for
  // exactly as long as a fox. Bounds are read from each species' own row, so
  // this asserts the *derivation* and never a duration — retune the table and it
  // still holds.
  const animals = shippedAnimalBalance();
  const step = 1 / 30;
  const observed = new Map<string, number[]>();
  for (const stats of Object.values(animals)) {
    const profile = wildProfileFor(stats, 0, 0);
    const random = makeWildlifeRng(wildlifeSeed(`rest:${stats.id}`));
    const state = initialRoamState(profile, random);
    let pose = { x: 0, z: 0, facing: 0 };
    let standing = 0;
    const pauses: number[] = [];
    // Undisturbed, so every pause is a plain roll rather than one carrying the
    // post-bolt breather. The run length is derived from this species' own
    // numbers for the reason above: a fixed one stops sampling as soon as the
    // table is retuned upward.
    const cycleSeconds = stats.restSeconds.max + (profile.roamRadius * 2) / profile.walkSpeed;
    const runTicks = Math.ceil((40 * cycleSeconds) / step);
    for (let tick = 0; tick < runTicks; tick += 1) {
      const beforeX = state.targetX;
      const next = advanceRoam(state, pose, profile, step, random, null);
      if (state.targetX !== beforeX && standing > 0) {
        pauses.push(standing * step);
        standing = 0;
      }
      standing = next.speed <= 0 ? standing + 1 : 0;
      pose = { x: next.x, z: next.z, facing: next.facing };
    }
    assert.ok(pauses.length > 20, `${stats.id} produced too few pauses to judge`);
    for (const pause of pauses) {
      // The upper bound carries the pivot: a departure spends its turn standing
      // still, and that time is part of what the player sees as the pause. Half a
      // turn at this species' rate is the most it can ever add.
      const pivotCeiling = 180 / stats.turnRateDegPerSecond;
      assert.ok(
        pause >= stats.restSeconds.min - step
        && pause <= stats.restSeconds.max + pivotCeiling + step,
        `${stats.id} stood ${pause.toFixed(2)}s, outside its own ${stats.restSeconds.min}..${stats.restSeconds.max} range`,
      );
    }
    observed.set(stats.id, pauses);
  }
  // And the table really does distinguish them, or everything above is vacuous.
  const cow = animals.cow ?? assert.fail("cow balance missing");
  const fox = animals.fox ?? assert.fail("fox balance missing");
  const authoredMean = (range: { min: number; max: number }): number => (range.min + range.max) / 2;
  assert.ok(
    authoredMean(cow.restSeconds) > authoredMean(fox.restSeconds),
    "the shipped table has to separate a settled grazer from a restless one for this to mean anything",
  );
  const mean = (values: number[]): number => values.reduce((sum, v) => sum + v, 0) / values.length;
  assert.ok(
    mean(observed.get("cow") ?? []) > mean(observed.get("fox") ?? []),
    "so the cow is observed standing longer than the fox",
  );
});

check("locomotion Faz 2: a standing animal's job comes from what it is, not from its speed", () => {
  // §3.3, the reason a wolf grazed. `wildlifeView` sent `working: speed <= 0`,
  // `classifyRtsAnimation` returns `work` before `idle`, and every species'
  // `work` clip is `Eating` — so the predator V3 added spent its whole patrol
  // eating grass. Speed cannot answer this; the species can.
  const animals = shippedAnimalBalance();
  const wildlife = new WildlifeSystem(animals, Object.values(animals).map((stats, index) => ({
    id: `herd:${stats.id}`,
    species: stats.id,
    x: index * 60,
    z: 0,
    count: 1,
  })));
  const field = new Group();
  const view = new WildlifeView(field);
  const working = new Map<string, boolean>();
  let animalUnderTest = "";
  view.setPresentationFactory(() => {
    const species = animalUnderTest;
    return {
      root: new Object3D(),
      pickTargets: [],
      selectionRadius: 0.5,
      dispose: () => {},
      update: (input) => { working.set(species, input.working === true); },
    };
  });

  for (const animal of wildlife.all()) {
    animalUnderTest = animal.stats.id;
    animal.speed = 0; // standing, which is the only case in question
    const carnivore = animal.stats.predator !== undefined;
    assert.equal(
      animal.activity,
      carnivore ? "alert" : "grazing",
      `a standing ${animal.stats.id} is ${carnivore ? "watching" : "eating"}`,
    );
    view.sync([animal], 1 / 30, null);
    assert.equal(
      working.get(animal.stats.id),
      !carnivore,
      `${animal.stats.id} must ${carnivore ? "not " : ""}be sent to the work role while standing`,
    );
    // And the role that flag produces: no carnivore may ever reach `work`, which
    // is the clip slot every sidecar fills with `Eating`.
    const tuning = rtsLocomotionTuning(animal.stats.moveSpeed, {
      walkClipSpeed: animal.stats.walkClipSpeed,
    });
    const role = classifyRtsAnimation(
      { planarSpeed: 0, deltaSeconds: 1 / 30, working: !carnivore },
      tuning,
    );
    assert.equal(role, carnivore ? "idle" : "work", `${animal.stats.id} standing plays the ${role} role`);
  }
  view.dispose();
});

check("locomotion Faz 4: a turn rate does not put prey out of a hunter's reach", () => {
  // §9's first risk, as a measurement rather than a hope. `validateGameData`'s
  // catchability inequality compares a bolt against what a hunter closes while
  // the animal is winded — and it knows nothing about turning. If the turn rate
  // changed the effective escape distance, only a run can say so.
  const deer = shippedAnimalBalance().deer ?? assert.fail("deer balance missing");
  const profile = wildProfileFor(deer, 0, 0);
  const step = 1 / 30;
  const random = makeWildlifeRng(wildlifeSeed("catchable"));
  const state = initialRoamState(profile, random);
  let pose = { x: 0, z: 0, facing: 0 };
  // The slowest thing that may hunt, so passing here passes for every worker.
  const hunterSpeed = 6;
  let hunter = { x: profile.roamRadius, z: 0 };
  let caught = false;
  for (let tick = 0; tick < 60 * 30; tick += 1) {
    const next = advanceRoam(state, pose, profile, step, random, hunter);
    pose = { x: next.x, z: next.z, facing: next.facing };
    const dx = pose.x - hunter.x;
    const dz = pose.z - hunter.z;
    const distance = Math.hypot(dx, dz);
    if (distance <= CAUGHT_DISTANCE) { caught = true; break; }
    const walk = Math.min(hunterSpeed * step, distance);
    hunter = { x: hunter.x + (dx / distance) * walk, z: hunter.z + (dz / distance) * walk };
  }
  assert.ok(caught, "a hunter still corners a deer inside a minute after the turn rate landed");
});

check("V3 Faz 1: every shipped species owns a sidecar and an actor", () => {
  // The clip-name test above scans whatever sidecars happen to be on disk, so it
  // is silent about one that was never written. This is the other half: a species
  // in the balance table with no rig is a herd marker that authors cleanly and
  // then draws nothing, which is the failure that looks like the level adapter
  // dropping the marker rather than like a missing file.
  const content = JSON.parse(
    readFileSync("public/game-data/content/rts-content.json", "utf8"),
  ) as { animals?: Record<string, { actorRef?: string }> };
  const manifest = JSON.parse(readFileSync("public/assets/manifest.json", "utf8")) as {
    assets: { id: string; path: string }[];
  };
  for (const id of Object.keys(shippedAnimalBalance())) {
    const actorRef = content.animals?.[id]?.actorRef
      ?? assert.fail(`rts-content.json has no actorRef for species "${id}"`);
    const actor = JSON.parse(readFileSync(`public/${actorRef}`, "utf8")) as {
      components: { component: string; props?: { assetId?: string } }[];
    };
    const mesh = actor.components.find((component) => component.component === "SkeletalMeshComponent")
      ?? assert.fail(`${actorRef} has no skeletal mesh`);
    const assetId = mesh.props?.assetId ?? assert.fail(`${actorRef} names no assetId`);
    const entry = manifest.assets.find((asset) => asset.id === assetId)
      ?? assert.fail(`${actorRef} names assetId "${assetId}", which the manifest does not carry`);
    const sidecar = entry.path.replace(/\.gltf$/, ".skeleton.json");
    assert.notEqual(sidecar, entry.path, `${assetId} is a .gltf the sidecar convention applies to`);
    assert.ok(existsSync(`public/${sidecar}`), `species "${id}" needs ${sidecar}`);
  }
});

check("V3 Faz 1: the predator block describes a hunter that can actually hunt", () => {
  const animals = shippedAnimalBalance();
  const predators = Object.values(animals).filter((stats) => stats.predator);
  assert.ok(predators.length > 0, "V3 ships at least one predator");

  const units = validateUnitBalance(
    JSON.parse(readFileSync("public/game-data/balance/units.json", "utf8")) as unknown,
  );
  const fastestWorker = Math.max(
    ...Object.values(units).filter((unit) => unit.role === "worker").map((unit) => unit.moveSpeed),
  );
  assert.ok(Number.isFinite(fastestWorker) && fastestWorker > 0, "units.json ships a worker to be chased");

  for (const stats of predators) {
    const predator = stats.predator ?? assert.fail("filtered above");

    // Speed contract, computed from both tables rather than pinned: a predator
    // slower than the worker it is hunting never lands a bite, and the whole
    // feature dies quietly — no error, just a wolf trailing a worker forever.
    assert.ok(
      stats.moveSpeed > fastestWorker,
      `${stats.id} moves ${stats.moveSpeed}, no faster than the ${fastestWorker}-speed worker it hunts`,
    );

    // Range contract, from the species' own two fields. The leash is measured
    // from the den and the patrol circle is too, so a leash inside the circle
    // means the chase is abandoned before it begins.
    assert.ok(
      predator.pursuitRadius > stats.roamRadius,
      `${stats.id} patrols ${stats.roamRadius} but only pursues to ${predator.pursuitRadius}`,
    );
    assert.ok(predator.acquisitionRadius > 0, `${stats.id} must be able to see a victim`);

    // Locality, the forest lesson again: a leash at map scale is a wolf that
    // follows a worker home rather than a den that is dangerous to walk past.
    assert.ok(
      predator.pursuitRadius < RTS_WORLD_HALF_EXTENT / 2,
      `${stats.id} pursues ${predator.pursuitRadius}, which is map-scale rather than local`,
    );

    // V3 §2.1: a predator patrols, it does not graze. Both bounds are computed
    // from the presentation's own calibration rather than pinned, because both
    // failures are things you only ever see on screen: below the grazing drift
    // the wolf reads as a deer wearing the wrong model, and at or above the
    // walk/run boundary it spends its entire patrol in the gallop clip.
    const tuning = rtsLocomotionTuning(stats.moveSpeed, { walkClipSpeed: stats.walkClipSpeed });
    assert.ok(
      predator.patrolSpeed > stats.walkClipSpeed,
      `${stats.id} patrols at ${predator.patrolSpeed}, no faster than the ${stats.walkClipSpeed} its prey grazes at`,
    );
    assert.ok(
      predator.patrolSpeed < tuning.runSpeed,
      `${stats.id} patrols at ${predator.patrolSpeed}, at or past the ${tuning.runSpeed} where it breaks into a gallop`,
    );
    // And the resulting playback rate has to be one the clamp will actually
    // honour, or the legs stop keeping up with the ground at exactly the pace
    // this field exists to set.
    const patrolRate = rtsPlaybackRate("walk", predator.patrolSpeed, tuning);
    assert.ok(
      Math.abs(patrolRate - predator.patrolSpeed / stats.walkClipSpeed) < 1e-9,
      `${stats.id}'s patrol rate is clamped, so its feet slide at its own patrol speed`,
    );
    assert.ok(patrolRate > 1, `${stats.id} plays its walk clip faster than a grazer does`);

    // KARAR 5: prey is wild game, never the livestock V2 let the player earn.
    for (const prey of predator.preySpecies) {
      const target = animals[prey] ?? assert.fail(`${stats.id} names unknown prey "${prey}"`);
      assert.equal(target.tameable, false, `${stats.id} must not hunt the tameable "${prey}"`);
    }
    assert.equal(stats.tameable, false, `${stats.id} is a predator and cannot also be driven into a pen`);
  }
});

check("V3 Faz 1: a predator is hunted by the same rules as its prey (KARAR 2 opened no exemption)", () => {
  // The whole reason KARAR 2 made the wolf huntable: the catchability inequality
  // in `validateAnimalBalance` stays a rule for *every* species, so no "predator
  // exemption" back door exists to quietly switch off the next species' flee
  // balance. This pins that the shipped predator satisfies it unchanged, and
  // that the validator still enforces it when a predator breaks it.
  const animals = shippedAnimalBalance();
  const fastestWorker = 6; // Only the shape below depends on this; magnitudes come from the table.
  for (const stats of Object.values(animals)) {
    assert.ok(stats.meatCapacity > 0, `${stats.id} is huntable and yields food`);
    assert.ok(
      fastestWorker * stats.fleeRecoverySeconds > stats.moveSpeed * stats.fleeSeconds,
      `${stats.id} bolts further than a hunter can close`,
    );
  }

  const uncatchablePredator = {
    ...JSON.parse(readFileSync("public/game-data/balance/animals.json", "utf8")) as Record<string, unknown>,
  };
  const wolf = uncatchablePredator["wolf"] as Record<string, unknown>;
  uncatchablePredator["wolf"] = { ...wolf, fleeSeconds: 60 };
  assert.throws(
    () => validateAnimalBalance(uncatchablePredator),
    GameDataError,
    "being a predator does not exempt a species from being catchable",
  );
});

check("V3 Faz 1: the validator refuses a predator block that cannot work", () => {
  const table = JSON.parse(readFileSync("public/game-data/balance/animals.json", "utf8")) as Record<string, unknown>;
  const wolf = table["wolf"] as Record<string, unknown>;
  const predator = wolf["predator"] as Record<string, unknown>;
  const withPredator = (patch: Record<string, unknown> | undefined) => ({
    ...table,
    wolf: { ...wolf, ...(patch === undefined ? { predator: undefined } : { predator: { ...predator, ...patch } }) },
  });

  // Non-positive is nonsense in every field, at any tuning.
  for (const key of
    ["acquisitionRadius", "damage", "attacksPerMinute", "pursuitRadius", "patrolSpeed"] as const) {
    for (const bad of [0, -1]) {
      assert.throws(() => validateAnimalBalance(withPredator({ [key]: bad })), GameDataError, `${key} = ${bad}`);
    }
    assert.throws(() => validateAnimalBalance(withPredator({ [key]: undefined })), GameDataError, `${key} missing`);
  }

  // A patrol at or below the grazing drift is not a patrol.
  assert.throws(
    () => validateAnimalBalance(withPredator({ patrolSpeed: wolf["walkClipSpeed"] as number })),
    GameDataError,
  );

  // The two relationship rules, both of which read as pathfinding faults in play.
  const roamRadius = (wolf["roamRadius"] as number);
  assert.throws(() => validateAnimalBalance(withPredator({ pursuitRadius: roamRadius })), GameDataError);
  assert.throws(
    () => validateAnimalBalance(withPredator({ pursuitRadius: RTS_WORLD_HALF_EXTENT })),
    GameDataError,
  );

  // A prey list is a set of real, wild, other species.
  assert.throws(() => validateAnimalBalance(withPredator({ preySpecies: "deer" })), GameDataError);
  assert.throws(() => validateAnimalBalance(withPredator({ preySpecies: ["dragon"] })), GameDataError);
  assert.throws(() => validateAnimalBalance(withPredator({ preySpecies: ["wolf"] })), GameDataError);
  assert.throws(() => validateAnimalBalance(withPredator({ preySpecies: ["deer", "deer"] })), GameDataError);

  // KARAR 5 as a data rule, not a runtime one.
  assert.throws(
    () => validateAnimalBalance({ ...table, wolf: { ...wolf, tameable: true } }),
    GameDataError,
    "a predator cannot also be tameable",
  );

  // And the block stays optional: dropping it leaves a legal grazing species.
  const grazing = validateAnimalBalance(withPredator(undefined));
  assert.equal(grazing.wolf?.predator, undefined);
  assert.ok(grazing.fox && !grazing.fox.predator, "the fox ships as ambience, carrying no predator block");
});

check("wildlife never counts against a kingdom's population", () => {
  // The reason wildlife is its own system rather than a third `UnitOwner`
  // (wildlife plan §3.5/§4.2): population is `units.unitsOf(owner).length`, so a
  // deer registered as a Unit would silently eat a supply slot that nothing on
  // screen explains. Pinned here because the "simplification" that breaks it —
  // folding animals into UnitSystem — looks like a cleanup, not a regression.
  const units = new UnitSystem();
  const structures = new PlacedStructureSystem();
  const population = new PopulationSystem("player", units, structures, 10);

  units.spawn("player", 0, 0, RTS_TEST_WORKER_STATS);
  const before = population.snapshot();
  assert.equal(before.current, 1, "the worker is the only thing counted so far");

  // V3 Faz 3 adds the predator to the same list, and for the same reason it was
  // worth stating for the deer: a wolf is the animal most likely to be "promoted"
  // to a Unit some day, because it is the one that fights — and the day it is,
  // three wolves would quietly cost a kingdom three soldiers' worth of supply.
  const wildlife = new WildlifeSystem(shippedAnimalBalance(), [
    { id: "test-herd", species: "deer", x: 0, z: 0, count: 6 },
    { id: "test-den", species: "wolf", x: 4, z: 0, count: 3 },
  ]);
  wildlife.update(1);
  assert.equal(wildlife.all().length, 9, "the herd and the pack really did populate the field");
  assert.deepEqual(
    population.snapshot(),
    before,
    "six deer and a wolf pack standing next to the worker change nothing about population",
  );
});

check("a herd stays a local cluster its hunters could be built beside", () => {
  // The forest's gather-radius lesson generalised: a source that spreads across
  // the map is not a source, it is one global pool. An animal that wandered out
  // of its herd's circle would be unreachable from any camp sited on that herd,
  // so the circle is the contract — checked over a long run, not one step.
  const balance = shippedAnimalBalance();
  const deer = balance.deer ?? assert.fail("the shipped table defines deer");
  const wildlife = new WildlifeSystem(balance, [
    { id: "drift-herd", species: "deer", x: 12, z: -8, count: 5 },
  ]);
  for (let tick = 0; tick < 4000; tick += 1) wildlife.update(0.1);

  for (const animal of wildlife.snapshots()) {
    const distance = Math.hypot(animal.x - 12, animal.z - -8);
    assert.ok(
      distance <= deer.roamRadius + 1e-6,
      `${animal.id} strayed ${distance.toFixed(2)} from a herd whose radius is ${deer.roamRadius}`,
    );
  }
});

check("grazing reads as walking, at playback rate 1, and repeats identically", () => {
  const balance = shippedAnimalBalance();

  for (const species of Object.values(balance)) {
    // Grazing speed has to land between the animation selector's walk and run
    // thresholds, or a herd either freezes into statues or stampedes on the
    // spot. Derived from the same table as the behaviour, so it holds at any
    // tuning rather than pinning today's numbers.
    const tuning = rtsLocomotionTuning(species.moveSpeed, { walkClipSpeed: species.walkClipSpeed });
    assert.ok(
      species.walkClipSpeed > tuning.walkSpeed,
      `${species.id} grazes fast enough to read as moving`,
    );
    assert.ok(
      species.walkClipSpeed < tuning.runSpeed,
      `${species.id} grazes slowly enough not to read as galloping`,
    );

    // The foot-slide contract, and the reason grazing speed *is* the clip speed:
    // an animal drawn at an authored model scale cannot use the engine's
    // "natural at half move speed" default. Pinning the two together makes the
    // rate exactly 1 at every tuning, so the feet plant where the animator put
    // them. Slowing the animal down would not have fixed this — the rate is
    // speed/clipSpeed, so it scales with the speed and the mismatch survives.
    assert.equal(
      rtsPlaybackRate("walk", species.walkClipSpeed, tuning),
      1,
      `${species.id} plays its walk clip at its authored pace`,
    );
  }

  const deer = balance.deer ?? assert.fail("the shipped table defines deer");
  assert.ok(deer.walkClipSpeed < deer.moveSpeed, "an animal flees faster than it grazes");

  // Seeded, not `Math.random`: where a deer wandered decides whether a hunter
  // can reach it, so it is simulation and the headless AI must see the same
  // field the player does.
  const definitions = [{ id: "same-herd", species: "deer", x: 4, z: 4, count: 4 }];
  const left = new WildlifeSystem(balance, definitions);
  const right = new WildlifeSystem(balance, definitions);
  for (let tick = 0; tick < 120; tick += 1) {
    left.update(0.2);
    right.update(0.2);
  }
  assert.deepEqual(left.snapshots(), right.snapshots(), "the same herd grazes identically twice");
});

check("a grazing animal stands still long enough to play its eating clip", () => {
  // The roam step must actually come to rest, not creep forever: standing still
  // is what puts the animal on the `work` role, which is what plays `Eating`.
  const profile = { homeX: 0, homeZ: 0, roamRadius: 8, walkSpeed: 1.5 };
  const random = makeWildlifeRng(7);
  const state = initialRoamState(profile, random);
  let pose = { x: 0, z: 0, facing: 0 };
  let restedTicks = 0;
  for (let tick = 0; tick < 600; tick += 1) {
    const next = advanceRoam(state, pose, profile, 0.1, random);
    pose = { x: next.x, z: next.z, facing: next.facing };
    if (next.speed === 0) restedTicks += 1;
  }
  assert.ok(restedTicks > 0, "the animal grazes rather than pacing without pause");
});

check("wildlife herds and their art are cross-checked against the balance table", () => {
  const balance = shippedAnimalBalance();
  const catalog = shippedRtsContentCatalog();

  // Every shipped species must resolve to art. A species that does not is a herd
  // of nothing at spawn, long after the catalog stopped being reported on.
  for (const species of Object.keys(balance)) {
    assert.ok(
      rtsAnimalActorRef(catalog, species),
      `species "${species}" resolves to an Actor`,
    );
  }

  // And the refusals, so a typo fails the load instead of the match.
  assert.throws(
    () => new WildlifeSystem(balance, [{ id: "h", species: "dragon", x: 0, z: 0, count: 2 }]),
    /unknown species/,
    "a herd of an unknown species is refused",
  );
  assert.throws(
    () => new WildlifeSystem(balance, [
      { id: "h", species: "deer", x: 0, z: 0, count: 1 },
      { id: "h", species: "stag", x: 5, z: 5, count: 1 },
    ]),
    /Duplicate herd/,
    "two herds cannot share an id",
  );
});

check("every shipped RTS Level authors the herds the blockout promises", () => {
  // The Level is the spatial authority for the `?rts` route, not the blockout
  // fallback — so wildlife added to `RTS_BLOCKOUT_MAP` alone would grazes in a
  // map nobody plays. A Level regenerated without its herd markers is exactly
  // the silent loss this pins.
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const resources = validateResourceBalance(
    JSON.parse(readFileSync("public/game-data/balance/resources.json", "utf8")) as unknown,
  );
  const animals = shippedAnimalBalance();

  for (const name of ["RTS_CoreMatch", "RTS_GameplayProof"]) {
    const layout = JSON.parse(
      readFileSync(`public/assets/ThreeAges/Levels/${name}.level.json`, "utf8"),
    ) as {
      actors: Array<{
        classRef: string;
        position: [number, number, number];
        variableOverrides?: Record<string, string | number | boolean | string[]>;
      }>;
      splines: Parameters<typeof adaptRtsLevel>[1];
    };
    const actors = layout.actors.map((instance, index) => ({
      index,
      instance,
      def: normalizeActorScriptDef(
        JSON.parse(readFileSync(`public/${instance.classRef}`, "utf8")) as unknown,
        instance.classRef,
      ),
    }));
    const level = adaptRtsLevel(actors, layout.splines, { buildings, resources, animals });
    assert.ok(level.herds.length > 0, `${name} authors at least one herd`);
    for (const herd of level.herds) {
      assert.ok(animals[herd.species], `${name}: herd "${herd.id}" names a known species`);
      assert.ok(herd.count > 0, `${name}: herd "${herd.id}" holds animals`);
    }
    // The whole point of the wildlife axis, and Faz 7's level contract: what is
    // safe is small and what is rich is out in the open. Both halves have to be
    // on the map or the lesson is not there to learn — a map whose only herd sits
    // in a base teaches "hunting is free", and one whose only herd is in the
    // middle teaches "hunting is an expansion", neither of which is the design.
    //
    // Measured against the starting control radius rather than a literal, so
    // retuning that radius moves the goalposts here too.
    const starts = [level.playerStart, level.enemyStart];
    for (const start of starts) {
      assert.ok(
        level.herds.some(
          (herd) => Math.hypot(herd.x - start.x, herd.z - start.z) < COMMAND_CENTER_CONTROL_RADIUS,
        ),
        `${name} opens every kingdom with game inside its own starting ground`,
      );
    }
    assert.ok(
      level.herds.some((herd) => starts.every(
        (start) => Math.hypot(herd.x - start.x, herd.z - start.z) > COMMAND_CENTER_CONTROL_RADIUS,
      )),
      `${name} puts at least one herd outside both starting control radii`,
    );

    // V2 Faz 2. Cattle answer a different question from deer: deer are food you
    // spend, cattle are food you *keep*, so a herd of them is worth expanding to
    // and worth denying. Both halves are pinned — that the species is on the map
    // at all (a Level regenerated without it leaves the pasture nothing to work),
    // and that none of it is free.
    const tameable = level.herds.filter((herd) => animals[herd.species]?.tameable);
    assert.ok(tameable.length > 0, `${name} authors game the pasture can actually tame`);
    for (const herd of tameable) {
      assert.ok(
        starts.every((start) => Math.hypot(herd.x - start.x, herd.z - start.z) > COMMAND_CENTER_CONTROL_RADIUS),
        `${name}: cattle herd "${herd.id}" is contested rather than sitting in a starting ground`,
      );
    }

    // V3 Faz 2. A den has to be on the map at all — the predator is the whole
    // version, and a Level regenerated without its wolves loses it silently
    // while every test about wolf *data* stays green.
    const dens = level.herds.filter((herd) => animals[herd.species]?.predator);
    assert.ok(dens.length > 0, `${name} authors the predator dens V3 adds`);
    for (const den of dens) {
      const predator = animals[den.species]?.predator ?? assert.fail("filtered above");
      // KARAR 1 is a rule about ground nobody owns, so it says nothing at all if
      // the pack patrols a kingdom's opening ground. Measured with the patrol
      // circle included, not just the den's centre: a wolf standing on the rim
      // is as much inside a base as one standing on the marker.
      for (const start of starts) {
        assert.ok(
          Math.hypot(den.x - start.x, den.z - start.z)
            > COMMAND_CENTER_CONTROL_RADIUS + animals[den.species]!.roamRadius,
          `${name}: den "${den.id}" patrols into a starting ground, where KARAR 1 forbids it to hunt`,
        );
      }
      // KARAR 3: the pack never comes back, so it has to be worth the walk once.
      assert.ok(den.count > 1, `${name}: den "${den.id}" is a pack rather than a lone wolf`);
      // Locality again, from the den's own leash: a pack whose reach covers a
      // start is not a dangerous place, it is a wolf that follows you home.
      for (const start of starts) {
        assert.ok(
          Math.hypot(den.x - start.x, den.z - start.z) > predator.pursuitRadius,
          `${name}: den "${den.id}" can chase into a starting ground`,
        );
      }
    }
  }
});

check("V3 Faz 2: the dens threaten both kingdoms as evenly as the map allows", () => {
  // The same fairness rule the cattle get, applied to the version's risk rather
  // than to its reward: if one kingdom's road out is guarded and the other's is
  // not, the wolf is not pressure, it is a handicap.
  //
  // Stated against the *map's own* skew rather than against zero, which is what
  // lets one rule cover all three layouts. The blockout's starts are symmetric by
  // construction, so its existing herds are exactly fair and the dens must be
  // too. `RTS_GameplayProof` authors its player start at (-40, 40) against an
  // enemy at (38, -38) — measured — and every herd on it already inherits that
  // two-unit skew, which the V2 fairness test records as map balance and out of
  // scope. So what is refused here is the thing V3 could actually do wrong:
  // dragging a den somewhere that makes the map *less* even than it already was.
  // Compared as multisets of distances, derived, never pinned to a number.
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const resources = validateResourceBalance(
    JSON.parse(readFileSync("public/game-data/balance/resources.json", "utf8")) as unknown,
  );
  const animals = shippedAnimalBalance();

  /**
   * The worst gap between what one kingdom walks and what the other walks, over
   * the two sorted distance lists. Zero is a perfectly mirrored layout.
   */
  const skew = (
    herds: readonly { x: number; z: number }[],
    playerStart: { x: number; z: number },
    enemyStart: { x: number; z: number },
    navigationBlockers: readonly NavBlocker[],
  ): number => {
    // The contract says *walking* distance. The ridge/river can make a straight
    // line look fair while one kingdom actually walks a longer flank, so route
    // through the same grid the match uses instead of measuring a ruler line.
    const navigation = new RtsNavigation();
    navigation.setBlockers(navigationBlockers);
    const walks = (start: { x: number; z: number }) => herds
      .map((herd) => {
        const path = navigation.plan(new Vector3(start.x, 0, start.z), new Vector3(herd.x, 0, herd.z));
        assert.ok(path, "every authored wolf den must be reachable on the match navigation grid");
        return path.slice(1).reduce(
          (distance, point, index) => distance + point.distanceTo(path[index] ?? point),
          0,
        );
      })
      .sort((left, right) => left - right);
    const fromPlayer = walks(playerStart);
    const fromEnemy = walks(enemyStart);
    let worst = 0;
    for (let index = 0; index < fromPlayer.length; index += 1) {
      worst = Math.max(worst, Math.abs((fromPlayer[index] ?? 0) - (fromEnemy[index] ?? 0)));
    }
    return worst;
  };

  const layouts: { readonly name: string; readonly herds: readonly { species: string; x: number; z: number }[];
    readonly playerStart: { x: number; z: number }; readonly enemyStart: { x: number; z: number };
    readonly navigationBlockers: readonly NavBlocker[] }[] = [];
  const blockout = resolveRtsSpatialLayout();
  layouts.push({
    name: "RTS_BLOCKOUT_MAP",
    herds: blockout.herds,
    playerStart: blockout.playerStart,
    enemyStart: blockout.enemyStart,
    navigationBlockers: blockout.navigationBlockers,
  });
  for (const name of ["RTS_CoreMatch", "RTS_GameplayProof"]) {
    const layout = JSON.parse(
      readFileSync(`public/assets/ThreeAges/Levels/${name}.level.json`, "utf8"),
    ) as {
      actors: Array<{
        classRef: string;
        position: [number, number, number];
        variableOverrides?: Record<string, string | number | boolean | string[]>;
      }>;
      splines: Parameters<typeof adaptRtsLevel>[1];
    };
    const actors = layout.actors.map((instance, index) => ({
      index,
      instance,
      def: normalizeActorScriptDef(
        JSON.parse(readFileSync(`public/${instance.classRef}`, "utf8")) as unknown,
        instance.classRef,
      ),
    }));
    const level = adaptRtsLevel(actors, layout.splines, { buildings, resources, animals });
    layouts.push({
      name,
      herds: level.herds,
      playerStart: level.playerStart,
      enemyStart: level.enemyStart,
      navigationBlockers: level.navigationBlockers,
    });
  }

  for (const layout of layouts) {
    const dens = layout.herds.filter((herd) => animals[herd.species]?.predator);
    const grazing = layout.herds.filter((herd) => !animals[herd.species]?.predator);
    assert.ok(dens.length > 0, `${layout.name} carries the predator dens`);
    assert.ok(dens.length % 2 === 0, `${layout.name}: dens come in mirrored pairs`);

    const denSkew = skew(dens, layout.playerStart, layout.enemyStart, layout.navigationBlockers);
    const mapSkew = skew(grazing, layout.playerStart, layout.enemyStart, layout.navigationBlockers);
    assert.ok(
      denSkew <= mapSkew + 1e-3,
      `${layout.name}: the dens are ${denSkew.toFixed(2)} apart for the two kingdoms, worse than the `
      + `${mapSkew.toFixed(2)} skew the map's own herds already carry`,
    );
  }

  // And on the layout where the starts *are* symmetric, "no worse" has to mean
  // exactly fair — otherwise the rule above would pass a blockout that quietly
  // gained a skew, because it would be comparing against itself.
  const blockoutLayout = layouts[0] ?? assert.fail("blockout layout missing");
  assert.equal(blockoutLayout.name, "RTS_BLOCKOUT_MAP");
  assert.ok(
    skew(
      blockoutLayout.herds.filter((herd) => animals[herd.species]?.predator),
      blockoutLayout.playerStart,
      blockoutLayout.enemyStart,
      blockoutLayout.navigationBlockers,
    ) < 0.001,
    "the blockout's symmetric starts make its dens exactly fair",
  );
});

check("V2 Faz 2: the authored herd layout offers both kingdoms the same walks to game", () => {
  // Fairness, stated as the only thing it can mean for a resource both sides
  // race for: the two kingdoms face the *same multiset* of walks. Derived from
  // the table rather than pinned, so it survives any retuning of where the herds
  // sit — what it refuses is dragging one marker and quietly handing one side a
  // shorter opening.
  //
  // Worth pinning because fairness here is reached in *pairs*, not by putting a
  // herd in the middle: the perfectly equidistant points all lie on the x = z
  // diagonal, and measured, that diagonal is `RTS_GameplayProof`'s river. So each
  // herd is mirrored across the map centre by another — the deer by the deer, the
  // stag by the bull, the cattle by the cattle — and one misplaced marker is
  // exactly what breaks that.
  //
  // Asserted against the blockout rather than the Levels because the blockout is
  // where this layout is designed and its two starts are symmetric by
  // construction. `RTS_GameplayProof` authors its player start at (-40, 40)
  // against an enemy at (38, -38) — measured — so its herds inherit a two-unit
  // skew that has nothing to do with wildlife. Levelling that is map balance, out
  // of scope here (V1 §7).
  const walks = (start: { readonly x: number; readonly z: number }): number[] => RTS_BLOCKOUT_MAP.herds
    .map((herd) => Math.hypot(herd.x - start.x, herd.z - start.z))
    .sort((a, b) => a - b);
  const fromPlayer = walks(RTS_BLOCKOUT_MAP.playerStart);
  const fromEnemy = walks(RTS_BLOCKOUT_MAP.enemyStart);
  assert.equal(fromPlayer.length, fromEnemy.length);
  for (let index = 0; index < fromPlayer.length; index += 1) {
    assert.ok(
      Math.abs((fromPlayer[index] ?? 0) - (fromEnemy[index] ?? 0)) < 0.001,
      "both kingdoms face the same set of walks to game "
      + `(${(fromPlayer[index] ?? 0).toFixed(1)} vs ${(fromEnemy[index] ?? 0).toFixed(1)})`,
    );
  }
});

check("a carcass picked clean leaves the field, and its art is released with it", () => {
  // The felled-tree rule for wildlife. A body that stays after the last of its
  // meat is banked is not a carcass, it is litter — it lies there for the rest of
  // the match, and every hunted herd leaves a graveyard where it grazed.
  const wildlife = new WildlifeSystem(shippedAnimalBalance(), [
    { id: "herd", species: "deer", x: 0, z: 0, count: 2 },
  ]);
  const reach = { resourceId: "food", x: 0, z: 0, radius: 18 } as const;

  let disposed = 0;
  const field = new Group();
  const view = new WildlifeView(field);
  view.setPresentationFactory(() => ({
    root: new Object3D(),
    pickTargets: [],
    selectionRadius: 0.5,
    dispose: () => { disposed += 1; },
  }));
  view.sync(wildlife.all(), 0, null);
  assert.equal(field.children.length, 2, "both animals are on the field");

  // Bring one down and butcher it in one load, which is what the last trip of a
  // real hunt does — the loads before it leave meat, and the body must stay for
  // those or the hunter walks back to nothing.
  const claim = wildlife.reserveNearest(1, reach) ?? assert.fail("nothing to claim");
  const quarry = wildlife.all().find((animal) => animal.id === claim.id) ?? assert.fail("claim missing");
  quarry.health.damage(quarry.stats.maxHealth);
  const partial = quarry.stats.meatCapacity / 2;
  assert.equal(
    wildlife.harvest({ workerId: 1, sourceId: claim.id, amount: partial, deltaSeconds: 1 }).amount,
    partial,
    "half the carcass comes off in the first load",
  );
  view.sync(wildlife.all(), 0, null);
  assert.equal(field.children.length, 2, "a half-butchered carcass is still there to work");
  assert.equal(disposed, 0);

  wildlife.harvest({ workerId: 1, sourceId: claim.id, amount: partial, deltaSeconds: 1 });
  assert.equal(quarry.spent, true, "nothing is left on it");
  view.sync(wildlife.all(), 0, null);
  assert.equal(field.children.length, 1, "the spent carcass left the field");
  assert.equal(disposed, 1, "and its art was released rather than left hidden in the graph");

  // The animal record survives on purpose (the forest keeps its stumps too), so
  // a worker still holding the claim resolves it instead of hitting a hole.
  assert.ok(wildlife.positionOf(claim.id), "the simulation still knows the source id");
  // And a later sync must not hand the corpse a fresh body every frame.
  view.sync(wildlife.all(), 0, null);
  assert.equal(field.children.length, 1, "a spent animal is never redrawn");

  view.dispose();
});

check("Faz 7: fog hides a herd, and unlike a forest it hides it again when the scout leaves", () => {
  const wildlife = new WildlifeSystem(shippedAnimalBalance(), [
    { id: "home", species: "deer", x: -30, z: -30, count: 3 },
    { id: "away", species: "deer", x: 30, z: 30, count: 3 },
  ]);
  let sources: VisionSource[] = [{ owner: "player", x: -30, z: -30, radius: 14 }];
  const vision = new VisionSystem(() => sources, { cellSize: 2, worldHalfExtent: 60 });
  const canSee = (x: number, z: number): boolean => vision.isVisible("player", x, z);

  // The shipped loop, not a copy of it: `WildlifeView` needs no GL context, so
  // the test drives the same `sync` the game runs and reads the same `visible`
  // flags the renderer would. Bodies are matched to herds by the sign of their x,
  // which the two herd centres and a 10-unit roam radius keep unambiguous.
  const field = new Group();
  const view = new WildlifeView(field);
  view.setPresentationFactory(() => ({
    root: new Object3D(),
    pickTargets: [],
    selectionRadius: 0.5,
    dispose: () => {},
  }));

  const drawn = (herd: "home" | "away"): Object3D[] =>
    field.children.filter((body) => (herd === "home" ? body.position.x < 0 : body.position.x > 0));

  vision.refresh();
  view.sync(wildlife.all(), 0, null, canSee);
  assert.equal(field.children.length, 6, "every animal got a body to hide");
  assert.ok(drawn("home").every((body) => body.visible), "the herd under your eye is drawn");
  assert.ok(
    drawn("away").every((body) => !body.visible),
    "a herd in unscouted ground is not on the map",
  );

  // Walk the eye across the map. This is the whole reason wildlife takes the unit
  // rule rather than the forest's: a tree stays drawn once explored, but a herd
  // remembered where it grazed has moved, or been hunted out by the opponent —
  // and the camp you would place on that memory has nothing to hunt.
  sources = [{ owner: "player", x: 30, z: 30, radius: 14 }];
  vision.refresh();
  view.sync(wildlife.all(), 0, null, canSee);
  assert.equal(vision.isExplored("player", -30, -30), true, "the ground is still explored");
  assert.ok(drawn("home").every((body) => !body.visible), "yet the herd that left your sight is gone");
  assert.ok(drawn("away").every((body) => body.visible), "and the one you found is on the map");

  // Flag off: no predicate, so the whole field is drawn exactly as it was before
  // fog existed — the same "absent means nothing hides" rule the forest follows.
  view.sync(wildlife.all(), 0, null);
  assert.ok(field.children.every((body) => body.visible), "a fogless match draws every animal");
  assert.equal(isWildlifeVisible("wild", 1000, 1000, undefined), true, "and the rule itself says so");

  view.dispose();
});

check("the animal validator refuses data that could never make sense", () => {
  const sane = {
    label: "Geyik",
    meatCapacity: 120,
    maxHealth: 40,
    moveSpeed: 7.5,
    walkClipSpeed: 1.5,
    fleeRadius: 9,
    fleeSeconds: 1.5,
    fleeRecoverySeconds: 3,
    huntSeconds: 5,
    roamRadius: 10,
    turnRateDegPerSecond: 220,
    restSeconds: { min: 2.5, max: 7 },
    tameable: false,
  };
  assert.ok(validateAnimalBalance({ deer: sane }).deer, "the sane shape passes");

  for (const key of [
    "meatCapacity", "maxHealth", "moveSpeed", "walkClipSpeed", "fleeRadius", "roamRadius",
    "fleeSeconds", "fleeRecoverySeconds", "huntSeconds", "turnRateDegPerSecond",
  ] as const) {
    assert.throws(
      () => validateAnimalBalance({ deer: { ...sane, [key]: 0 } }),
      new RegExp(`${key}: must be > 0`),
      `a zero ${key} is refused, naming the field`,
    );
  }

  // Locomotion polish §8. Both ends of the turn rate: zero is covered above (an
  // animal that can never face its target), and the ceiling is the same instant
  // snap the plan removed, only spelled as a number.
  assert.throws(
    () => validateAnimalBalance({ deer: { ...sane, turnRateDegPerSecond: 721 } }),
    /turnRateDegPerSecond: 721 exceeds 720/,
    "a turn rate past half a turn per second is refused, naming the field",
  );
  assert.ok(
    validateAnimalBalance({ deer: { ...sane, turnRateDegPerSecond: 720 } }).deer,
    "and the ceiling itself is legal, so the bound is a bound rather than a magnitude",
  );
  // The pause range. A negative pause is the §3.2 fault reintroduced from the
  // table — a timer that has already expired on arrival — and an inverted range
  // is a range nothing can pick a number out of.
  for (const key of ["min", "max"] as const) {
    assert.throws(
      () => validateAnimalBalance({ deer: { ...sane, restSeconds: { ...sane.restSeconds, [key]: -1 } } }),
      new RegExp(`restSeconds\\.${key}: must be >= 0`),
      `a negative restSeconds.${key} is refused, naming the field`,
    );
    const { [key]: _dropped, ...partial } = sane.restSeconds;
    assert.throws(
      () => validateAnimalBalance({ deer: { ...sane, restSeconds: partial } }),
      /must be a finite number/,
      `a restSeconds missing ${key} is refused`,
    );
  }
  assert.throws(
    () => validateAnimalBalance({ deer: { ...sane, restSeconds: { min: 7, max: 2 } } }),
    /restSeconds: min 7 must not exceed max 2/,
    "an inverted pause range is refused, naming the file and the field",
  );
  assert.ok(
    validateAnimalBalance({ deer: { ...sane, restSeconds: { min: 0, max: 0 } } }).deer,
    "a species that never settles is a temperament, not bad data",
  );
  assert.throws(
    () => validateAnimalBalance({ deer: { ...sane, restSeconds: undefined } }),
    /restSeconds/,
    "a species that never answers how long it pauses is refused",
  );
  // A herd that roams the whole map is the "one global pool" failure again.
  assert.throws(
    () => validateAnimalBalance({ deer: { ...sane, roamRadius: 70 } }),
    /at map scale/,
    "a map-scale roam radius is refused",
  );
  // Prey outruns a worker, so a hunt only converges during the winded window.
  // Data where a bolt outlasts the recovery produces game that is chased forever
  // — a bug that presents as broken pathfinding rather than as a bad number.
  assert.throws(
    () => validateAnimalBalance({ deer: { ...sane, fleeRecoverySeconds: 0.5 } }),
    /can never be caught/,
    "a species that always outruns its hunter is refused",
  );

  // V2 taming. `tameable` is required of every species rather than defaulted:
  // omitting it must be a load failure, not a silent "no", or a new animal ships
  // un-tameable because nobody wrote the line.
  const { tameable: _omitted, ...untamed } = sane;
  assert.throws(
    () => validateAnimalBalance({ deer: untamed }),
    /tameable: must be a boolean/,
    "a species that never answers whether it tames is refused",
  );
  const cow = { ...sane, tameable: true, tameSeconds: 8, pastureYield: 1, breedSeconds: 90 };
  assert.ok(validateAnimalBalance({ cow }).cow?.tameable, "a fully answered tameable species passes");
  for (const key of ["tameSeconds", "pastureYield", "breedSeconds"] as const) {
    // Each of these is a herding bug in disguise when it is missing: no calm
    // time is prey that is walked up to and never caught, no yield is an animal
    // that stands in a pen earning nothing, no breeding is a pen that never fills.
    const { [key]: _dropped, ...incomplete } = cow;
    assert.throws(
      () => validateAnimalBalance({ cow: incomplete }),
      new RegExp(`must be a finite number`),
      `a tameable species without ${key} is refused`,
    );
    assert.throws(
      () => validateAnimalBalance({ cow: { ...cow, [key]: 0 } }),
      new RegExp(`${key}: must be > 0`),
      `a zero ${key} is refused, naming the field`,
    );
    assert.throws(
      () => validateAnimalBalance({ deer: { ...sane, [key]: 1 } }),
      new RegExp(`${key}: only a tameable species may carry it`),
      `${key} on an untameable species is refused rather than ignored`,
    );
  }

  // V2 Faz 6, fighting back. Optional and independent of taming — omission is
  // the normal answer, and V3's predator will want the block without ever being
  // tameable — but a block that is *present* has to mean something.
  assert.equal(validateAnimalBalance({ deer: sane }).deer?.retaliation, undefined, "a species may simply submit");
  assert.ok(
    validateAnimalBalance({ deer: { ...sane, retaliation: { damage: 4, attacksPerMinute: 20 } } })
      .deer?.retaliation,
    "an untameable species may still fight back",
  );
  for (const key of ["damage", "attacksPerMinute"] as const) {
    assert.throws(
      () => validateAnimalBalance({ deer: { ...sane, retaliation: { damage: 4, attacksPerMinute: 20, [key]: 0 } } }),
      new RegExp(`retaliation.${key}: must be > 0`),
      `a retaliation with no ${key} is refused rather than silently harmless`,
    );
  }
  // And how hard it hits is a tuning, not a contract: a bull that kills every
  // shepherd is something the player watches happen, unlike prey that can never
  // be caught, which only ever looks like broken pathfinding.
  assert.ok(
    validateAnimalBalance({ cow: { ...cow, retaliation: { damage: 500, attacksPerMinute: 600 } } })
      .cow?.retaliation,
    "the validator has no opinion on how hard a blow lands",
  );
});

check("Faz 4: a gathering camp's reach stays local and still covers the herd it was built for", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const camp = buildings.hunting_camp ?? assert.fail("hunting camp balance missing");
  const economy = camp.economy ?? assert.fail("a hunting camp needs an economy block");
  assert.equal(economy.requiresGame, true, "the hunting camp hunts rather than farms");
  assert.equal(economy.resourceId, "food", "hunting banks food, like the farm it competes with");
  // Reach and load size are what make the cycle a round trip rather than a
  // building that drains a herd from a distance; both must be authored.
  const reach = economy.gatherRadius ?? assert.fail("a hunting camp needs a reach");
  assert.ok(reach > 0 && (economy.carryCapacity ?? 0) > 0);

  // Range contract: a grazing animal must never wander permanently out of the
  // camp built for its herd. Computed from both tables rather than pinned, so it
  // stays true at any tuning of either.
  for (const [id, stats] of Object.entries(shippedAnimalBalance())) {
    assert.ok(
      stats.roamRadius < reach,
      `${id} roams ${stats.roamRadius}, past the hunting camp's reach of ${reach}`,
    );
  }

  // Locality, the forest lesson generalised to every finite source: a reach that
  // approaches map scale turns every herd, grove and deposit into one shared
  // pool, and *where* a camp is built stops meaning anything.
  const localLimit = RTS_WORLD_HALF_EXTENT / 2;
  for (const [id, stats] of Object.entries(buildings)) {
    const source = stats.economy;
    if (!source?.requiresGame && !source?.requiresForest && !source?.requiresResourceNode
      && !source?.requiresLivestock) continue;
    assert.ok(
      (source.gatherRadius ?? 0) < localLimit,
      `${id} reaches ${source.gatherRadius}, which is map-scale rather than local`,
    );
  }
});

check("Faz 5: one animal is claimed by one hunter, and the claim survives the chase", () => {
  const animals = shippedAnimalBalance();
  // Exactly two animals, so "the only one left free" is a claim the test can name.
  const wildlife = new WildlifeSystem(animals, [{ id: "herd", species: "deer", x: 0, z: 0, count: 2 }]);
  const reach = { resourceId: "food", x: 0, z: 0, radius: 18 } as const;

  const first = wildlife.reserveNearest(1, reach) ?? assert.fail("the first hunter found nothing to claim");
  const second = wildlife.reserveNearest(2, reach) ?? assert.fail("the second hunter found nothing to claim");
  assert.notEqual(first.id, second.id, "two hunters cannot bring down the same animal");
  assert.equal(
    wildlife.reserveNearest(1, reach)?.id,
    first.id,
    "asking again returns the animal already claimed rather than shopping around",
  );

  // Drive the claimed animal far outside the camp's reach, which is exactly what
  // a chase does. The claim has to survive it, or the hunter is sent home every
  // time his quarry does the one thing quarry does.
  const claimed = wildlife.all().find((animal) => animal.id === first.id) ?? assert.fail("claimed animal missing");
  claimed.position.set(reach.radius * 4, 0, 0);
  assert.equal(wildlife.reserveNearest(1, reach)?.id, first.id, "a bolt does not break the claim");

  wildlife.releaseReservation(1);
  // The released animal is still standing four camp-radii away, so this only
  // passes because a camp works the *herd* it was built for rather than whatever
  // is inside its circle this second.
  assert.equal(
    wildlife.reserveNearest(3, reach)?.id,
    first.id,
    "a released animal is claimable again, herd-anchored even where it ran to",
  );
  assert.equal(wildlife.reserveNearest(2, reach)?.id, second.id, "another hunter's claim is untouched");
});

check("Faz 5: a hunter runs down its quarry, butchers it, and banks exactly what the carcass held", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const camp = buildings.hunting_camp ?? assert.fail("hunting camp balance missing");
  const economy = camp.economy ?? assert.fail("hunting camp economy missing");
  const animals = shippedAnimalBalance();
  const deer = animals.deer ?? assert.fail("deer balance missing");
  // One animal, so the run has an exact expected yield derived from the table.
  const wildlife = new WildlifeSystem(animals, [{ id: "herd", species: "deer", x: 0, z: 0, count: 1 }]);
  const units = new UnitSystem();
  const structures = new PlacedStructureSystem();
  const navigation = new RtsNavigation();
  const kingdoms = new KingdomRegistry(["player"], units, structures, { food: 0, wood: 500 }, 20);
  const territory = new TerritoryControlSystem(() => [{ owner: "player", x: 0, z: 0, radius: 1000 }]);
  territory.refresh();
  const construction = new StructureConstructionService(
    buildings,
    structures,
    kingdoms,
    navigation,
    () => structures.navigationBlockers(),
    territory,
    () => {},
    () => {},
    (stats, x, z) => stats.economy?.requiresGame
      && wildlife.liveAnimalsNear(x, z, stats.economy.gatherRadius ?? 0).length === 0
      ? "missing-game"
      : null,
  );
  // On the herd itself, which is where a player puts it: with one animal the
  // spawn point is a seeded draw anywhere inside the roam circle, and a camp
  // placed off to one side can legitimately fall out of reach of it.
  const built = construction.build("player", "hunting_camp", 0, 0);
  if (!built.built) return assert.fail(`hunting camp construction failed: ${built.reason}`);
  structures.advanceConstruction(built.structure, camp.constructionSeconds);

  const hunter = units.spawn("player", 6, 0, RTS_TEST_WORKER_STATS);
  const production = new EconomyProductionSystem(
    units, structures, navigation, () => false, undefined, undefined, wildlife,
  );
  const quarry = wildlife.all()[0] ?? assert.fail("the herd spawned no animal");

  let banked = 0;
  let huntStrikes = 0;
  let depletedWhileMeatRemained = false;
  const step = 0.25;
  for (let tick = 0; tick < 4000; tick += 1) {
    wildlife.update(step, units.all().map((unit) => unit.position));
    updateUnitMovement(units.all(), step);
    production.update(step);
    huntStrikes = Math.max(huntStrikes, hunter.huntStrikeCount);
    // Stand in for the road/depot chain so the camp's buffer cannot cap the run:
    // one deer carries more meat than the camp can hold at once, by design.
    banked += production.withdrawBuffered(built.structure.id)?.amount ?? 0;
    const status = production.snapshots("player")[0]?.status;
    if (status === "source-depleted" && quarry.remainingMeat > 0) depletedWhileMeatRemained = true;
  }

  assert.equal(huntStrikes, 1, "one contact drops the quarry and emits exactly one attack event");
  assert.equal(quarry.dead, true, "the quarry was brought down");
  assert.equal(quarry.remainingMeat, 0, "the carcass was picked clean");
  // Derived from the table, not pinned: retune `meatCapacity` and this still holds.
  assert.ok(
    Math.abs(banked - deer.meatCapacity) < 0.0001,
    `a carcass banks exactly its meatCapacity (expected ${deer.meatCapacity}, banked ${banked})`,
  );
  assert.equal(economy.resourceId, "food", "the meat arrives as food");
  // §9's flicker: a chase repeatedly carries the quarry outside the camp's reach,
  // and a camp that called itself exhausted every time would read as broken while
  // the hunt was going perfectly.
  assert.equal(depletedWhileMeatRemained, false, "the camp never called itself exhausted while meat remained");
  assert.equal(production.snapshots("player")[0]?.status, "source-depleted", "an emptied herd stops the camp");
  assert.equal(production.isAssigned(hunter), false, "the hunter is released once the herd is gone");
  territory.dispose();
});

check("Faz 4: a hunting camp is refused away from live game and legal beside a herd", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const camp = buildings.hunting_camp ?? assert.fail("hunting camp balance missing");
  const reach = camp.economy?.gatherRadius ?? assert.fail("a hunting camp needs a reach");
  const wildlife = new WildlifeSystem(shippedAnimalBalance(), [
    { id: "herd", species: "deer", x: 0, z: 0, count: 4 },
  ]);
  const units = new UnitSystem();
  const structures = new PlacedStructureSystem();
  const navigation = new RtsNavigation();
  const kingdoms = new KingdomRegistry(["player"], units, structures, { food: 0, wood: 500 }, 20);
  // A control zone large enough that territory never vetoes these proposals —
  // the rule under test is the herd, not the border.
  const territory = new TerritoryControlSystem(() => [{ owner: "player", x: 0, z: 0, radius: 1000 }]);
  territory.refresh();
  const construction = new StructureConstructionService(
    buildings,
    structures,
    kingdoms,
    navigation,
    () => structures.navigationBlockers(),
    territory,
    () => {},
    () => {},
    (stats, x, z) => stats.economy?.requiresGame
      && wildlife.liveAnimalsNear(x, z, stats.economy.gatherRadius ?? 0).length === 0
      ? "missing-game"
      : null,
  );
  assert.equal(
    construction.validate("player", "hunting_camp", 0, 0)?.valid,
    true,
    "a camp is legal at the herd it will hunt",
  );
  // Far enough that no animal can graze into reach: the herd's own roam radius
  // plus the camp's, and then some.
  const away = Math.ceil(reach * 3);
  assert.ok(away < RTS_WORLD_HALF_EXTENT, "the far test point stays on the map");
  assert.equal(
    construction.validate("player", "hunting_camp", away, 0)?.reason,
    "missing-game",
    "away from every herd the ghost is refused, and says why",
  );
  territory.dispose();
});

// --- Pasture and taming V2 Faz 3: the building and its placement rule ---

check("V2 Faz 3: the pasture is authored as the third production shape, and its reach covers what it can tame", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const pasture = buildings.pasture ?? assert.fail("pasture balance missing");
  const economy = pasture.economy ?? assert.fail("a pasture needs an economy block");
  assert.equal(economy.requiresLivestock, true, "the pasture produces from its pen, not from a source it works");
  assert.equal(economy.resourceId, "food", "penned livestock banks food, like the farm it competes with");
  // §3.5's whole point: output is measured in animals, so the per-worker rate is
  // the one field this shape may omit — and the pen size is what bounds it.
  assert.equal(economy.perWorkerPerMinute, undefined, "a pasture declares no per-worker rate");
  assert.ok((economy.perAnimalPerMinute ?? 0) > 0, "the pasture rate is per animal");
  assert.ok(
    Number.isInteger(economy.livestockCapacity) && (economy.livestockCapacity ?? 0) > 0,
    "the pen has a whole-animal ceiling, which is what keeps livestock income finite",
  );
  // A pasture is not a camp that walks out to a finite source. Sharing those
  // flags would put it in the gather cycle, which §3.4 measured as the way a
  // tamed cow gets banked as meat.
  assert.ok(
    !economy.requiresGame && !economy.requiresForest && !economy.requiresResourceNode,
    "a pasture is not also a gathering camp",
  );

  // Every tier of the six carries the two livestock numbers, and neither ever
  // regresses — the tier is what the match actually reads.
  const tiers = [...pasture.progression?.settlement ?? [], ...pasture.progression?.town ?? []];
  assert.equal(tiers.length, 6, "the pasture declares all six playable tiers");
  let previousPen = 0;
  let previousRate = 0;
  for (const tier of tiers) {
    const pen = tier.economy?.livestockCapacity ?? 0;
    const rate = tier.economy?.perAnimalPerMinute ?? 0;
    assert.ok(Number.isInteger(pen) && pen > 0, `pasture tier ${tier.level} declares a whole-animal pen`);
    assert.ok(rate > 0, `pasture tier ${tier.level} declares a per-animal rate`);
    assert.ok(pen >= previousPen && rate >= previousRate, `pasture tier ${tier.level} does not regress`);
    previousPen = pen;
    previousRate = rate;
  }

  // Range contract, the hunting camp's rule applied to the species that can
  // actually fill this building: a grazing cow must not wander permanently out of
  // the pasture built for its herd. Computed from both tables, never pinned.
  const reach = economy.gatherRadius ?? assert.fail("a pasture needs a reach");
  const tameable = Object.entries(shippedAnimalBalance()).filter(([, stats]) => stats.tameable);
  assert.ok(tameable.length > 0, "there is at least one tameable species, or this contract is vacuous");
  for (const [id, stats] of tameable) {
    assert.ok(
      stats.roamRadius < reach,
      `${id} roams ${stats.roamRadius}, past the pasture's reach of ${reach}`,
    );
  }
});

check("V2 Faz 3: the pasture's data shape is enforced, and the per-worker rate stays mandatory elsewhere", () => {
  const raw = JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as Record<string, any>;
  const mutated = (edit: (data: Record<string, any>) => void): Record<string, any> => {
    const copy = JSON.parse(JSON.stringify(raw)) as Record<string, any>;
    edit(copy);
    return copy;
  };
  const refuses = (edit: (data: Record<string, any>) => void, pattern: RegExp, why: string): void => {
    assert.throws(
      () => validateBuildingBalance(mutated(edit)),
      (error: unknown) => error instanceof GameDataError && pattern.test(error.message),
      why,
    );
  };

  // §9's risk, held shut: the exemption is scoped to the livestock flag, so
  // dropping the rate from an ordinary producer is still a load failure.
  refuses(
    (data) => { delete data.farm.economy.perWorkerPerMinute; },
    /perWorkerPerMinute/,
    "a farm without a per-worker rate is refused, naming the field",
  );
  refuses(
    (data) => { delete data.farm.progression.settlement[0].economy.perWorkerPerMinute; },
    /perWorkerPerMinute/,
    "and so is a farm tier without one",
  );
  refuses(
    (data) => { data.farm.economy.localBufferCapacity = 61; },
    /localBufferCapacity: must equal workerCapacity/,
    "a worker producer's base camp buffer is derived from its staffing and rate",
  );
  refuses(
    (data) => { data.farm.progression.settlement[1].economy.localBufferCapacity = 121; },
    /localBufferCapacity: must equal workerCapacity/,
    "and a tier's camp buffer follows the same derived rule",
  );

  // The animals-table rule in the other direction: a livestock field on a
  // building that has no pen is refused rather than silently dropped.
  for (const field of ["livestockCapacity", "perAnimalPerMinute"] as const) {
    refuses(
      (data) => { data.farm.economy[field] = 4; },
      new RegExp(`${field}: only a requiresLivestock building may carry it`),
      `${field} on a farm is refused rather than ignored`,
    );
    refuses(
      (data) => { data.farm.progression.town[0].economy[field] = 4; },
      new RegExp(`${field}: only a requiresLivestock building may carry it`),
      `${field} on a farm tier is refused rather than ignored`,
    );
  }

  refuses(
    (data) => { data.pasture.economy.livestockCapacity = 0; },
    /livestockCapacity: must be a positive integer/,
    "a pen that holds nothing is refused, naming the field",
  );
  refuses(
    (data) => { data.pasture.economy.livestockCapacity = 4.5; },
    /livestockCapacity: must be a positive integer/,
    "half an animal is refused too",
  );
  refuses(
    (data) => { data.pasture.economy.perAnimalPerMinute = 0; },
    /perAnimalPerMinute must be > 0/,
    "a pasture that produces nothing per animal is refused",
  );
  refuses(
    (data) => { delete data.pasture.economy.gatherRadius; },
    /gatherRadius/,
    "a pasture with no reach is refused: a shepherd would have nowhere to look",
  );
  // A pasture that also claimed a finite source would run both production shapes
  // at once, which §3.4 measured as the path that banks a tamed cow as meat.
  refuses(
    (data) => { data.pasture.economy.requiresGame = true; data.pasture.economy.carryCapacity = 10; },
    /may not also gather a finite source/,
    "a pasture may not double as a gathering camp",
  );

  const shippedPen = validateBuildingBalance(raw).pasture?.progression?.settlement[0]?.economy?.livestockCapacity
    ?? assert.fail("pasture Settlement Lv1 pen missing");
  refuses(
    (data) => { data.pasture.progression.settlement[1].economy.livestockCapacity = shippedPen - 1; },
    /livestockCapacity/,
    "a tier that shrinks the pen is refused",
  );
  refuses(
    (data) => { delete data.pasture.progression.town[0].economy.perAnimalPerMinute; },
    /perAnimalPerMinute/,
    "a pasture tier without its rate is refused",
  );
});

check("V2 Faz 3: a pasture is refused away from tameable animals, and deer are not tameable animals", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const reach = buildings.pasture?.economy?.gatherRadius ?? assert.fail("a pasture needs a reach");
  // Two herds, far enough apart that neither can graze into the other's circle:
  // cattle at the origin, deer off to one side. The deer herd is the sharp half
  // of this test — live game in reach must not justify a pasture that could never
  // fill, which `liveAnimalsNear` alone would have allowed.
  const deerAt = Math.ceil(reach * 3);
  const wildlife = new WildlifeSystem(shippedAnimalBalance(), [
    { id: "cattle", species: "cow", x: 0, z: 0, count: 4 },
    { id: "deer", species: "deer", x: deerAt, z: 0, count: 4 },
  ]);
  const units = new UnitSystem();
  const structures = new PlacedStructureSystem();
  const navigation = new RtsNavigation();
  const kingdoms = new KingdomRegistry(["player"], units, structures, { food: 0, wood: 500 }, 20);
  const territory = new TerritoryControlSystem(() => [{ owner: "player", x: 0, z: 0, radius: 1000 }]);
  territory.refresh();
  const construction = new StructureConstructionService(
    buildings,
    structures,
    kingdoms,
    navigation,
    () => structures.navigationBlockers(),
    territory,
    () => {},
    () => {},
    (stats, x, z) => stats.economy?.requiresLivestock
      && wildlife.tameableAnimalsNear(x, z, stats.economy.gatherRadius ?? 0).length === 0
      ? "missing-livestock"
      : null,
  );

  assert.equal(
    construction.validate("player", "pasture", 0, 0)?.valid,
    true,
    "a pasture is legal at the cattle it will tame",
  );
  // Perpendicular to the two herds rather than further along their line, so the
  // empty point stays comfortably on the map while clearing both circles.
  const away = deerAt;
  assert.ok(away < RTS_WORLD_HALF_EXTENT, "the far test point stays on the map");
  assert.equal(
    construction.validate("player", "pasture", 0, away)?.reason,
    "missing-livestock",
    "away from every herd the ghost is refused, and says why",
  );
  assert.equal(
    construction.validate("player", "pasture", deerAt, 0)?.reason,
    "missing-livestock",
    "a ring of deer is game, not livestock: the pasture is still refused",
  );
  territory.dispose();
});

check("V2 Faz 3: a completed pasture stands with an empty pen, hires no one, and is not counted as a food supply", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const pasture = buildings.pasture ?? assert.fail("pasture balance missing");
  const wildlife = new WildlifeSystem(shippedAnimalBalance(), [
    { id: "cattle", species: "cow", x: 0, z: 0, count: 4 },
  ]);
  const units = new UnitSystem();
  const structures = new PlacedStructureSystem();
  const navigation = new RtsNavigation();
  const kingdoms = new KingdomRegistry(["player"], units, structures, { food: 0, wood: 500 }, 20);
  const territory = new TerritoryControlSystem(() => [{ owner: "player", x: 0, z: 0, radius: 1000 }]);
  territory.refresh();
  const construction = new StructureConstructionService(
    buildings,
    structures,
    kingdoms,
    navigation,
    () => structures.navigationBlockers(),
    territory,
    () => {},
    () => {},
    (stats, x, z) => stats.economy?.requiresLivestock
      && wildlife.tameableAnimalsNear(x, z, stats.economy.gatherRadius ?? 0).length === 0
      ? "missing-livestock"
      : null,
  );
  const built = construction.build("player", "pasture", 0, 0);
  if (!built.built) return assert.fail(`pasture construction failed: ${built.reason}`);
  structures.advanceConstruction(built.structure, pasture.constructionSeconds);

  // Idle workers standing right at the door: an ordinary producer would have
  // hired them on the first tick.
  const shepherds = [units.spawn("player", 6, 0, RTS_TEST_WORKER_STATS), units.spawn("player", -6, 0, RTS_TEST_WORKER_STATS)];
  const production = new EconomyProductionSystem(
    units, structures, navigation, () => false, undefined, undefined, wildlife,
  );
  for (let tick = 0; tick < 40; tick += 1) {
    updateUnitMovement(units.all(), 0.25);
    production.update(0.25);
  }

  const snapshot = production.snapshots("player")[0] ?? assert.fail("the completed pasture is not a producer");
  assert.equal(snapshot.status, "missing-livestock", "an empty pen says so rather than reading as broken");
  assert.equal(snapshot.assignedWorkers, 0, "the pasture's crew is hired by the pasture system, not by the economy loop");
  for (const shepherd of shepherds) {
    assert.equal(production.isAssigned(shepherd), false, "an idle worker beside a pasture stays idle");
  }
  // Manual assignment is the same rule: a player order must not fill the crew
  // with workers who would then stand at the door producing nothing.
  assert.equal(
    production.assignWorkers(built.structure, shepherds).assignedWorkers,
    0,
    "even an explicit order cannot staff a pasture through the economy loop",
  );
  assert.equal(snapshot.localBuffer, 0, "and nothing is produced from an empty pen");
  // The AI reads this: a pasture nobody has driven an animal into is a building,
  // not a food supply, exactly like a hunted-out camp.
  assert.equal(producerHasSource(snapshot.status), false, "an empty pen does not count as a live food source");
  territory.dispose();
});

// --- Pasture and taming V2 Faz 4: ownership and the drive ---

/**
 * A pasture standing on a cattle herd, with the systems a drive needs and
 * nothing else. Returns everything the assertions read.
 *
 * The pasture is deliberately placed a walk away from the herd's centre: with
 * the two on top of each other an animal could start inside the pen and be
 * penned the instant it was calmed, and the drive — the half of §2 this phase
 * exists for — would never run.
 */
function pastureDriveFixture(options: {
  readonly species?: string;
  readonly herdCount?: number;
  /**
   * Where the herd grazes. Moved only by the single-animal fixtures: one animal
   * scattered anywhere in a `roamRadius` circle can start outside the pasture's
   * reach, and the building would then be refused before the test began.
   */
  readonly herdX?: number;
  /**
   * Extra herds on the same field — V3 Faz 3's den, which needs a *drive* to
   * interrupt rather than a lone worker standing about.
   */
  readonly extraHerds?: readonly RtsHerdDefinition[];
  /**
   * The kingdom's control circle. The blanket default keeps every earlier
   * pasture test on friendly ground; V3 Faz 3 shrinks it to the pasture itself,
   * because a wolf that can only take a worker on unowned ground needs there to
   * be some (KARAR 1).
   */
  readonly control?: { readonly x: number; readonly z: number; readonly radius: number };
} = {}) {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const pastureStats = buildings.pasture ?? assert.fail("pasture balance missing");
  const animals = shippedAnimalBalance();
  const wildlife = new WildlifeSystem(animals, [
    { id: "cattle", species: options.species ?? "cow", x: options.herdX ?? 0, z: 0, count: options.herdCount ?? 4 },
    ...(options.extraHerds ?? []),
  ]);
  const units = new UnitSystem();
  const structures = new PlacedStructureSystem();
  const navigation = new RtsNavigation();
  const kingdoms = new KingdomRegistry(["player"], units, structures, { food: 0, wood: 500 }, 20);
  const control = options.control ?? { x: 0, z: 0, radius: 1000 };
  const territory = new TerritoryControlSystem(() => [{ owner: "player", ...control }]);
  territory.refresh();
  const construction = new StructureConstructionService(
    buildings,
    structures,
    kingdoms,
    navigation,
    () => structures.navigationBlockers(),
    territory,
    () => {},
    () => {},
    (stats, x, z) => stats.economy?.requiresLivestock
      && wildlife.tameableAnimalsNear(x, z, stats.economy.gatherRadius ?? 0).length === 0
      ? "missing-livestock"
      : null,
  );
  const built = construction.build("player", "pasture", 12, 0);
  if (!built.built) return assert.fail(`pasture construction failed: ${built.reason}`);
  structures.advanceConstruction(built.structure, pastureStats.constructionSeconds);
  const pasture = new PastureSystem(units, structures, navigation, wildlife);
  return { buildings, pastureStats, animals, wildlife, units, structures, navigation, territory, construction, structure: built.structure, pasture };
}

check("V2 Faz 4: a shepherd walks out, calms an animal, drives it home, and the pasture keeps it", () => {
  const fixture = pastureDriveFixture();
  const { wildlife, units, pasture, structure } = fixture;
  const cow = fixture.animals.cow ?? assert.fail("cow balance missing");
  const capacity = structure.economy?.livestockCapacity ?? assert.fail("pasture pen capacity missing");
  // Two workers, the Settlement Lv1 shepherd budget. Anything the pasture does
  // not hire stays idle, which is one of the things under test.
  const workers = [
    units.spawn("player", 10, 4, RTS_TEST_WORKER_STATS),
    units.spawn("player", 10, -4, RTS_TEST_WORKER_STATS),
    units.spawn("player", 14, 6, RTS_TEST_WORKER_STATS),
  ];

  const seen = new Set<string>();
  let calmedWhileWorking = false;
  let calmedWithLivestockActivity = false;
  const step = 0.25;
  for (let tick = 0; tick < 2400; tick += 1) {
    pasture.update(step);
    wildlife.update(step, units.all().map((unit) => unit.position));
    updateUnitMovement(units.all(), step);
    for (const worker of workers) {
      const state = pasture.stateFor(worker);
      if (state !== "idle") seen.add(state);
      // §2.4: the shepherd is *at work* while calming, not walking. That is what
      // puts him on the work montage instead of sliding in an idle pose.
      if (state === "calming" && worker.isWorking) calmedWhileWorking = true;
      if (state === "calming" && worker.workerActivity === "livestock") calmedWithLivestockActivity = true;
    }
  }

  assert.deepEqual(
    [...seen].sort(),
    ["calming", "driving", "moving-to-animal"],
    "all three of §2's steps actually ran",
  );
  assert.equal(calmedWhileWorking, true, "calming is standing work, and the shepherd's pose says so");
  assert.equal(calmedWithLivestockActivity, true, "the pasture owns and reports livestock activity while calming");

  const penned = wildlife.all().filter((animal) => animal.owner === "player");
  assert.equal(penned.length, capacity, "the drive filled the pen to its authored capacity, and stopped there");
  assert.ok(
    penned.length < wildlife.all().length || wildlife.all().length === capacity,
    "capacity is what stopped it, not running out of cattle",
  );
  // V2 Faz 8: penned is a *place in a line*, not a flag and no longer a yard to
  // wander. Every assertion below is computed from the same `penStalls` the
  // runtime posts them at, so a re-authored footprint, spacing or capacity keeps
  // this true — what is pinned is that the pen is a row and that each animal is
  // standing in its own place in it.
  const stalls = penStalls(structure);
  assert.equal(stalls.length, capacity, "the pasture offers exactly one stall per animal it may hold");
  const occupied = new Set<number>();
  for (const animal of penned) {
    const slot = stalls.findIndex((stall) =>
      Math.hypot(animal.position.x - stall.x, animal.position.z - stall.z) < 1e-6);
    assert.ok(slot >= 0, `a penned animal stands on a stall, not somewhere in a yard (${animal.position.x.toFixed(2)}, ${animal.position.z.toFixed(2)})`);
    assert.equal(occupied.has(slot), false, "and no two animals were driven into the same stall");
    occupied.add(slot);
    // Compared as an angle rather than as a number: facing is normalised on its
    // way through the shared turn helper, so "the same heading" and "the same
    // radian" are not the same test.
    const offBy = animal.facing - (stalls[slot]?.facing ?? 0);
    assert.ok(
      Math.abs(Math.atan2(Math.sin(offBy), Math.cos(offBy))) < 1e-3,
      "it faces into the pen, like the rest of the row",
    );
    // The whole of Faz 8's claim: what stands there is an animated body, not an
    // animal that thinks. No speed, no lead, no roaming — and the activity that
    // puts it on the asset's `Eating` clip.
    assert.equal(animal.speed, 0, "a stalled animal is not moving");
    assert.equal(animal.activity, "grazing", "and is on its eating clip, not an idle pose");
    assert.notEqual(animal.stall, null, "penning is what replaced its behaviour, not something layered over it");
    assert.equal(animal.lead, null, "a penned animal is no longer being led by anyone");
    assert.equal(animal.stats.id, cow.id, "the tameable species is what was taken");
    const halfWidth = structure.stats.footprint.width / 2;
    const halfDepth = structure.stats.footprint.depth / 2;
    assert.ok(
      Math.abs(animal.position.x - structure.x) < halfWidth
        && Math.abs(animal.position.z - structure.z) < halfDepth,
      "a penned animal occupies the pasture footprint rather than standing beside it",
    );
  }
  // The crew is released once the pen is full: shepherds are workers, and §55's
  // rule that nothing may hold a worker forever applies to herding too.
  for (const worker of workers) {
    assert.equal(pasture.isShepherd(worker), false, "no worker is left holding a job the pen has no room for");
    assert.equal(worker.workerActivity, null, "a released shepherd keeps no stale livestock activity");
  }
  fixture.territory.dispose();
});

check("V2 Faz 4: a tamed animal leaves the wild economy — no camp may count it, hunt it, or be built on it", () => {
  const fixture = pastureDriveFixture();
  const { wildlife, units, pasture, structure, buildings } = fixture;
  const camp = buildings.hunting_camp ?? assert.fail("hunting camp balance missing");
  const reach = { resourceId: "food", x: 0, z: 0, radius: camp.economy?.gatherRadius ?? 0 } as const;
  const wildMeat = wildlife.remainingNear(reach);
  assert.ok(wildMeat > 0, "the herd is worth something to a hunting camp before anyone tames it");

  units.spawn("player", 10, 4, RTS_TEST_WORKER_STATS);
  units.spawn("player", 10, -4, RTS_TEST_WORKER_STATS);
  const step = 0.25;
  for (let tick = 0; tick < 2400; tick += 1) {
    pasture.update(step);
    wildlife.update(step, units.all().map((unit) => unit.position));
    updateUnitMovement(units.all(), step);
  }
  const penned = wildlife.all().filter((animal) => animal.owner === "player");
  assert.ok(penned.length > 0, "something was actually tamed, or this proves nothing");

  // §3.7, the bug this closes: without an owner filter the camp counts the
  // kingdom's own cattle as meat and sends hunters to shoot them.
  const remaining = wildlife.remainingNear(reach);
  const takenMeat = penned.reduce((total, animal) => total + animal.remainingMeat, 0);
  assert.ok(
    Math.abs(remaining - (wildMeat - takenMeat)) < 1e-6,
    "every tamed animal comes off the camp's count, exactly its own worth",
  );
  assert.equal(
    wildlife.reserveNearest(999, reach)?.id === penned[0]?.id,
    false,
    "and no hunter can claim one",
  );
  assert.equal(
    wildlife.huntableAnimalsNear(structure.x, structure.z, 8).some((animal) => animal.owner !== "wild"),
    false,
    "the huntable query answers with wild animals only",
  );

  // Population is the V1 invariant this must not break: taming gives a kingdom
  // an animal, never a supply slot.
  const population = new PopulationSystem("player", fixture.units, fixture.structures, 10);
  const before = population.snapshot().current;
  assert.equal(
    population.snapshot().current,
    before,
    "livestock still costs no population, owned or wild",
  );
  fixture.territory.dispose();
});

check("V2 Faz 4: losing the shepherd frees the animal instead of freezing it", () => {
  const fixture = pastureDriveFixture();
  const { wildlife, units, pasture } = fixture;
  const shepherd = units.spawn("player", 10, 4, RTS_TEST_WORKER_STATS);
  const step = 0.25;
  // Run until the drive is genuinely under way, then kill the shepherd on it.
  let droveFor = 0;
  for (let tick = 0; tick < 2400 && droveFor < 4; tick += 1) {
    pasture.update(step);
    wildlife.update(step, units.all().map((unit) => unit.position));
    updateUnitMovement(units.all(), step);
    if (pasture.stateFor(shepherd) === "driving") droveFor += 1;
  }
  assert.ok(droveFor >= 4, "a drive was under way to interrupt");
  const driven = wildlife.reservationOf(shepherd.id) ?? assert.fail("the shepherd held no animal");
  assert.notEqual(driven.lead, null, "the animal was being led");

  shepherd.health.damage(shepherd.health.max);
  pasture.update(step);
  assert.equal(pasture.isShepherd(shepherd), false, "a dead shepherd holds no job");
  assert.equal(driven.lead, null, "and lets go of the animal rather than leaving it mid-lead");
  assert.equal(driven.owner, "wild", "an animal that never reached the pen is still wild");
  assert.equal(driven.reservedByWorkerId, null, "its claim is free for the next shepherd — or a hunter");
  fixture.territory.dispose();
});

// --- Pasture and taming V2 Faz 5: production and breeding ---

/**
 * Run a fixture until its pen has taken everything it is going to take, then
 * hand back the pasture and its economy loop. The drive itself is Faz 4's test;
 * this is the setup every Faz 5 assertion starts from.
 */
function filledPastureFixture(options: { readonly herdCount?: number; readonly workers?: number } = {}) {
  const fixture = pastureDriveFixture({ herdCount: options.herdCount ?? 4 });
  for (let index = 0; index < (options.workers ?? 2); index += 1) {
    fixture.units.spawn("player", 10, index % 2 === 0 ? 4 : -4, RTS_TEST_WORKER_STATS);
  }
  const production = new EconomyProductionSystem(
    fixture.units,
    fixture.structures,
    fixture.navigation,
    () => false,
    undefined,
    undefined,
    fixture.wildlife,
    (structure) => fixture.pasture.pennedYield(structure),
  );
  const step = 0.25;
  const tick = (): void => {
    fixture.pasture.update(step);
    fixture.wildlife.update(step, fixture.units.all().map((unit) => unit.position));
    updateUnitMovement(fixture.units.all(), step);
    production.update(step);
  };
  for (let index = 0; index < 2400; index += 1) tick();
  return { ...fixture, production, step, tick };
}

check("V2 Faz 5: a pasture pays its pen's worth per minute, with nobody working there", () => {
  const fixture = filledPastureFixture();
  const { wildlife, structure, pasture, production, units } = fixture;
  const economy = structure.economy ?? assert.fail("pasture economy missing");
  const rate = economy.perAnimalPerMinute ?? assert.fail("pasture rate missing");

  const penned = pasture.pennedAnimals(structure);
  assert.ok(penned.length > 0, "the pen filled, or this proves nothing");
  // Derived from both tables exactly as the runtime does it, so retuning either
  // the building's rate or the species' multiplier keeps this true.
  const pennedYield = penned.reduce((total, animal) => total + (animal.stats.pastureYield ?? 0), 0);
  assert.ok(pennedYield > 0, "penned animals are worth something");

  // Unattended for ten minutes with no road out, the pasture has filled its own
  // buffer and stopped — the same back-pressure a farm has, and the reason the
  // road/depot chain is what turns a pen into income.
  assert.equal(
    production.snapshots("player")[0]?.status,
    "buffer-full",
    "a pasture nobody collects from fills up and waits",
  );
  production.withdrawBuffered(structure.id);
  fixture.tick();

  // Nobody is employed here: the shepherds went home when the pen filled, and
  // the economy loop refuses to staff a pasture at all. That is the plan's whole
  // gain — food without spending population on it.
  const snapshot = production.snapshots("player")[0] ?? assert.fail("the pasture is not a producer");
  assert.equal(snapshot.status, "producing", "collected from, a full pen produces again");
  assert.equal(snapshot.assignedWorkers, 0, "and does it with no workers assigned");
  for (const worker of units.all()) {
    assert.equal(pasture.isShepherd(worker), false, "every shepherd was released once the pen was full");
  }
  assert.ok(
    Math.abs(snapshot.productionPerMinute - pennedYield * rate) < 1e-6,
    `the rate line is pen yield x per-animal rate (expected ${pennedYield * rate}, read ${snapshot.productionPerMinute})`,
  );

  // And the buffer really fills at that rate. Drained every tick so the local
  // buffer's own ceiling cannot cap the measurement — which is exactly what the
  // road/depot chain does in a match, through the same `withdrawBuffered`.
  let banked = 0;
  const seconds = 120;
  for (let index = 0; index < seconds / fixture.step; index += 1) {
    fixture.tick();
    banked += production.withdrawBuffered(structure.id)?.amount ?? 0;
  }
  banked += production.withdrawBuffered(structure.id)?.amount ?? 0;
  const expected = pennedYield * rate * (seconds / 60);
  assert.ok(
    Math.abs(banked - expected) < expected * 0.02,
    `two minutes bank two minutes of output (expected ~${expected.toFixed(1)}, banked ${banked.toFixed(1)})`,
  );
  assert.equal(economy.resourceId, "food", "and it arrives as food, through the ordinary buffer");
  assert.equal(wildlife.all().every((animal) => !animal.dead), true, "nothing was slaughtered to produce it");
  fixture.territory.dispose();
});

check("V2 Faz 5: a pen breeds up to its capacity and stops, and an empty one never starts", () => {
  // Two cattle into a pen with room for more, so breeding has somewhere to go.
  const fixture = filledPastureFixture({ herdCount: 2 });
  const { structure, pasture, wildlife } = fixture;
  const capacity = structure.economy?.livestockCapacity ?? assert.fail("pen capacity missing");
  const cow = shippedAnimalBalance().cow ?? assert.fail("cow balance missing");
  const drivenIn = 2;
  assert.ok(capacity > drivenIn, "the fixture leaves room to breed into, or the test is vacuous");

  // Long enough for more births than the pen could ever hold, which is the point:
  // what stops it has to be the capacity, not the clock.
  for (let index = 0; index < (cow.breedSeconds ?? 0) * (capacity + 4) / fixture.step; index += 1) {
    fixture.tick();
  }
  const penned = pasture.pennedAnimals(structure);
  assert.equal(penned.length, capacity, "the pen breeds up to its authored ceiling");
  // Only two animals ever existed to drive in, so the rest were born here — the
  // herd on the map is bigger than the one the Level authored.
  assert.equal(
    wildlife.all().length,
    capacity,
    `${capacity - drivenIn} animals were born rather than driven`,
  );
  assert.equal(
    wildlife.all().filter((animal) => animal.owner === "player").length,
    capacity,
    "and no animal is owned that the pen is not holding",
  );
  assert.equal(new Set(penned.map((animal) => animal.id)).size, capacity, "every animal in the pen is a distinct one");
  fixture.territory.dispose();

  // The other half: nobody to drive anything in, so nothing to breed from. A
  // pasture that stocked itself would make the whole drive optional.
  const empty = pastureDriveFixture();
  for (let index = 0; index < 4000; index += 1) {
    empty.pasture.update(0.25);
    empty.wildlife.update(0.25, []);
  }
  assert.equal(empty.pasture.pennedAnimals(empty.structure).length, 0, "an empty pen breeds nothing");
  empty.territory.dispose();
});

check("V2 Faz 5: razing a pasture frees its herd instead of deleting it", () => {
  const fixture = filledPastureFixture();
  const { structure, pasture, wildlife, structures } = fixture;
  const penned = pasture.pennedAnimals(structure);
  assert.ok(penned.length > 0, "there is a herd to free");
  const ids = penned.map((animal) => animal.id);
  // Where each body was standing in the line, taken *before* the barn comes
  // down: V2 Faz 8's rule is that the animation's post is the spawn point, so
  // this is the only witness that can tell a freed animal from a re-spawned one.
  const stood = new Map(penned.map((animal) => [animal.id, animal.position.clone()]));
  const stalls = penStalls(structure);
  for (const animal of penned) {
    assert.ok(
      stalls.some((stall) => Math.hypot(animal.position.x - stall.x, animal.position.z - stall.z) < 1e-6),
      "the pen really is a row of stalls before it burns",
    );
  }

  structures.destroy(structure);
  fixture.tick();

  assert.equal(pasture.pennedAnimals(structure).length, 0, "the pasture is gone and so is its pen");
  for (const id of ids) {
    const animal = wildlife.animalById(id) ?? assert.fail(`animal ${id} vanished with the building`);
    assert.equal(animal.owner, "wild", "its livestock is wild again");
    assert.equal(animal.lead, null, "and nobody is leading it");
    // The AI comes back on where the animated body was, not at the barn's pivot
    // and not back at the herd it was driven from. One tick of grazing has run,
    // so it is measured as "it started from the stall" rather than "it is still
    // standing on it".
    assert.equal(animal.stall, null, "it is a thinking animal again, not a body at a post");
    const from = stood.get(id) ?? assert.fail(`no recorded stall for ${id}`);
    assert.ok(
      Math.hypot(animal.roamProfile.homeX - from.x, animal.roamProfile.homeZ - from.z) < 1e-6,
      "the herd it now grazes is centred on the stall it was freed from",
    );
    // Wild again means huntable again: the opponent who razed the barn now has
    // to run the cattle down like any other herd.
    assert.ok(
      wildlife.huntableAnimalsNear(animal.position.x, animal.position.z, 4).some((near) => near.id === id),
      "a freed animal is game once more",
    );
    // It grazes where it was left, not back at the herd it was taken from.
    assert.ok(
      Math.hypot(animal.roamProfile.homeX - animal.position.x, animal.roamProfile.homeZ - animal.position.z)
        <= animal.stats.roamRadius,
      "and settles on the ground it is standing on",
    );
  }
  fixture.territory.dispose();
});

// --- Pasture V2 Faz 8: the pen is a feeding line, and the line is not AI ---

check("V2 Faz 8: a pasture's stalls fill its front footprint strip in an evenly spaced row", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const pastureStats = buildings.pasture ?? assert.fail("pasture balance missing");
  const structures = new PlacedStructureSystem();
  const structure = structures.place("player", pastureStats, 10, -4);
  const capacity = structure.economy?.livestockCapacity ?? assert.fail("pen capacity missing");
  const stalls = penStalls(structure);

  assert.equal(stalls.length, capacity, "one place per animal the tier's pen may hold");
  const halfWidth = structure.stats.footprint.width / 2;
  const halfDepth = structure.stats.footprint.depth / 2;
  const rows = new Map<string, number>();
  const spacings = new Set<string>();
  for (const [index, stall] of stalls.entries()) {
    // The pen uses the vacant front strip *within* the ground the pasture owns.
    // Its mesh is shifted back into the same footprint, so no animal reads as a
    // disconnected herd parked beside a building.
    assert.ok(Math.abs(stall.x - structure.x) < halfWidth, `stall ${index} stays inside the footprint width`);
    assert.ok(Math.abs(stall.z - structure.z) < halfDepth, `stall ${index} stays inside the footprint depth`);
    assert.ok(stall.x > structure.x, `stall ${index} uses the pasture's front half`);
    const row = stall.x.toFixed(6);
    rows.set(row, (rows.get(row) ?? 0) + 1);
    assert.equal(stall.facing, stalls[0]?.facing, "the whole row looks the same way, into the pen");
    if (index > 0) {
      const previous = stalls[index - 1]!;
      spacings.add(Math.hypot(stall.x - previous.x, stall.z - previous.z).toFixed(6));
    }
  }
  // A queue, which is the picture the phase exists for: consecutive places are
  // one fixed gap apart. Two distinct gaps are allowed rather than one, because a
  // tier whose pen outgrows the face wraps to a second row and the step between
  // rows is the second value — so raising `livestockCapacity` stays a tuning
  // decision rather than a red build.
  assert.ok(spacings.size <= 2, `the row is evenly spaced (gaps: ${[...spacings].join(", ")})`);
  assert.deepEqual(
    [...rows.values()].sort((left, right) => left - right),
    [2, 2],
    "a four-animal Settlement pen is arranged as two side-by-side pairs",
  );
  assert.equal(
    new Set(stalls.map((stall) => `${stall.x.toFixed(4)}:${stall.z.toFixed(4)}`)).size,
    capacity,
    "and no two animals are sent to the same spot",
  );
  // Nothing stands inside anything else, which is the assertion a spacing test is
  // really for — a cow is about a unit across at this scale.
  for (const [index, stall] of stalls.entries()) {
    for (const other of stalls.slice(index + 1)) {
      assert.ok(
        Math.hypot(stall.x - other.x, stall.z - other.z) >= 1.5,
        "no two stalls overlap",
      );
    }
  }
});

check("V2 Faz 8: a penned animal stops being simulated — it stands, eats, and ignores the field", () => {
  const fixture = filledPastureFixture();
  const { structure, pasture, wildlife, units } = fixture;
  const penned = pasture.pennedAnimals(structure);
  assert.ok(penned.length > 0, "the pen filled, or this proves nothing");
  const parked = penned.map((animal) => ({ animal, at: animal.position.clone() }));

  // Everything that moves a wild animal, all at once: a crowd standing on top of
  // the pen (fright), a predator warning fired straight at it (V3's threat), and
  // a lead as if a shepherd had grabbed it. None of them is a state a penned
  // animal can enter, and this is the test that says so rather than a comment.
  for (const { animal } of parked) {
    animal.fleeFromPredator({ x: animal.position.x, z: animal.position.z });
    animal.lead = { x: animal.position.x + 20, z: animal.position.z, follow: true };
  }
  for (let index = 0; index < 6; index += 1) units.spawn("player", structure.x, structure.z, RTS_TEST_WORKER_STATS);
  const crowd = units.all().map((unit) => unit.position);
  for (let index = 0; index < 600; index += 1) {
    wildlife.update(0.25, crowd);
    pasture.update(0.25);
  }

  for (const { animal, at } of parked) {
    assert.equal(
      Math.hypot(animal.position.x - at.x, animal.position.z - at.z),
      0,
      "150 seconds of crowds, predators and a lead moved it not one unit",
    );
    assert.equal(animal.speed, 0, "so its clip is a standing one");
    assert.equal(animal.activity, "grazing", "and the standing one is `Eating`");
    assert.equal(animal.owner, "player", "it is still the kingdom's animal throughout");
  }
  assert.equal(
    pasture.pennedAnimals(structure).length,
    penned.length,
    "and the pen still holds exactly what it held",
  );
  assert.equal(
    pasture.isLivestockPresentationVisible(penned[0]!, () => "settlement"),
    true,
    "Settlement Lv1 draws the livestock in its open pen",
  );
  assert.deepEqual(
    pasture.livestockPresentationOffset(penned[0]!),
    { x: 0, y: 0, z: 0 },
    "Lv1 keeps its already-correct ground presentation",
  );
  structure.level = 2;
  assert.deepEqual(
    pasture.livestockPresentationOffset(penned[0]!),
    { x: 0.25, y: 0.28, z: 0 },
    "Lv2 alone lifts and moves livestock forward onto its raised stone floor",
  );
  structure.level = 3;
  assert.equal(
    pasture.isLivestockPresentationVisible(penned[0]!, () => "settlement"),
    false,
    "Settlement Lv3 hides livestock inside its closed pasture",
  );
  structure.level = 1;
  assert.equal(
    pasture.isLivestockPresentationVisible(penned[0]!, () => "town"),
    false,
    "the enclosed Town pasture keeps that presentation rule",
  );
  fixture.territory.dispose();
});

check("V3 Faz 3: a shepherd the wolf kills lets go of the animal he was holding", () => {
  // V2 Faz 7's four-reader lesson, re-asked for a death that arrives from a
  // system none of those readers has heard of. Nothing about a bite is special —
  // it is `health.damage`, the same call a soldier's blow makes — and that is
  // exactly the claim worth pinning, because the cheap way to write a predator is
  // a bespoke kill path that forgets to look like a death.
  const fixture = pastureDriveFixture({
    herdCount: 1,
    herdX: 6,
    // Only the pasture's own ground is held, so the drive walks out into the open
    // where KARAR 1 lets a wolf interrupt it.
    control: { x: 12, z: 0, radius: 5 },
    extraHerds: [{ id: "den", species: "wolf", x: 0, z: 0, count: 1 }],
  });
  const { wildlife, units, pasture, territory, animals } = fixture;
  const cowStats = animals.cow ?? assert.fail("cow balance missing");
  const predatorStats = animals.wolf?.predator ?? assert.fail("wolf predator block missing");
  const cow = wildlife.all().find((animal) => animal.stats.id === "cow") ?? assert.fail("no cow spawned");
  const wolf = wildlife.all().find((animal) => animal.stats.id === "wolf") ?? assert.fail("no wolf spawned");
  // Both planted on unowned ground: a cow free to wander its full eight units
  // could drift back inside the pasture's circle and make the drive safe, which
  // would leave this test passing for the wrong reason.
  cow.rehome({ ...wildProfileFor(cowStats, 0, 0), roamRadius: 0.5 });
  cow.position.set(0, 0, 0);
  wolf.position.set(0, 0, 0);
  assert.equal(territory.ownerAt(0, 0), "neutral", "the herd grazes outside the kingdom's control area");

  const predators = new PredatorSystem(units, wildlife, (x, z) => territory.ownerAt(x, z));
  const shepherd = units.spawn("player", 12, 4, RTS_TEST_WORKER_STATS);
  const strikes: PredatorStrike[] = [];
  const step = 0.25;
  const tick = (): void => {
    pasture.update(step);
    predators.update(step).forEach((strike) => strikes.push(strike));
    wildlife.update(step, units.all().map((unit) => unit.position));
    updateUnitMovement(units.all(), step);
  };

  for (let index = 0; index < 4000 && pasture.stateFor(shepherd) !== "calming"; index += 1) tick();
  assert.equal(pasture.stateFor(shepherd), "calming", "the shepherd reached the cow and got hold of it");
  const held = wildlife.reservationOf(shepherd.id) ?? assert.fail("a calming shepherd has claimed his animal");
  assert.equal(held.id, cow.id, "and the claim is on the cow he was sent for");
  assert.equal(
    territory.ownerAt(shepherd.position.x, shepherd.position.z),
    "neutral",
    "he is doing it out in the open, which is the only reason the wolf may touch him",
  );

  // Left exactly one bite from death, so what finishes him is unambiguously the
  // wolf's rather than whatever else the tick happens to run.
  shepherd.health.damage(shepherd.health.current - predatorStats.damage);
  const before = strikes.length;
  for (let index = 0; index < 800 && !shepherd.health.depleted; index += 1) tick();
  assert.equal(shepherd.health.depleted, true, "the wolf finished him");
  assert.ok(strikes.length > before, "and a bite is what did it");
  assert.equal(strikes[strikes.length - 1]?.victim, shepherd, "the last blow was the wolf's, on him");

  // The readers, one pass later: nothing the job left behind outlives the body.
  tick();
  assert.equal(wildlife.reservationOf(shepherd.id), null, "no claim outlives the shepherd");
  assert.equal(cow.reservedByWorkerId, null, "the cow is unclaimed again");
  assert.equal(cow.lead, null, "and nobody is walking it — a lead nobody holds strands it forever");
  assert.equal(cow.owner, "wild", "it never became anybody's livestock");
  assert.equal(pasture.stateFor(shepherd), "idle", "and the pasture has let the job go");
  assert.equal(
    wildlife.huntableAnimalsNear(0, 0, 2).some((animal) => animal.id === cow.id),
    true,
    "so the next shepherd can be sent for the same cow",
  );
  territory.dispose();
});

// --- Pasture and taming V2 Faz 6: the bull fights back ---

/**
 * A drive with the retaliation system wired in, and a record of every blow that
 * landed during it.
 *
 * One animal in the herd and one shepherd on purpose: the point of these
 * assertions is a single struggle whose whole arithmetic can be checked against
 * the table, not a field of them.
 */
function retaliationDriveFixture(species: string, options: { readonly leaveHealth?: number } = {}) {
  const fixture = pastureDriveFixture({ species, herdCount: 1, herdX: 6 });
  const retaliation = new WildlifeRetaliationSystem(fixture.units, fixture.wildlife);
  const shepherd = fixture.units.spawn("player", 10, 4, RTS_TEST_WORKER_STATS);
  if (options.leaveHealth !== undefined) {
    shepherd.health.damage(Math.max(0, shepherd.health.max - options.leaveHealth));
  }
  const strikes: WildlifeStrike[] = [];
  const statesWhenStruck = new Set<string>();
  const step = 0.25;
  const tick = (): void => {
    fixture.pasture.update(step);
    fixture.wildlife.update(step, fixture.units.all().map((unit) => unit.position));
    updateUnitMovement(fixture.units.all(), step);
    // Last, exactly as `RtsApp` orders it: a blow lands on whoever is still
    // standing over the animal once both of them have moved.
    const landed = retaliation.update(step);
    for (const strike of landed) statesWhenStruck.add(fixture.pasture.stateFor(strike.worker));
    strikes.push(...landed);
  };
  return { ...fixture, retaliation, shepherd, strikes, statesWhenStruck, step, tick };
}

check("V2 Faz 6: driving a bull wounds the shepherd holding it, and driving a cow does not", () => {
  const bullRun = retaliationDriveFixture("bull");
  const bull = bullRun.animals.bull ?? assert.fail("bull balance missing");
  const profile = bull.retaliation ?? assert.fail("the bull is the species that fights back");
  const quarry = bullRun.wildlife.all()[0] ?? assert.fail("no bull spawned");
  // Run until the struggle has actually produced blows, and stop there. How many
  // a bull gets in before it gives up — whether the shepherd survives at all —
  // is the tuning this phase exists to let somebody choose, so nothing below
  // asks for a particular answer to it.
  for (
    let tick = 0;
    tick < 2400 && bullRun.strikes.length < 3
      && quarry.owner === "wild" && !bullRun.shepherd.health.depleted;
    tick += 1
  ) bullRun.tick();

  // Derived from the table rather than pinned: whatever the damage is retuned
  // to, the shepherd's wound is the blows he took times that number.
  assert.ok(bullRun.strikes.length > 0, "a bull being calmed fights the shepherd calming it");
  assert.equal(
    bullRun.shepherd.health.max - bullRun.shepherd.health.current,
    bullRun.strikes.length * profile.damage,
    "every point of the wound came from a blow the bull actually landed",
  );
  assert.equal(
    quarry.strikeCount,
    bullRun.strikes.length,
    "and presentation is told about each one, so `Attack_Headbutt` plays per blow rather than on a loop",
  );
  // §4.3's narrow door: the bull answers being *handled*, and stops the moment
  // it has been beaten. A shepherd gored all the way home would be the animal
  // winning a struggle it had already lost.
  assert.deepEqual(
    [...bullRun.statesWhenStruck],
    ["calming"],
    "the blows land while it is being calmed, never once it is walking home",
  );
  // V1 §3.9, measured rather than assumed: a struck worker does *not* fight
  // back. The defensive path needs an attacking `Unit` (`retaliateAgainstAttack`
  // takes one, and only `resolveCombatHit` calls it), and an animal is a
  // `CombatTarget` that is not a `Unit` — so no wildlife blow can set the
  // `autoAcquired` flag that `unitCombat` requires before a worker swings. The
  // shepherd stands there and takes it, which is §4.3's whole point: the risk is
  // the price of the bull, not the opening of a worker-versus-wildlife war.
  assert.equal(bullRun.shepherd.attackTarget, null, "a gored shepherd acquires nothing");
  assert.equal(bullRun.shepherd.autoAcquired, false, "and never enters combat over it");

  // The two halves of "it stops once it is beaten", set up directly rather than
  // waiting for a drive to happen to put the pair in contact: a bull standing on
  // top of a worker who has claimed it, once as that kingdom's own livestock and
  // once as a wild animal already on a lead. Both are the same sentence — this
  // fight is over — and a full minute of ticks is given to break it in.
  const bystander = bullRun.units.spawn("player", quarry.position.x, quarry.position.z, RTS_TEST_WORKER_STATS);
  quarry.lead = null;
  quarry.reservedByWorkerId = bystander.id;
  quarry.owner = "player";
  bullRun.retaliation.update(60);
  assert.equal(quarry.attacking, false, "a penned bull has nothing left to fight");
  assert.equal(bystander.health.current, bystander.health.max, "and never gores the kingdom that owns it");
  quarry.owner = "wild";
  quarry.lead = { x: bystander.position.x, z: bystander.position.z, follow: true };
  bullRun.retaliation.update(60);
  assert.equal(bystander.health.current, bystander.health.max, "a bull being walked home is a bull that lost");
  bullRun.territory.dispose();

  // The control, and the reason the field is optional: an animal with no
  // retaliation block is handled without a scratch.
  const cowRun = retaliationDriveFixture("cow");
  const cow = cowRun.animals.cow ?? assert.fail("cow balance missing");
  assert.equal(cow.retaliation, undefined, "the cow simply submits");
  const calf = cowRun.wildlife.all()[0] ?? assert.fail("no cow spawned");
  for (let tick = 0; tick < 2400 && calf.owner === "wild"; tick += 1) cowRun.tick();
  assert.equal(calf.owner, "player", "the cow was penned too, so the two runs are comparable");
  assert.equal(cowRun.strikes.length, 0, "and nothing was struck");
  assert.equal(cowRun.shepherd.health.current, cowRun.shepherd.health.max, "the cow's shepherd is untouched");
  cowRun.territory.dispose();
});

check("V2 Faz 6: a bull that kills its shepherd frees itself, and the pasture sends the next one", () => {
  // Sent out with exactly one blow left in him, computed from the table rather
  // than chosen: whatever the bull's damage is retuned to, the first hit that
  // lands is the one that kills him — so the death path is reached at any tuning
  // rather than only at the shipped one.
  const bull = shippedAnimalBalance().bull ?? assert.fail("bull balance missing");
  const profile = bull.retaliation ?? assert.fail("the bull is the species that fights back");
  const fixture = retaliationDriveFixture("bull", { leaveHealth: profile.damage });
  const { wildlife, units, pasture, shepherd } = fixture;
  const quarry = wildlife.all()[0] ?? assert.fail("no bull spawned");
  for (let tick = 0; tick < 2400 && !shepherd.health.depleted; tick += 1) fixture.tick();
  assert.equal(shepherd.health.depleted, true, "the bull killed the man holding it");
  assert.equal(fixture.strikes.length, 1, "one blow, and it was the bull's");

  // Faz 4's release path, reached from a new direction: the job is dropped, the
  // animal is let go rather than left standing mid-lead, and it is wild again.
  fixture.tick();
  assert.equal(pasture.isShepherd(shepherd), false, "a dead shepherd holds no job");
  assert.equal(quarry.lead, null, "the bull is not left holding a lead nobody is walking");
  assert.equal(quarry.owner, "wild", "and it is still wild — it won this round");
  assert.equal(quarry.reservedByWorkerId, null, "its claim is free again");
  assert.equal(quarry.attacking, false, "with nobody to fight, it stops fighting");

  // §2.9's promise is a price, not a dead end: the pasture hires again rather
  // than writing the job off, and the next man out pays the same toll. Whether
  // he lives to finish is the tuning, and is nobody's business here.
  const relief = units.spawn("player", 10, -4, RTS_TEST_WORKER_STATS);
  let relieved = false;
  for (let tick = 0; tick < 2400 && relief.health.current === relief.health.max; tick += 1) {
    fixture.tick();
    relieved ||= pasture.isShepherd(relief);
  }
  assert.equal(relieved, true, "the pasture sent the next shepherd out to the same bull");
  assert.ok(relief.health.current < relief.health.max, "and he pays the same toll on the way");
  fixture.territory.dispose();
});

check("V2 Faz 4: your own livestock is never fogged, and the opponent's still is", () => {
  const field = new Group();
  const view = new WildlifeView(field);
  const wildlife = new WildlifeSystem(shippedAnimalBalance(), [
    { id: "mine", species: "cow", x: -30, z: -30, count: 1 },
    { id: "theirs", species: "cow", x: 30, z: 30, count: 1 },
  ]);
  const [mine, theirs] = wildlife.all();
  if (!mine || !theirs) return assert.fail("the two herds did not spawn");
  // Both penned, one to each kingdom, and nobody can see either point.
  wildlife.tame(mine.id, "player", { x: -30, z: -30, facing: 0 });
  wildlife.tame(theirs.id, "enemy", { x: 30, z: 30, facing: 0 });
  view.setPresentationFactory(() => ({
    root: new Object3D(),
    pickTargets: [],
    selectionRadius: 0.5,
    dispose: () => {},
  }));

  view.sync(wildlife.all(), 0, null, () => false, "player");
  const bodies = field.children;
  assert.equal(bodies.length, 2, "both animals got a body");
  assert.ok(
    bodies.filter((body) => body.position.x < 0).every((body) => body.visible),
    "a kingdom does not lose track of its own cattle in its own pen",
  );
  assert.ok(
    bodies.filter((body) => body.position.x > 0).every((body) => !body.visible),
    "the opponent's herd keeps the moving-thing rule in full",
  );
  // And the rule itself, without a view: ownership only ever *adds* visibility.
  assert.equal(isWildlifeVisible("player", 0, 0, () => false, "player"), true);
  assert.equal(isWildlifeVisible("enemy", 0, 0, () => false, "player"), false);
  assert.equal(isWildlifeVisible("wild", 0, 0, () => false, "player"), false);
  view.dispose();
});

check("V2 Faz 8: enclosed livestock leaves the renderer but not the simulation", () => {
  const field = new Group();
  const view = new WildlifeView(field);
  const wildlife = new WildlifeSystem(shippedAnimalBalance(), [
    { id: "pen", species: "cow", x: 0, z: 0, count: 1 },
  ]);
  const animal = wildlife.all()[0] ?? assert.fail("the pen fixture needs a cow");
  assert.ok(wildlife.tame(animal.id, "player", { x: 1, z: 0, facing: 0 }), "the cow is penned");
  view.setPresentationFactory(() => ({
    root: new Object3D(),
    pickTargets: [],
    selectionRadius: 0.5,
    dispose: () => {},
  }));

  view.sync(wildlife.all(), 0, null, undefined, undefined, () => true, () => ({ x: 0.25, y: 0.28, z: 0 }));
  assert.equal(field.children.length, 1, "an open pasture draws its penned animal");
  assert.equal(
    field.children[0]?.position.x,
    animal.position.x + 0.25,
    "the Lv2 art correction moves only the rendered animal forward",
  );
  assert.equal(
    field.children[0]?.position.y,
    animal.position.y + 0.46,
    "the animal can be lifted onto a raised stone floor visually",
  );

  view.sync(wildlife.all(), 0, null, undefined, undefined, () => false);
  assert.equal(field.children.length, 0, "an enclosed pasture releases the animal model");
  assert.equal(animal.owner, "player", "hiding the model never changes livestock ownership");
  assert.notEqual(animal.stall, null, "or its penned simulation state");

  view.sync(wildlife.all(), 0, null, undefined, undefined, () => true);
  assert.equal(field.children.length, 1, "a later open state recreates the presentation");
  view.dispose();
});

check("RTS collapse deformation patches the husk's own materials, never the ones it was cloned from", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const house = buildings.house ?? assert.fail("house balance missing");
  const structures = new PlacedStructureSystem();
  const structure = structures.place("player", house, 0, 0);
  structures.advanceConstruction(structure, house.constructionSeconds);
  const visual = structure.object.getObjectByName("rts-complete-building-placeholder")
    ?? assert.fail("the completed visual is missing");

  const standing = structureVisualMaterials(visual)[0] ?? assert.fail("the completed visual has no material");
  structures.destroy(structure);
  const husk = structureVisualMaterials(visual)[0] ?? assert.fail("the husk lost its material");

  // The ordering that makes the whole approach safe: the husk is deformed only
  // after its materials are privatised, so a collapse can never bend every other
  // standing building that shares the model's materials.
  assert.notEqual(husk, standing, "the husk collapses on its own material copies");
  assert.deepEqual(
    compileStructureDeformPatch(standing).uniforms,
    {},
    "the material the copy was taken from is left unpatched",
  );
  const patched = compileStructureDeformPatch(husk);
  assert.ok("rtsDeformProgress" in patched.uniforms, "the husk's own copy carries the deformation");
  assert.ok(
    patched.vertexShader.includes("transformed = rtsDeformPosition("),
    "the patch displaces the vertex three is about to transform",
  );
  assert.ok(
    patched.vertexShader.includes("objectNormal = rtsDeformNormal("),
    "and corrects the normal, so a squashed face does not light as if it were still pitched",
  );
  structures.clear();
});

check("RTS collapse deformation gives every husk its own progress and drives it to exactly 1", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const house = buildings.house ?? assert.fail("house balance missing");
  const structures = new PlacedStructureSystem();
  const first = structures.place("player", house, 0, 0);
  const second = structures.place("player", house, 20, 0);
  structures.advanceConstruction(first, house.constructionSeconds);
  structures.advanceConstruction(second, house.constructionSeconds);
  const firstVisual = first.object.getObjectByName("rts-complete-building-placeholder")
    ?? assert.fail("the first completed visual is missing");
  const secondVisual = second.object.getObjectByName("rts-complete-building-placeholder")
    ?? assert.fail("the second completed visual is missing");

  structures.destroy(first);
  structures.destroy(second);
  const firstMaterial = structureVisualMaterials(firstVisual)[0] ?? assert.fail("no husk material");
  const secondMaterial = structureVisualMaterials(secondVisual)[0] ?? assert.fail("no husk material");
  const firstProgress = compileStructureDeformPatch(firstMaterial).uniforms.rtsDeformProgress;
  const secondProgress = compileStructureDeformPatch(secondMaterial).uniforms.rtsDeformProgress;

  // The classic failure of a uniform-driven effect: two husks handed the same
  // `{ value }` box collapse in lockstep, and one clearing resets the other.
  assert.notEqual(firstProgress, secondProgress, "two husks never share one progress box");
  assert.equal(
    compileStructureDeformPatch(firstMaterial).uniforms.rtsDeformProgress,
    firstProgress,
    "recompiling a material rebinds the box it already had, rather than making a second one",
  );

  const progress = firstProgress as { value: number };
  assert.equal(progress.value, 0, "a husk that has not started falling is undeformed");
  structures.updateVisualAnimations(0.45);
  assert.ok(progress.value > 0 && progress.value < 1, "the shape gives way while the building goes over");
  structures.updateVisualAnimations(5);
  assert.equal(progress.value, 1, "the fall ends fully deformed, and the ruin holds that shape");
  structures.clear();
});

check("RTS heavy damage buckles a building, light damage does not, and repair puts the shape back", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const house = buildings.house ?? assert.fail("house balance missing");
  const structures = new PlacedStructureSystem();
  const structure = structures.place("player", house, 0, 0);
  structures.advanceConstruction(structure, house.constructionSeconds);
  const visual = structure.object.getObjectByName("rts-complete-building-placeholder")
    ?? assert.fail("the completed visual is missing");
  const mesh = visual instanceof Mesh ? visual : assert.fail("the completed placeholder is a mesh");
  const intact = mesh.material;
  assert.equal(mesh.castShadow, true, "buildings cast shadows, so the shadow pass has to follow the deformation");

  // Light damage reads through colour alone. A building that visibly bends the
  // moment it is scratched would make every skirmish look like a siege.
  structure.health.damage(structure.health.max * 0.5);
  structures.updateVisualAnimations(0.1);
  assert.deepEqual(
    compileStructureDeformPatch(structureVisualMaterials(visual)[0] ?? assert.fail("no material")).uniforms,
    {},
    "light damage leaves the geometry straight",
  );
  assert.equal(mesh.customDepthMaterial, undefined, "and installs no shadow override");

  structure.health.damage(structure.health.max * 0.25);
  structures.updateVisualAnimations(0.1);
  const heavy = compileStructureDeformPatch(
    structureVisualMaterials(visual)[0] ?? assert.fail("no material"),
  ).uniforms;
  assert.equal(
    (heavy.rtsDeformProgress as { value: number }).value,
    1,
    "heavy damage is a held state, not an animation that has to be ticked",
  );
  assert.ok(mesh.customDepthMaterial, "the shadow pass deforms with the building");

  // Repair is the reason this is a uniform rather than an edited vertex buffer:
  // undoing it is dropping the material clone the patch lived on.
  structure.health.heal(structure.health.max);
  structures.updateVisualAnimations(0.1);
  assert.equal(mesh.material, intact, "a repaired building is back on its original material");
  assert.equal(mesh.customDepthMaterial, undefined, "and casts its original, upright shadow again");
  structures.clear();
});

check("RTS ruin lifetime is authored per building, not fixed in the collapse code", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const house = buildings.house ?? assert.fail("house balance missing");
  const raze = (system: PlacedStructureSystem): PlacedStructure => {
    const structure = system.place("player", house, 0, 0);
    system.advanceConstruction(structure, house.constructionSeconds);
    system.destroy(structure);
    // Two steps, not one: a ruin created mid-frame is still swept by that same
    // frame's ruin pass, so finishing the fall on a large step would start its
    // clock at that step. The sliver leaves the ruin window effectively at zero.
    system.updateVisualAnimations(0.89);
    system.updateVisualAnimations(0.01);
    return structure;
  };

  const authored = new PlacedStructureSystem();
  authored.setDamagePresentationHandler({ ruinSeconds: () => 3 });
  const short = raze(authored);
  authored.updateVisualAnimations(2.9);
  assert.equal(short.object.parent, authored.root, "the ruin stands for the window the table authored");
  authored.updateVisualAnimations(0.2);
  assert.equal(short.object.parent, null, "and leaves when that window closes");
  authored.clear();

  // A fork with no damage table still gets a readable ruin rather than a husk
  // that never leaves. Derived from the exported constant, so retuning it here
  // cannot leave this test asserting a number the code no longer uses.
  const bare = new PlacedStructureSystem();
  const standard = raze(bare);
  bare.updateVisualAnimations(DEFAULT_RUIN_SECONDS - 0.5);
  assert.equal(standard.object.parent, bare.root, "the default window is the exported one");
  bare.updateVisualAnimations(1);
  assert.equal(standard.object.parent, null);
  bare.clear();
});

check("RTS deformation amounts are authored in the damage table, not hard-coded in the husk", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const house = buildings.house ?? assert.fail("house balance missing");
  const squashUniform = (squash: number): { x: number; y: number; z: number } => {
    const structures = new PlacedStructureSystem();
    structures.setDamagePresentationHandler({
      collapseDeformation: () => ({ squash, splay: 0.2, buckle: 0 }),
    });
    const structure = structures.place("player", house, 0, 0);
    structures.advanceConstruction(structure, house.constructionSeconds);
    const visual = structure.object.getObjectByName("rts-complete-building-placeholder")
      ?? assert.fail("the completed visual is missing");
    structures.destroy(structure);
    const material = structureVisualMaterials(visual)[0] ?? assert.fail("the husk lost its material");
    const amount = compileStructureDeformPatch(material).uniforms.rtsDeformAmount as {
      value: { x: number; y: number; z: number };
    };
    structures.clear();
    return amount.value;
  };

  const single = squashUniform(0.3);
  const double = squashUniform(0.6);
  // Proportionality, not a magnitude: the shader scales the authored number by
  // the height ramp per vertex, so pinning a product here would make retuning
  // either the table or the ramp a red build for no reason.
  assert.ok(single.x > 0, "an authored squash reaches the shader");
  assert.ok(Math.abs(double.x / single.x - 2) < 1e-9, "doubling the authored squash doubles what the shader gets");
  assert.equal(single.z, 0, "an authored zero stays zero — buckle is opt-out from the table");
  assert.ok(single.y > 0, "and splay travels the same path");
});

check("RTS structure impacts are reported per blow, so debris cannot fire on a timer", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const house = buildings.house ?? assert.fail("house balance missing");
  const structures = new PlacedStructureSystem();
  const impacts: number[] = [];
  structures.setDamagePresentationHandler({ onDamaged: (_structure, amount) => impacts.push(amount) });

  const structure = structures.place("player", house, 0, 0);
  structures.advanceConstruction(structure, house.constructionSeconds);
  structures.updateVisualAnimations(0.1);
  assert.deepEqual(impacts, [], "a building nobody is hitting sheds nothing");

  const blow = structure.health.max * 0.2;
  structure.health.damage(blow);
  structures.updateVisualAnimations(0.1);
  assert.deepEqual(impacts, [blow], "a blow is reported once, with the health it took");

  // The regression this replaces: debris used to be a repeating slot, so a
  // wounded building shed masonry forever while standing untouched.
  for (let i = 0; i < 30; i += 1) structures.updateVisualAnimations(0.5);
  assert.deepEqual(impacts, [blow], "and fifteen seconds of standing there damaged reports nothing further");

  structure.health.damage(blow);
  structures.updateVisualAnimations(0.1);
  assert.deepEqual(impacts, [blow, blow], "the next blow is a new impact");

  structure.health.heal(structure.health.max);
  structures.updateVisualAnimations(0.1);
  assert.deepEqual(impacts, [blow, blow], "repairing a building is not an impact");

  // A foundation has no masonry to shed; debris off a half-built frame reads as
  // a bug rather than as damage.
  const site = structures.place("player", house, 20, 0);
  structures.updateVisualAnimations(0.1);
  site.health.damage(site.health.max * 0.3);
  structures.updateVisualAnimations(0.1);
  assert.deepEqual(impacts, [blow, blow], "an unfinished site takes damage silently");
  structures.clear();
});

check("RTS ruin clearing is announced so trailing husk VFX cannot outlive the husk", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const farm = buildings.farm ?? assert.fail("farm balance missing");
  const structures = new PlacedStructureSystem();
  const cleared: number[] = [];
  structures.setDamagePresentationHandler({ onRuinCleared: (id) => cleared.push(id) });

  const timedOut = structures.place("player", farm, 0, 0);
  structures.advanceConstruction(timedOut, farm.constructionSeconds);
  structures.destroy(timedOut);
  // Past the fall, then past the ruin window: the husk leaves on its own.
  structures.updateVisualAnimations(1);
  assert.deepEqual(cleared, [], "a standing ruin is not announced as cleared");
  structures.updateVisualAnimations(60);
  assert.deepEqual(cleared, [timedOut.id], "the timed-out ruin reports its own id");

  // A husk still mid-fall when the match resets must be announced too, or the
  // smoke it was venting would outlive the match that spawned it.
  const midFall = structures.place("player", farm, 8, 0);
  structures.advanceConstruction(midFall, farm.constructionSeconds);
  structures.destroy(midFall);
  structures.updateVisualAnimations(0.1);
  structures.clear();
  assert.deepEqual(cleared, [timedOut.id, midFall.id], "match cleanup releases the falling husk");
});

/**
 * **The balance-data rule, for every check below that reads
 * `public/game-data/balance/*.json`.**
 *
 * These tables exist so the numbers can be changed without touching code. A test
 * that pins a magnitude takes that away again: the next tuning pass turns red,
 * and what the red build teaches is not "you broke something" but "edit the test
 * until it agrees" — which is how a suite stops being read.
 *
 * So: assert the **contract**, never the **tuning**.
 *
 * - Shape — the field exists, is positive, names the right resource, covers
 *   every tier.
 * - Relationships — Town outranks Settlement, external deposits beat safe ones,
 *   a siege gun outranges the archer escorting it. These encode design
 *   decisions, and a retune that inverts one is a real regression.
 * - Derivation — where a test needs an amount, compute it from the same table
 *   (`1200 - lv2Cost.cost.food`), so the arithmetic stays true at any tuning.
 *
 * The validators are the other half of this: a value that must never be
 * nonsensical (a zero-capacity deposit, an arbitrage-positive market) is refused
 * at load in `validateGameData.ts`, where the failure names the file and the
 * field rather than a test line number.
 */
check("unit balance validates combat stats for stable unit ids", () => {
  const balance = validateUnitBalance(
    JSON.parse(readFileSync("public/game-data/balance/units.json", "utf8")) as unknown,
  );
  // The roster contract, not the tuning: asserting concrete health/damage here
  // would make every balance pass a test failure (plan §75).
  assert.deepEqual(
    Object.keys(balance).sort(),
    ["archer_placeholder", "guard_placeholder", "siege_placeholder", "worker_placeholder"],
    "Faz 7 ships the Guard/Archer/Siege core roster plus the worker",
  );
  // Every definition carries its own key back out. Nothing authors this in the
  // file body; it is stamped from the key so the id a unit is grouped and
  // bulk-selected by cannot drift from the id it is trained by.
  for (const [id, stats] of Object.entries(balance)) {
    assert.equal(stats.id, id, `"${id}" carries its key as its id`);
  }
  assert.equal(balance["guard_placeholder"]?.role, "guard");
  assert.equal(balance["archer_placeholder"]?.attackType, "ranged");
  assert.ok(
    (balance["archer_placeholder"]?.projectileSpeed ?? 0) > 0,
    "the Archer owns a positive visual Arrow speed in balance data",
  );
  assert.equal(balance["siege_placeholder"]?.role, "siege");
  // The siege line is a gun, not a battering ram: it throws its shot, and it throws it
  // from further out than the Archer walking beside it.
  assert.equal(balance["siege_placeholder"]?.attackType, "ranged");
  assert.equal(balance["siege_placeholder"]?.structureAttackVfx, "cannonball");
  // The shell's blast is an authored effect asset, not a shape the cannonball
  // system draws. Which effect is authoring and may change; that the id the gun
  // names still resolves to something the manifest ships is the contract — a
  // renamed or unregistered `.effect.json` would otherwise cost every siege
  // shot its explosion with nothing failing.
  const siegeBurst = balance["siege_placeholder"]?.impactEffect
    ?? assert.fail("the artillery names the effect its shell bursts into");
  assert.ok(
    parseRtsEffectManifest(
      JSON.parse(readFileSync("public/assets/manifest.json", "utf8")) as unknown,
    ).has(siegeBurst),
    `"${siegeBurst}" is a manifested effect asset`,
  );
  assert.ok(
    balance["siege_placeholder"]!.attackRange > balance["archer_placeholder"]!.attackRange,
    "the gun opens fire from behind the line that escorts it",
  );
  // A worker is bought with food and nothing else — the claim that makes food a
  // growth resource rather than a second wood. The amount is tuning.
  assert.deepEqual(Object.keys(balance["worker_placeholder"]?.cost ?? {}), ["food"]);
  assert.ok((balance["worker_placeholder"]?.cost.food ?? 0) > 0);

  // The Town milestone is the whole gate for the Town-age roster: the Archer opens
  // from a Town-age Range and the artillery from the Barracks the kingdom already
  // owns, both the moment the age commits. No shipped unit asks for a centre level
  // above the Lv1 the Town transition resets every kingdom to — a second gate one
  // upgrade past the age read as a Town that had not actually arrived.
  assert.equal(balance["guard_placeholder"]?.requiredSettlementLevel, 1);
  assert.equal(balance["archer_placeholder"]?.requiredSettlementLevel, 1);
  assert.equal(balance["siege_placeholder"]?.requiredSettlementLevel, 1);
  assert.equal(balance["siege_placeholder"]?.requiredAge, "town");
  assert.equal(balance["siege_placeholder"]?.productionBuildingId, "barracks");
  assert.equal(balance["archer_placeholder"]?.productionBuildingId, "archery_range");
  assert.equal(balance["archer_placeholder"]?.requiredAge, "town");

  for (const [id, stats] of Object.entries(balance)) {
    if (id === "worker_placeholder") continue;
    assert.ok(stats.moveSpeed > 0, `${id} carries a data-owned move speed`);
    assert.ok(stats.acquisitionRange > 0, `${id} can find its own targets`);
  }
  // GDD 12 §33 read as a contract rather than as numbers: each role's identity
  // is which column it is best against, and that must hold after any retune.
  const bestClass = (id: string) =>
    (Object.entries(balance[id]!.damageMultipliers) as [string, number][])
      .sort((left, right) => right[1] - left[1])[0]![0];
  assert.equal(bestClass("guard_placeholder"), "heavy", "the Guard is the front-line answer to other heavies");
  assert.equal(bestClass("archer_placeholder"), "light", "the Archer punishes light units");
  // The Topçu is deliberately *not* read through `bestClass`. It is the one
  // weapon with no soft column — a shell answers whatever it is pointed at —
  // so the highest column would only report which way a tie broke. Its two
  // real claims are stated instead, and both must survive a retune.
  const siege = balance["siege_placeholder"]!;
  assert.ok(
    siege.damageMultipliers.structure > balance["guard_placeholder"]!.damageMultipliers.structure * 4,
    "plan §46: siege is *necessary* against buildings, not merely better",
  );
  assert.ok(
    Math.min(siege.damageMultipliers.light, siege.damageMultipliers.heavy)
      > Math.max(...Object.values(balance["archer_placeholder"]!.damageMultipliers)),
    "and it answers massed bodies too: one shell beats the Archer's best column against every armour class",
  );
  assert.ok(
    balance["archer_placeholder"]!.attackRange > balance["guard_placeholder"]!.attackRange * 3,
    "plan §46: the Archer is only effective while it is not reached",
  );

  assert.throws(
    () => validateUnitBalance({ guard_placeholder: { ...RTS_TEST_UNIT_STATS, maxHealth: 0 } }),
    GameDataError,
  );
  assert.throws(
    () => validateUnitBalance({ guard_placeholder: { ...RTS_TEST_UNIT_STATS, attackCooldown: 0 } }),
    GameDataError,
  );
  assert.throws(
    () => validateUnitBalance({ archer_placeholder: { ...RTS_TEST_ARCHER_STATS, projectileSpeed: 0 } }),
    GameDataError,
    "a nonpositive projectile speed is invalid balance data",
  );
  assert.throws(
    () => validateUnitBalance({ guard_placeholder: { ...RTS_TEST_UNIT_STATS, trainingSeconds: 0 } }),
    GameDataError,
  );
  assert.throws(
    () => validateUnitBalance({ guard_placeholder: { ...RTS_TEST_UNIT_STATS, moveSpeed: 0 } }),
    GameDataError,
    "a motionless unit is a data bug, not a design",
  );
  assert.throws(
    () => validateUnitBalance({ guard_placeholder: { ...RTS_TEST_UNIT_STATS, role: "cavalry" } }),
    GameDataError,
    "cavalry is out of vertical-slice scope; the id must not slip in through data",
  );
  assert.throws(
    () => validateUnitBalance({ guard_placeholder: { ...RTS_TEST_UNIT_STATS, armorClass: "structure" } }),
    GameDataError,
    "only buildings carry the structure armour class",
  );
  assert.throws(
    () => validateUnitBalance({
      guard_placeholder: { ...RTS_TEST_UNIT_STATS, damageMultipliers: { light: 1, heavy: 1 } },
    }),
    GameDataError,
    "an attacker missing a §33 column would silently resolve to NaN damage",
  );
  assert.throws(
    () => validateUnitBalance({
      guard_placeholder: { ...RTS_TEST_UNIT_STATS, damageMultipliers: { light: 1, heavy: 1, structure: 0 } },
    }),
    GameDataError,
    "§33 counters are soft: a zero multiplier makes a matchup unwinnable",
  );
  assert.throws(
    () => validateUnitBalance({ guard_placeholder: { ...RTS_TEST_UNIT_STATS, chaseRange: 1 } }),
    GameDataError,
    "a leash shorter than acquisition would drop a target on the tick it was found",
  );
  assert.throws(
    () => validateUnitBalance({ archer_placeholder: { ...RTS_TEST_ARCHER_STATS, acquisitionRange: 2 } }),
    GameDataError,
    "a unit that sees less far than it shoots could never open fire",
  );
  assert.throws(
    () => validateUnitBalance({ guard_placeholder: { ...RTS_TEST_UNIT_STATS, impactEffect: "rts-fx-explosion" } }),
    GameDataError,
    "only a lobbed shot has a landing to burst at; anywhere else the effect would silently never play",
  );
  assert.throws(
    () => validateUnitBalance({ siege_placeholder: { ...RTS_TEST_SIEGE_STATS, impactEffect: "../secret.effect.json" } }),
    GameDataError,
    "an impact burst names a manifest asset id, never a path",
  );
  assert.equal(
    validateUnitBalance({
      siege_placeholder: { ...RTS_TEST_SIEGE_STATS, impactEffect: "rts-fx-explosion" },
    })["siege_placeholder"]?.impactEffect,
    "rts-fx-explosion",
    "the gun's authored burst survives validation",
  );
  assert.throws(() => validateUnitBalance({ "Guard Placeholder": RTS_TEST_UNIT_STATS }), GameDataError);
  assert.throws(
    () => validateUnitBalance({ archer_placeholder: RTS_TEST_UNIT_STATS }),
    GameDataError,
    "a body id that disagrees with its key is a half-finished rename, not a second name",
  );
  assert.equal(
    validateUnitBalance({ heavy_guard: { ...RTS_TEST_UNIT_STATS, id: undefined } })["heavy_guard"]?.id,
    "heavy_guard",
    "an unauthored id is stamped from the key",
  );
});

check("the Topçu shells a defended building from outside the building's own reach", () => {
  // This is the whole point of trading the old battering ram for a gun: siege
  // that has to walk into a Karakol's arrows is siege the defender answers for
  // free. If a retune ever puts the tower's range above the gun's, the unit is
  // a ram again with extra steps — so the relationship, not either number, is
  // the contract.
  const units = validateUnitBalance(
    JSON.parse(readFileSync("public/game-data/balance/units.json", "utf8")) as unknown,
  );
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const defenceRanges = Object.values(buildings)
    .map((building) => building.defense?.attackRange ?? 0);
  const longestDefence = Math.max(...defenceRanges);
  assert.ok(longestDefence > 0, "at least one building shoots back, or this proves nothing");
  assert.ok(
    units["siege_placeholder"]!.attackRange > longestDefence,
    `the gun (${units["siege_placeholder"]!.attackRange}) must outrange the longest building defence (${longestDefence})`,
  );
});

check("building balance validates grid-aligned Phase 2 footprints", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  // Grid alignment is the claim in this check's name, and it is an invariant:
  // placement snaps to a 2-unit grid, so an odd footprint puts a building's edge
  // half a cell off every road it ever touches. The *sizes* are balance data and
  // are not pinned — see the balance-data rule above.
  for (const [id, stats] of Object.entries(buildings)) {
    assert.ok(stats.footprint.width > 0 && stats.footprint.depth > 0, `${id} has a real footprint`);
    assert.equal(stats.footprint.width % 2, 0, `${id} footprint width is grid-aligned`);
    assert.equal(stats.footprint.depth % 2, 0, `${id} footprint depth is grid-aligned`);
  }
  assert.ok((buildings.barracks?.cost.wood ?? 0) > 0, "military production is bought with wood");
  // Shape, not amounts: a producer names one resource, hires a bounded crew, and
  // fills a *finite* local buffer — that buffer being finite is what makes the
  // "full barn, empty treasury" lesson possible at all.
  assert.equal(buildings.farm?.economy?.resourceId, "food");
  assert.ok((buildings.farm?.economy?.workerCapacity ?? 0) > 0);
  assert.ok((buildings.farm?.economy?.perWorkerPerMinute ?? 0) > 0);
  assert.ok((buildings.farm?.economy?.localBufferCapacity ?? 0) > 0);
  const defense = buildings.outpost?.defense;
  assert.ok(defense, "the outpost shoots back");
  assert.ok(defense!.attackDamage > 0 && defense!.attackCooldown > 0 && defense!.attackRange > 0);
  assert.ok(defense!.arrowsPerVolley >= 1);
  // The one relationship worth holding: a tower is anti-infantry, and useless
  // against buildings. Retuning may move all three numbers; it may not invert
  // the roles they encode.
  assert.ok(
    defense!.damageMultipliers.light > defense!.damageMultipliers.heavy,
    "arrows favour light targets over armour",
  );
  assert.ok(
    defense!.damageMultipliers.heavy > defense!.damageMultipliers.structure,
    "a tower is not a siege engine",
  );
  assert.equal(buildings.house?.icon, "/assets/ui/icons/building-house.png");
  assert.equal(buildings.house?.portrait, undefined, "selection artwork reuses the building icon");
  assert.throws(
    () => validateBuildingBalance({ house: { label: "Ev", footprint: { width: 0, depth: 4 }, cost: {}, constructionSeconds: 25 } }),
    GameDataError,
  );
  assert.throws(
    () => validateBuildingBalance({ house: { label: "Ev", icon: "https://example.invalid/house.svg", footprint: { width: 4, depth: 4 }, cost: {}, constructionSeconds: 25, maxHealth: 100, visionRadius: 8 } }),
    GameDataError,
    "UI assets are packaged paths, not arbitrary URLs",
  );
  // Raster icon art is a first-class option: authored artwork does not always
  // come out of a vector tool, and forcing SVG pushed forks toward a fake
  // conversion (a PNG wrapped in an <svg>) that defeats the check entirely.
  const rasterIcon = validateBuildingBalance({
    house: { label: "Ev", icon: "/assets/ui/icons/building-house.png", footprint: { width: 4, depth: 4 }, cost: {}, constructionSeconds: 25, maxHealth: 100, visionRadius: 8 },
  });
  assert.equal(rasterIcon.house?.icon, "/assets/ui/icons/building-house.png");
  assert.throws(
    () => validateBuildingBalance({ house: { label: "Ev", icon: "/assets/ui/icons/building-house.webp", footprint: { width: 4, depth: 4 }, cost: {}, constructionSeconds: 25, maxHealth: 100, visionRadius: 8 } }),
    GameDataError,
    "the allowed extensions stay an explicit list, not anything image-shaped",
  );
});

check("Faz B UI icons are data-driven and every shipped reference exists", () => {
  const tables = [
    validateBuildingBalance(JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown),
    validateUnitBalance(JSON.parse(readFileSync("public/game-data/balance/units.json", "utf8")) as unknown),
    // Trade sites are neither built nor trained, but their selection panel shows
    // the same portrait frame, so their artwork is held to the same rule.
    validateTradeSiteBalance(JSON.parse(readFileSync("public/game-data/balance/trade-sites.json", "utf8")) as unknown),
  ];
  assert.equal(tables[1].worker_placeholder?.icon, "/assets/ui/icons/unit-worker.png");
  assert.equal(tables[1].worker_placeholder?.portrait, undefined, "selection artwork reuses the unit icon");
  for (const table of tables) {
    for (const definition of Object.values(table)) {
      for (const asset of [definition.icon]) {
        assert.ok(asset, `${definition.label} needs a UI artwork reference`);
        assert.ok(statSync(`public${asset}`).isFile(), `${definition.label} references a missing UI asset: ${asset}`);
      }
    }
  }
});

check("Faz 6 stone and gold data defines finite safe and richer external deposits", () => {
  const resources = validateResourceBalance(
    JSON.parse(readFileSync("public/game-data/balance/resources.json", "utf8")) as unknown,
  );
  // Both deposit kinds exist and are finite for both resources; how much they
  // hold is tuning, and the relationship that matters is asserted below.
  for (const id of ["stone", "gold"] as const) {
    for (const kind of ["safeNode", "externalNode"] as const) {
      const node = resources[id]?.[kind];
      assert.ok(node && node.capacity > 0 && node.perWorkerPerMinute > 0, `${id}.${kind} is a real deposit`);
    }
  }
  for (const resource of Object.values(resources)) {
    // Wood is in this table too, as a tree yield rather than a deposit pair, so
    // the deposit relationship is asserted over the resources that have one.
    if (!resource.safeNode || !resource.externalNode) continue;
    assert.ok(resource.externalNode.capacity > resource.safeNode.capacity,
      `${resource.id}: expansion must offer more total material than the safe deposit`);
    assert.ok(resource.safeNode.capacity > 0 && resource.externalNode.perWorkerPerMinute > 0);
  }

  const raw = JSON.parse(readFileSync("public/game-data/balance/resources.json", "utf8")) as Record<string, unknown>;
  assert.throws(() => validateResourceBalance({ wood: raw.wood, gold: raw.gold }), GameDataError,
    "both Faz 6 deposit resources are required");
  assert.throws(() => validateResourceBalance({
    ...raw,
    stone: { ...(raw.stone as object), externalNode: { capacity: 300, perWorkerPerMinute: 7 } },
  }), GameDataError, "external capacity must actually reward expansion");
  assert.throws(() => validateResourceBalance({
    ...raw,
    gold: { ...(raw.gold as object), safeNode: { capacity: 0, perWorkerPerMinute: 3 } },
  }), GameDataError, "empty deposits are invalid data, not an exhausted starting state");
});

check("wood is balanced as a per-tree capacity, and only as a capacity", () => {
  const raw = JSON.parse(readFileSync("public/game-data/balance/resources.json", "utf8")) as Record<string, unknown>;
  const resources = validateResourceBalance(raw);

  // Shape, not magnitude: wood is worked as trees, so it carries a tree yield
  // and no deposit profile at all. The rate a camp cuts at is the building's
  // business (`buildings.json` progression tiers), which is why there is no
  // `perWorkerPerMinute` here to disagree with it.
  const wood = resources.wood ?? assert.fail("wood must be in the resource balance");
  assert.ok(wood.tree && wood.tree.capacity > 0, "wood defines what one tree holds");
  assert.equal(wood.safeNode, undefined, "wood is grown, not deposited");
  assert.equal(wood.externalNode, undefined, "wood is grown, not deposited");
  assert.ok(!("perWorkerPerMinute" in (wood.tree as object)),
    "cutting speed belongs to the lumber camp's tiers, not to the tree");

  assert.throws(() => validateResourceBalance({ ...raw, wood: { label: "Odun" } }), GameDataError,
    "a resource must say how it is worked");
  assert.throws(() => validateResourceBalance({
    ...raw,
    wood: { label: "Odun", tree: { capacity: 60 }, safeNode: { capacity: 1, perWorkerPerMinute: 1 } },
  }), GameDataError, "trees and deposits are exclusive shapes");
  assert.throws(() => validateResourceBalance({ ...raw, wood: { label: "Odun", tree: { capacity: 0 } } }),
    GameDataError, "a tree that holds nothing is a blocker with no yield");
  assert.throws(() => validateResourceBalance({ stone: raw.stone, gold: raw.gold }), GameDataError,
    "every authored tree needs this number, so it is required");

  // A wood *deposit* is authoring nonsense, and both doors say so rather than
  // letting an undefined capacity through: the level adapter names the marker,
  // and the node system refuses to build one.
  assert.throws(() => new ResourceNodeSystem(resources, [
    { id: "bad-wood", resourceId: "wood", kind: "safe", x: 0, z: 0 },
  ]), /not deposited but grown/);
});

check("Faz 6 assigns all four resources to distinct core-match decisions", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const units = validateUnitBalance(
    JSON.parse(readFileSync("public/game-data/balance/units.json", "utf8")) as unknown,
  );
  const ages = validateAgeBalance(
    JSON.parse(readFileSync("public/game-data/balance/ages.json", "utf8")) as unknown,
  );
  // The claim is that each of the four resources buys something the others do
  // not — that is the §6 design and it has to survive retuning. The amounts are
  // balance data and are deliberately *not* pinned here: an exact figure turns
  // every legitimate pass over the numbers into a red build, which is how a test
  // teaches people to edit the test instead of thinking about the change.
  assert.ok((units.worker_placeholder?.cost.food ?? 0) > 0, "food pays for worker growth");
  // Wood buys soldiers — but not necessarily *this* soldier. Naming one unit id
  // made a legitimate tuning pass (`797f84f0` dropped the Guard's wood to 0,
  // leaving the Archer at 10 and the Topçu at 40) fail a check whose actual claim
  // was still true, and a red build there teaches people to edit the test rather
  // than think about the change. The contract is that the military roster as a
  // whole is bought partly with wood; which unit carries it is balance.
  assert.ok(
    Object.entries(units).some(([, stats]) => stats.role !== "worker" && (stats.cost.wood ?? 0) > 0),
    "wood contributes to military production",
  );
  assert.ok((buildings.house?.cost.wood ?? 0) > 0, "wood pays for settlement construction");
  assert.ok(
    (ages.town.levelUpgrades[0]?.cost.stone ?? 0) > 0,
    "stone pays for Town-era centre level upgrades",
  );
  assert.ok((ages.town.cost.gold ?? 0) > 0, "gold is a mandatory Town transition resource");
  // All four, and nothing optional about any of them: the Town transition is the
  // one gate the whole economy has to clear together.
  for (const resourceId of ["food", "wood", "stone", "gold"] as const) {
    assert.ok((ages.town.cost[resourceId] ?? 0) > 0, `the Town transition must charge ${resourceId}`);
  }
});

/**
 * The shipped catalog, validated against the shipped balance tables — the same
 * pair the runtime boots from. Every presentation assertion below reads it rather
 * than a fixture, so a mapping removed from the data fails a test.
 */
function shippedRtsContentCatalog(): RtsContentCatalog {
  return validateRtsContentCatalog(
    JSON.parse(readFileSync("public/game-data/content/rts-content.json", "utf8")) as unknown,
    {
      unitBalance: validateUnitBalance(
        JSON.parse(readFileSync("public/game-data/balance/units.json", "utf8")) as unknown,
      ),
      buildingBalance: validateBuildingBalance(
        JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
      ),
      animalBalance: validateAnimalBalance(
        JSON.parse(readFileSync("public/game-data/balance/animals.json", "utf8")) as unknown,
      ),
    },
  );
}

check("Actor presentation Faz 5: the catalog resolves art by age family and in-age level", () => {
  const catalog = shippedRtsContentCatalog();
  const actor = (name: string) => `assets/ThreeAges/Actors/Buildings/${name}.actor.json`;

  // Aged buildings take the art family from the owner's age and the variant from
  // the in-age level — the two axes the legacy path used to encode in a filename.
  assert.equal(rtsBuildingActorRef(catalog, "command_center", "completed", 1, "settlement"), actor("BP_RTS_CommandCenter_FirstAge_T1"));
  assert.equal(rtsBuildingActorRef(catalog, "command_center", "completed", 1, "town"), actor("BP_RTS_CommandCenter_SecondAge_T1"));
  assert.equal(rtsBuildingActorRef(catalog, "house", "completed", 2, "settlement"), actor("BP_RTS_House_FirstAge_T2"));
  assert.equal(rtsBuildingActorRef(catalog, "depot", "completed", 3, "settlement"), actor("BP_RTS_Depot_FirstAge_T3"));
  assert.equal(rtsBuildingActorRef(catalog, "barracks", "completed", 3, "town"), actor("BP_RTS_Barracks_SecondAge_T3"));
  assert.equal(rtsBuildingActorRef(catalog, "farm", "completed", 2, "town"), actor("BP_RTS_Farm_SecondAge_T2"));

  // The resource camps ship one model each, so age and level resolve to the same
  // Actor rather than to nothing.
  assert.equal(rtsBuildingActorRef(catalog, "quarry", "completed", 3, "town"), actor("BP_RTS_Quarry"));
  assert.equal(rtsBuildingActorRef(catalog, "lumber_camp", "completed", 1, "settlement"), actor("BP_RTS_LumberCamp"));
  assert.equal(rtsBuildingActorRef(catalog, "gold_mine", "construction", 2, "town"), actor("BP_RTS_GoldMine"));

  // Unlike the legacy table, a level outside the ladder is not clamped to the
  // nearest model: it resolves to nothing, and the caller shows the stand-in.
  // Clamping is how a level the game cannot reach used to look supported.
  assert.equal(rtsBuildingActorRef(catalog, "barracks", "completed", 0, "settlement"), null);
  assert.equal(rtsBuildingActorRef(catalog, "barracks", "completed", 9, "settlement"), null);
  assert.equal(rtsBuildingActorRef(catalog, "nonexistent", "completed", 1, "settlement"), null);
});

check("Actor presentation: a building's owner variant wins, and its absence falls back", () => {
  const catalog = shippedRtsContentCatalog();
  const actor = (name: string) => `assets/ThreeAges/Actors/Buildings/${name}.actor.json`;

  // The Barracks flies the owner's colours, so the two armies resolve to
  // different Actors at the age the variant is authored for.
  for (const level of [1, 2, 3]) {
    assert.equal(
      rtsBuildingActorRef(catalog, "barracks", "completed", level, "settlement", "player"),
      actor(`BP_RTS_Barracks_FirstAge_T${level}`),
    );
    assert.equal(
      rtsBuildingActorRef(catalog, "barracks", "completed", level, "settlement", "enemy"),
      actor(`BP_RTS_Enemy_Barracks_FirstAge_T${level}`),
    );
  }

  // Only the settlement set is authored per owner. Town has to fall back to the
  // shared art rather than resolve to nothing — an unauthored age is the normal
  // state of this table, not a gap.
  assert.equal(
    rtsBuildingActorRef(catalog, "barracks", "completed", 2, "town", "enemy"),
    actor("BP_RTS_Barracks_SecondAge_T2"),
  );

  // A building both sides share resolves identically for both, which is what
  // keeps the override opt-in instead of something every building must author.
  assert.equal(
    rtsBuildingActorRef(catalog, "house", "completed", 2, "settlement", "enemy"),
    rtsBuildingActorRef(catalog, "house", "completed", 2, "settlement", "player"),
  );

  // The ladder decides the scale each rung is fitted to, so it has to narrow by
  // owner exactly as the single lookup does. A ladder that leaked the shared
  // models here would size the enemy's Barracks against art it never draws.
  const enemyLadder = rtsBuildingActorRefLadder(catalog, "barracks", "completed", "settlement", "enemy");
  const playerLadder = rtsBuildingActorRefLadder(catalog, "barracks", "completed", "settlement", "player");
  assert.deepEqual(
    [...enemyLadder].sort(),
    [1, 2, 3].map((level) => actor(`BP_RTS_Enemy_Barracks_FirstAge_T${level}`)).sort(),
  );
  assert.deepEqual(
    [...playerLadder].sort(),
    [1, 2, 3].map((level) => actor(`BP_RTS_Barracks_FirstAge_T${level}`)).sort(),
  );
  // Same rung count either way: the override replaces models, never the ladder's
  // shape, so levelling up stays an increase in size on both sides.
  assert.equal(enemyLadder.length, playerLadder.length);

  // A filename beginning with Enemy_ is an AI-only flag variant. No such
  // second-age L1 file exists for the WatchTower, so both owners share it;
  // L2 and L3 select the explicit enemy models.
  assert.equal(
    rtsBuildingActorRef(catalog, "outpost", "completed", 1, "settlement", "enemy"),
    actor("BP_RTS_Enemy_Outpost_FirstAge_T1"),
  );
  assert.equal(
    rtsBuildingActorRef(catalog, "outpost", "completed", 1, "town", "enemy"),
    actor("BP_RTS_Outpost_SecondAge_T1"),
  );
  for (const level of [2, 3]) {
    assert.equal(
      rtsBuildingActorRef(catalog, "outpost", "completed", level, "town", "enemy"),
      actor(`BP_RTS_Enemy_Outpost_SecondAge_T${level}`),
    );
  }

  // Owner variants are separate files. Left out of the preflight set they would
  // load "successfully" and fail when the first enemy Barracks is drawn.
  const refs = rtsContentCatalogRefs(catalog);
  for (const level of [1, 2, 3]) {
    assert.ok(
      refs.includes(actor(`BP_RTS_Enemy_Barracks_FirstAge_T${level}`)),
      `enemy Barracks T${level} joins the preflight load set`,
    );
  }
});

check("Faz M1 the Market is buildable and every balance building has art wired", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const market = buildings["market"];
  assert.ok(market, "the market building exists in balance data");
  assert.ok(market.cost.wood && market.cost.wood > 0, "the market is bought with wood the opening actually has");
  // The trade tuning rides on the building entry so M2's panel has real data to
  // read; the validator already refused it if the no-arbitrage rule were broken.
  assert.ok((market.market?.lotSize ?? 0) > 0, "a trade moves a real quantity");
  assert.deepEqual(Object.keys(market.market?.basePrice ?? {}).sort(), ["food", "stone", "wood"]);
  // Both age families and all three levels resolve — the art pack ships all six.
  const catalog = shippedRtsContentCatalog();
  assert.equal(
    rtsBuildingActorRef(catalog, "market", "completed", 1, "settlement"),
    "assets/ThreeAges/Actors/Buildings/BP_RTS_Market_FirstAge_T1.actor.json",
  );
  assert.equal(
    rtsBuildingActorRef(catalog, "market", "completed", 3, "town"),
    "assets/ThreeAges/Actors/Buildings/BP_RTS_Market_SecondAge_T3.actor.json",
  );
  // The invariant that would have caught a forgotten mapping: a building the data
  // can place but the catalog does not know now renders as the explicit stand-in,
  // which is a bug report rather than a building that merely looks wrong.
  for (const id of Object.keys(buildings)) {
    assert.ok(
      rtsBuildingActorRef(catalog, id, "completed", 1, "settlement"),
      `building "${id}" has no Actor mapping`,
    );
  }
});

/**
 * Assetization Faz A baseline (docs/planned/THREEAGES_RTS_CONTENT_ASSETIZATION_PLAN.md).
 *
 * Faz A changes no behaviour; its job is to pin the seams the later phases move
 * so a migration cannot land silently. Each assertion below records *where the
 * authority lives today*, and is expected to be rewritten — not deleted — by the
 * phase named in its comment. The flag is the gate all of that hangs from.
 */
check("Actor presentation Faz 5: the contentAssets flag is gone, and an old URL still boots", () => {
  // The flag is removed: the Actor pack is simply how the RTS renders, and there
  // is no legacy art path left for it to switch to.
  assert.equal(isFeatureFlag("contentAssets"), false, "the retired flag is no longer a known id");
  // An old bookmark must still open the game. Unknown ids in `?flags=` are
  // ignored, so the URL boots and the pack loads as it would have anyway.
  assert.deepEqual(
    resolveFeatureFlags({}, "contentAssets"),
    resolveFeatureFlags(),
    "a URL naming the removed flag resolves to the ordinary defaults",
  );
  assert.equal(resolveFeatureFlags({}, "contentAssets,fogOfWar").fogOfWar, true, "flags beside it still apply");

  // A *preset* is the one place it must fail loudly: a checked-in file naming a
  // flag that no longer exists is a stale file, not a runtime nicety.
  assert.throws(
    () => validateGamePreset({ ...readPresetJson("gameplay_proof"), flags: { contentAssets: true } }, "gameplay_proof"),
    GameDataError,
    "a preset naming the removed flag is rejected",
  );

  assert.equal(resolveFeatureFlags().levelAssets, false, "Level gameplay data remains opt-in during Faz D");
  assert.equal(resolveFeatureFlags({}, "levelAssets").levelAssets, true, "?flags=levelAssets opts in");
});

check("Actor presentation Faz 5: the catalog is the only art authority left", () => {
  const catalog = shippedRtsContentCatalog();
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );

  // The code-side art table this used to pin (`rtsBuildingArt`) is deleted. The
  // check it carried survives as the thing that actually matters: every building
  // the data can place resolves art, and it resolves it from the catalog.
  for (const id of Object.keys(buildings)) {
    assert.ok(rtsBuildingActorRef(catalog, id, "completed", 1, "settlement"), `building "${id}" has no Actor`);
  }

  // A source-level guard so the deleted module cannot quietly reappear as a
  // second authority: nothing under src/ may resolve a building mesh by path.
  const visuals = readFileSync("src/game/rts/structures/rtsBuildingVisuals.ts", "utf8");
  assert.ok(!/^import .*rtsBuildingArt/m.test(visuals), "the visual library no longer imports the legacy art table");
  assert.ok(!visuals.includes(".gltf"), "the visual library no longer names model files at all");
  assert.throws(
    () => statSync("src/game/rts/structures/rtsBuildingArt.ts"),
    "the legacy art table is gone from the tree",
  );
});

check("Assetization Faz A: RTS_BLOCKOUT_MAP is still the spatial authority Faz D takes over", () => {
  // Plan §K-05 moves each of these to the Level asset. Pinning the *shape* (not
  // the coordinates, which are tuning) means Faz D's adapter has an explicit
  // before-picture: when the Level supplies these, this test names what moved.
  const map = RTS_BLOCKOUT_MAP;
  assert.ok(map.playerStart && map.enemyStart, "both starts are hard-coded in TypeScript today");
  assert.notDeepEqual(map.playerStart, map.enemyStart, "the two kingdoms do not share a start");
  for (const key of ["resourceNodes", "enemyBaseAnchors", "enemyExpansions", "navigationBlockers"] as const) {
    const entries = map[key];
    assert.ok(Array.isArray(entries) && entries.length > 0, `${key} is authored in rtsMapBlockout.ts`);
  }
  // Duplicate ids are the first thing the Faz D adapter has to reject, so the
  // legacy data has to be clean before it is migrated.
  const nodeIds = map.resourceNodes.map((node) => node.id);
  assert.equal(new Set(nodeIds).size, nodeIds.length, "resource node ids are unique");
});

check("Assetization Faz D: Level marker Actors resolve starts, resources, anchors and spline routes", () => {
  const buildings = validateBuildingBalance(JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown);
  const resources = validateResourceBalance(JSON.parse(readFileSync("public/game-data/balance/resources.json", "utf8")) as unknown);
  const actor = (name: string, variables: unknown[], overrides: Record<string, string | number | boolean | string[]>, position: [number, number, number]) => ({
    index: 0, instance: { classRef: `${name}.actor.json`, position, variableOverrides: overrides },
    def: normalizeActorScriptDef({ name, parentClass: "actor", variables }),
  });
  const starts = [
    actor("BP_RTS_KingdomStart", [{ key: "owner", label: "Owner", type: "select", default: "player" }], { owner: "player" }, [-10, 0, 10]),
    actor("BP_RTS_KingdomStart", [{ key: "owner", label: "Owner", type: "select", default: "player" }], { owner: "enemy" }, [10, 0, -10]),
  ];
  const markerActors = [...starts,
    actor("BP_RTS_ResourceNode", [{ key: "nodeId", label: "Node", type: "text", default: "n" }, { key: "resourceId", label: "Resource", type: "text", default: "stone" }, { key: "kind", label: "Kind", type: "select", default: "safe" }], { nodeId: "stone-a", resourceId: "stone", kind: "safe" }, [2, 0, 3]),
    actor("BP_RTS_BuildAnchor", [
      { key: "owner", label: "Owner", type: "select", default: "enemy" },
      { key: "buildingId", label: "Building", type: "text", default: "farm" },
    ], { buildingId: "farm" }, [4, 0, 5]),
  ];
  const level = adaptRtsLevel(markerActors, [{ id: "route", position: [1, 0, 2], spline: { schema: 1, closed: false, defaultUp: [0, 1, 0], reparamStepsPerSegment: 8, points: [{ id: "a", position: [0, 0, 0], pointType: "linear" }, { id: "b", position: [4, 0, 0], pointType: "linear" }] }, runtime: { tags: ["rts.route:enemy:base:0"] } }], { buildings, resources, animals: shippedAnimalBalance() });
  assert.deepEqual(level.playerStart, { x: -10, z: 10 });
  assert.deepEqual(level.resourceNodes, [{ id: "stone-a", resourceId: "stone", kind: "safe", x: 2, z: 3 }]);
  assert.deepEqual(level.routes.get("rts.route:enemy:base:0"), [{ x: 1, z: 2 }, { x: 5, z: 2 }]);
  assert.throws(() => adaptRtsLevel([starts[0]!], [], { buildings, resources, animals: shippedAnimalBalance() }), RtsLevelError);
});

