check("Faz 7 a group order hands each unit its nearest slot, not its selection index", () => {
  const units = new UnitSystem();
  const navigation = new RtsNavigation();
  // Four units around the command point, one per quadrant. Kare's 2x2 grid has a
  // slot in each quadrant too, so the correct assignment is the one where nobody
  // crosses the middle — which is exactly what index order would break, since
  // these are spawned in the opposite order to the slots. The formation is named
  // rather than left to the default: the point under test is slot *matching*, and
  // it must keep being asserted against a known geometry.
  const northEast = units.spawn("player", 20, 20, RTS_TEST_UNIT_STATS);
  const northWest = units.spawn("player", -20, 20, RTS_TEST_UNIT_STATS);
  const southEast = units.spawn("player", 20, -20, RTS_TEST_UNIT_STATS);
  const southWest = units.spawn("player", -20, -20, RTS_TEST_UNIT_STATS);
  const squad = [northEast, northWest, southEast, southWest];

  const assignments = assignGroupDestinations(squad, new Vector3(0, 0, 0), navigation, [], "square");
  const slot = new Map(assignments.map((a) => [a.unit, a.destination]));
  for (const unit of squad) {
    const destination = slot.get(unit) ?? assert.fail("unit missing a slot");
    assert.ok(
      Math.sign(destination.x) === Math.sign(unit.position.x)
        && Math.sign(destination.z) === Math.sign(unit.position.z),
      "each unit takes the slot on its own side instead of crossing the group",
    );
  }
  assert.ok(
    assignments.every((a) => a.path && a.path.length > 0),
    "every unit gets a route on open ground",
  );
  assert.equal(
    new Set(assignments.map((a) => `${a.destination.x}:${a.destination.z}`)).size,
    4,
    "no two units are sent to the same square",
  );

  // Determinism: the same selection, reordered, is the same set of orders.
  const shuffled = assignGroupDestinations(
    [southWest, northEast, southEast, northWest], new Vector3(0, 0, 0), navigation, [], "square",
  );
  for (const a of shuffled) {
    assert.deepEqual(
      [a.destination.x, a.destination.z],
      [slot.get(a.unit)?.x, slot.get(a.unit)?.z],
      "assignment does not depend on selection order",
    );
  }
});

check("Faz 2: Hat and Kol generate forward-facing, distinct move destinations", () => {
  const target = new Vector3(20, 0, 0);
  const centroid = new Vector3(0, 0, 0);
  const line = rtsFormationWorldSlots("line", 10, 1.6, centroid, target);
  assert.equal(new Set(line.map((slot) => slot.x.toFixed(5))).size, 1, "a line is perpendicular to its movement heading");
  assert.equal(new Set(line.map((slot) => slot.z.toFixed(5))).size, 10, "each line unit gets its own slot");

  const column = rtsFormationWorldSlots("column", 10, 1.6, centroid, target);
  assert.equal(new Set(column.map((slot) => slot.x.toFixed(5))).size, 5, "a ten-unit column has five files along its heading");
  assert.equal(new Set(column.map((slot) => slot.z.toFixed(5))).size, 2, "a ten-unit column stays two units wide");

  const units = new UnitSystem();
  const guards = Array.from({ length: 10 }, (_, index) => units.spawn(
    "player",
    -8 + (index % 5) * 4,
    12 + Math.floor(index / 5) * 3,
    RTS_TEST_UNIT_STATS,
  ));
  const navigation = new RtsNavigation();
  const lineOrders = assignGroupDestinations(guards, new Vector3(0, 0, -12), navigation, [], "line");
  assert.equal(new Set(lineOrders.map((order) => order.destination.z.toFixed(5))).size, 1, "Hat sends the squad to one front");
  assert.equal(new Set(lineOrders.map((order) => order.destination.x.toFixed(5))).size, 10, "Hat does not stack destinations");
  assert.ok(lineOrders.every((order) => order.path !== null), "each line slot is planned through existing navigation");

  const columnOrders = assignGroupDestinations(guards, new Vector3(0, 0, -12), navigation, [], "column");
  assert.equal(new Set(columnOrders.map((order) => order.destination.x.toFixed(5))).size, 2, "Kol keeps two files for ten Guards");
  assert.equal(new Set(columnOrders.map((order) => order.destination.z.toFixed(5))).size, 5, "Kol adds depth rather than widening");
  assert.ok(columnOrders.every((order) => order.path !== null), "each column slot is planned through existing navigation");
});

check("Faz 3: mixed formations keep Guards ahead of Archers and Siege", () => {
  const units = new UnitSystem();
  const guards = Array.from({ length: 10 }, (_, index) => units.spawn(
    "player", -12 + (index % 5) * 3, 10 + Math.floor(index / 5) * 3, RTS_TEST_UNIT_STATS,
  ));
  const archers = Array.from({ length: 10 }, (_, index) => units.spawn(
    "player", -12 + (index % 5) * 3, 16 + Math.floor(index / 5) * 3, RTS_TEST_ARCHER_STATS,
  ));
  const siege = [
    units.spawn("player", -2, 22, RTS_TEST_SIEGE_STATS),
    units.spawn("player", 2, 22, RTS_TEST_SIEGE_STATS),
  ];
  const navigation = new RtsNavigation();
  const orders = assignGroupDestinations([...guards, ...archers, ...siege], new Vector3(0, 0, -20), navigation, [], "line");
  const destinations = new Map(orders.map((order) => [order.unit, order.destination]));
  const meanZ = (group: readonly Unit[]) => group.reduce((sum, unit) => sum + (destinations.get(unit)?.z ?? 0), 0) / group.length;
  const meanX = (group: readonly Unit[]) => group.reduce((sum, unit) => sum + (destinations.get(unit)?.x ?? 0), 0) / group.length;

  // Movement heads north (-Z), so a lower Z is the front rank.
  assert.ok(meanZ(guards) < meanZ(archers), "Guards take the front rank");
  assert.ok(meanZ(archers) < meanZ(siege), "Siege takes the rear rank");
  const centroid = [...guards, ...archers, ...siege].reduce((total, unit) => total.add(unit.position), new Vector3())
    .multiplyScalar(1 / 22);
  const forward = new Vector3(0, 0, -20).sub(centroid).setY(0).normalize();
  const siegeLateralOffset = (meanX(siege) * forward.z) - (meanZ(siege) + 20) * forward.x;
  assert.ok(Math.abs(siegeLateralOffset) < 0.001, "the rear Siege rank remains centred on the formation axis");
  assert.ok(orders.every((order) => order.path !== null), "each role-aware slot uses existing navigation");
});

check("Faz 4: advanced formation geometries stay distinct and deterministic", () => {
  const target = new Vector3(0, 0, -20);
  const centroid = new Vector3(0, 0, 10);
  const wedge = rtsFormationWorldSlots("wedge", 10, 1.6, centroid, target);
  assert.equal(new Set(wedge.map((slot) => slot.z.toFixed(5))).size, 4, "a ten-unit wedge has four readable ranks");
  assert.equal(
    wedge.filter((slot) => slot.z === Math.min(...wedge.map((candidate) => candidate.z))).length,
    1,
    "the wedge has one forward tip",
  );

  const crescent = rtsFormationWorldSlots("crescent", 8, 1.6, centroid, target);
  const wingDepth = Math.min(crescent[0]?.z ?? 0, crescent[crescent.length - 1]?.z ?? 0);
  const centreDepth = Math.max(...crescent.slice(2, -2).map((slot) => slot.z));
  assert.ok(wingDepth < centreDepth, "crescent wings lead its recessed centre toward the target");

  const square = rtsFormationWorldSlots("square", 9, 1.6, centroid, target);
  assert.equal(new Set(square.map((slot) => slot.x.toFixed(5))).size, 3, "a nine-unit square has three files");
  assert.equal(new Set(square.map((slot) => slot.z.toFixed(5))).size, 3, "a nine-unit square has three ranks");

  const loose = rtsFormationWorldSlots("loose", 9, 1.6, centroid, target);
  const nearestDistance = (slots: readonly Vector3[]) => Math.min(...slots.flatMap((slot, index) => slots
    .slice(index + 1)
    .map((other) => Math.hypot(slot.x - other.x, slot.z - other.z))));
  assert.ok(nearestDistance(loose) > nearestDistance(square) * 1.45, "loose spacing is materially wider than square spacing");
  assert.deepEqual(
    rtsFormationWorldSlots("loose", 9, 1.6, centroid, target).map((slot) => slot.toArray()),
    loose.map((slot) => slot.toArray()),
    "loose jitter is deterministic",
  );
});

check("Faz 4: square keeps Siege inside the Guard ring", () => {
  const units = new UnitSystem();
  const guards = Array.from({ length: 10 }, (_, index) => units.spawn(
    "player", -12 + (index % 5) * 3, 10 + Math.floor(index / 5) * 3, RTS_TEST_UNIT_STATS,
  ));
  const archers = Array.from({ length: 10 }, (_, index) => units.spawn(
    "player", -12 + (index % 5) * 3, 16 + Math.floor(index / 5) * 3, RTS_TEST_ARCHER_STATS,
  ));
  const siege = [
    units.spawn("player", -2, 22, RTS_TEST_SIEGE_STATS),
    units.spawn("player", 2, 22, RTS_TEST_SIEGE_STATS),
  ];
  const target = new Vector3(0, 0, -20);
  const orders = assignGroupDestinations([...guards, ...archers, ...siege], target, new RtsNavigation(), [], "square");
  const destinations = new Map(orders.map((order) => [order.unit, order.destination]));
  const radius = (unit: Unit) => {
    const slot = destinations.get(unit) ?? assert.fail("missing formation destination");
    return Math.hypot(slot.x - target.x, slot.z - target.z);
  };
  assert.ok(
    Math.max(...siege.map(radius)) < Math.min(...guards.map(radius)),
    "Siege receives inner square slots before any Guard leaves the outer ring",
  );
  assert.ok(orders.every((order) => order.path !== null), "advanced slots continue through existing navigation");
});

check("Askerî AI v2 §5: one Topçu no longer opens the whole formation's spacing", () => {
  // The bug this pins: spacing used to be `max(navRadius) * 2 + padding` over
  // the *whole* group, so a single wide gun stretched twenty Guards apart. The
  // contract is per-pair — a Guard's neighbours are spaced for Guards, and the
  // gun takes its own room where it actually stands.
  const target = new Vector3(0, 0, -20);
  const navigation = new RtsNavigation();
  const rankGap = (destinations: readonly Vector3[]): number => Math.min(...destinations
    .flatMap((slot, index) => destinations.slice(index + 1)
      .map((other) => Math.hypot(slot.x - other.x, slot.z - other.z))));

  const plainSystem = new UnitSystem();
  const plainGuards = Array.from({ length: 6 }, (_, index) => plainSystem.spawn(
    "player", -6 + index * 2.4, 10, RTS_TEST_UNIT_STATS,
  ));
  const plain = assignGroupDestinations(plainGuards, target, navigation, [], "line");

  const mixedSystem = new UnitSystem();
  const mixedGuards = Array.from({ length: 6 }, (_, index) => mixedSystem.spawn(
    "player", -6 + index * 2.4, 10, RTS_TEST_UNIT_STATS,
  ));
  const gun = mixedSystem.spawn("player", 0, 14, RTS_TEST_SIEGE_STATS);
  const mixed = assignGroupDestinations([...mixedGuards, gun], target, navigation, [], "line");
  const mixedGuardSlots = mixed
    .filter((order) => order.unit.role === "guard")
    .map((order) => order.destination);

  assert.ok(
    Math.abs(rankGap(mixedGuardSlots) - rankGap(plain.map((order) => order.destination))) < 1e-6,
    "the Guard rank keeps the spacing it had before a gun joined the group",
  );

  // And the gun is not simply crammed in: every slot around it clears both
  // bodies. Derived from the units' own radii, so retuning a silhouette moves
  // this bar with it instead of stranding the check.
  const gunSlot = mixed.find((order) => order.unit === gun)?.destination
    ?? assert.fail("the gun received no slot");
  for (const order of mixed) {
    if (order.unit === gun) continue;
    assert.ok(
      Math.hypot(gunSlot.x - order.destination.x, gunSlot.z - order.destination.z)
        >= gun.navRadius + order.unit.navRadius - 1e-6,
      "no slot next to the gun overlaps it",
    );
  }
});

check("Askerî AI v2 §6: Dağınık keeps Topçu behind, and stays scattered", () => {
  const units = new UnitSystem();
  const guards = Array.from({ length: 6 }, (_, index) => units.spawn(
    "player", -6 + index * 2.4, 10, RTS_TEST_UNIT_STATS,
  ));
  const archers = Array.from({ length: 4 }, (_, index) => units.spawn(
    "player", -4 + index * 2.4, 14, RTS_TEST_ARCHER_STATS,
  ));
  const siege = [
    units.spawn("player", -2, 18, RTS_TEST_SIEGE_STATS),
    units.spawn("player", 2, 18, RTS_TEST_SIEGE_STATS),
  ];
  const target = new Vector3(0, 0, -20);
  const squad = [...guards, ...archers, ...siege];
  const loose = assignGroupDestinations(squad, target, new RtsNavigation(), [], "loose");
  const destinations = new Map(loose.map((order) => [order.unit, order.destination]));
  // Movement heads north (-Z), so a lower Z is further forward.
  const meanZ = (group: readonly Unit[]) => group
    .reduce((sum, unit) => sum + (destinations.get(unit)?.z ?? 0), 0) / group.length;
  assert.ok(meanZ(guards) < meanZ(archers), "Dağınık still puts Guards ahead of Archers");
  assert.ok(meanZ(archers) < meanZ(siege), "and it never drops the guns into the front band");

  // The scatter is the whole point of the formation and must survive the bands:
  // Dağınık slots stay further apart than the same squad in Kare.
  const spread = (orders: readonly { destination: Vector3 }[]): number => Math.min(...orders
    .flatMap((order, index) => orders.slice(index + 1)
      .map((other) => Math.hypot(order.destination.x - other.destination.x,
        order.destination.z - other.destination.z))));
  const square = assignGroupDestinations(squad, target, new RtsNavigation(), [], "square");
  assert.ok(spread(loose) > spread(square), "Dağınık is still the loose one");
  assert.deepEqual(
    assignGroupDestinations(squad, target, new RtsNavigation(), [], "loose")
      .map((order) => order.destination.toArray()),
    loose.map((order) => order.destination.toArray()),
    "§17.3: and its jitter is still deterministic",
  );
});

check("Askerî AI v2 §4: Kama is an assault wedge with a support tail", () => {
  const units = new UnitSystem();
  const guards = Array.from({ length: 6 }, (_, index) => units.spawn(
    "player", -6 + index * 2.4, 10, RTS_TEST_UNIT_STATS,
  ));
  const archers = Array.from({ length: 4 }, (_, index) => units.spawn(
    "player", -4 + index * 2.4, 14, RTS_TEST_ARCHER_STATS,
  ));
  const siege = [units.spawn("player", 0, 18, RTS_TEST_SIEGE_STATS)];
  const target = new Vector3(0, 0, -20);
  const orders = assignGroupDestinations(
    [...guards, ...archers, ...siege], target, new RtsNavigation(), [], "wedge",
  );
  const destinations = new Map(orders.map((order) => [order.unit, order.destination]));
  const depth = (unit: Unit): number => destinations.get(unit)?.z ?? 0;

  // The tip charges; the tail shoots over it. Not one twenty-unit triangle whose
  // widest row happens to be made of guns.
  const tip = orders.reduce((best, order) => order.destination.z < best.destination.z ? order : best);
  assert.equal(tip.unit.role, "guard", "the point of the wedge is a Guard");
  assert.ok(
    Math.max(...guards.map(depth)) < Math.min(...archers.map(depth)),
    "every Archer stands behind every Guard",
  );
  assert.ok(
    Math.max(...archers.map(depth)) < Math.min(...siege.map(depth)),
    "and the gun is the tail of the tail",
  );
  // The vanguard is genuinely a wedge, not a line: its guards occupy several ranks.
  assert.ok(
    new Set(guards.map((guard) => depth(guard).toFixed(3))).size > 1,
    "the Guard vanguard keeps the wedge's depth",
  );
  assert.ok(orders.every((order) => order.path !== null), "and the whole shape still routes");
});

check("Faz 5: a blocked formation tightens before it abandons its shape", () => {
  const units = new UnitSystem();
  const navigation = new RtsNavigation();
  navigation.setBlockers(corridorBlockers(5));
  const squad = Array.from({ length: 4 }, (_, index) => units.spawn(
    "player", -3 + index * 2, 8, RTS_TEST_UNIT_STATS,
  ));
  const orders = assignGroupDestinations(squad, new Vector3(0, 0, 0), navigation, [], "line");
  assert.ok(orders.every((order) => order.path !== null), "the narrowed line still reaches the corridor target");
  assert.ok(orders.every((order) => order.fallback === undefined), "80% spacing succeeds before individual fallback is needed");
  assert.ok(
    Math.max(...orders.map((order) => Math.abs(order.destination.x))) < 2,
    `the final line fits inside the five-unit gap instead of keeping its full width: ${JSON.stringify(orders.map((order) => order.destination.toArray()))}`,
  );
});

check("Faz 5: an unreachable formation slot finds nearby legal ground", () => {
  const units = new UnitSystem();
  const navigation = new RtsNavigation();
  navigation.setBlockers([{ min: [-2, -1, -2], max: [2, 4, 2] }]);
  const squad = [
    units.spawn("player", -1, 8, RTS_TEST_UNIT_STATS),
    units.spawn("player", 1, 8, RTS_TEST_UNIT_STATS),
  ];
  const orders = assignGroupDestinations(squad, new Vector3(0, 0, 0), navigation, [], "line");
  assert.ok(orders.every((order) => order.path !== null), "a blocked slot does not cancel the group order");
  assert.ok(orders.every((order) => order.fallback === "nearby"), "each blocked slot searches nearby ground after spacing fallback");
  assert.ok(orders.every((order) => navigation.isWalkable(order.destination.x, order.destination.z)), "nearby fallback stays on legal ground");
});

check("Faz 7 a squad clears a narrow corridor instead of jamming in it", () => {
  const units = new UnitSystem();
  const navigation = new RtsNavigation();
  navigation.setBlockers(corridorBlockers(3));

  // Twelve Guards south of a 3-wide gap, ordered through it. Without separation
  // they overlap into one body; without the congestion escape, the ones that
  // cannot reach their slot grind against the group forever.
  const squad: Unit[] = [];
  for (let i = 0; i < 12; i += 1) {
    squad.push(units.spawn("player", -4 + (i % 4) * 2.5, 8 + Math.floor(i / 4) * 2.5, RTS_TEST_UNIT_STATS));
  }
  for (const { unit, path } of assignGroupDestinations(squad, new Vector3(0, 0, -8), navigation)) {
    assert.ok(path, "the corridor is passable for infantry");
    unit.setMovePath(path ?? []);
  }

  simulateSquad(squad, navigation, 30);
  assert.ok(
    squad.every((unit) => unit.position.z < -4),
    "every Guard is through the gap and on the far side",
  );
  assert.ok(
    squad.every((unit) => unit.pathTarget === null),
    "plan §45: no unit is left holding an order it can never finish",
  );
  // The whole point of separation: they arrive as twelve bodies, not one stack.
  for (const unit of squad) {
    for (const other of squad) {
      if (unit === other) continue;
      const gap = Math.hypot(unit.position.x - other.position.x, unit.position.z - other.position.z);
      assert.ok(gap > unit.navRadius, `units ${unit.id} and ${other.id} are not standing inside each other`);
    }
  }
});

check("Faz 7 two squads meeting head-on in a bridge do not deadlock", () => {
  const units = new UnitSystem();
  const navigation = new RtsNavigation();
  // A bridge is the corridor case with traffic in both directions at once: the
  // plan's acceptance is "köprüde kalıcı sıkışma oluşmuyor".
  navigation.setBlockers(corridorBlockers(4));

  const northbound: Unit[] = [];
  const southbound: Unit[] = [];
  for (let i = 0; i < 6; i += 1) {
    northbound.push(units.spawn("player", -1.5 + (i % 2) * 3, 6 + Math.floor(i / 2) * 2.5, RTS_TEST_UNIT_STATS));
    southbound.push(units.spawn("player", -1.5 + (i % 2) * 3, -6 - Math.floor(i / 2) * 2.5, RTS_TEST_UNIT_STATS));
  }
  for (const { unit, path } of assignGroupDestinations(northbound, new Vector3(0, 0, -10), navigation)) {
    unit.setMovePath(path ?? []);
  }
  for (const { unit, path } of assignGroupDestinations(southbound, new Vector3(0, 0, 10), navigation)) {
    unit.setMovePath(path ?? []);
  }

  const all = [...northbound, ...southbound];
  simulateSquad(all, navigation, 40);
  assert.ok(
    all.every((unit) => unit.pathTarget === null),
    "every crossing ends — in arrival or in a stop, never in a permanent jam",
  );
  assert.ok(
    northbound.filter((unit) => unit.position.z < -1).length >= 4
      && southbound.filter((unit) => unit.position.z > 1).length >= 4,
    "both columns get the bulk of their units across the bridge",
  );
});

check("Faz 7 the wide Topçu crosses a corridor with its escort without being swallowed by it", () => {
  const units = new UnitSystem();
  const navigation = new RtsNavigation();
  navigation.setBlockers(corridorBlockers(4));

  // The Topçu is the largest body the roster fields. A siege line is escorted
  // (§46: siege is weak against units), so the case that matters is the gun
  // inside a crowd of Guards, in a gap, not the gun alone on open ground.
  const gun = units.spawn("player", 0, 8, RTS_TEST_SIEGE_STATS);
  const escort: Unit[] = [];
  for (let i = 0; i < 8; i += 1) {
    escort.push(units.spawn("player", -3 + (i % 4) * 2, 11 + Math.floor(i / 4) * 2, RTS_TEST_UNIT_STATS));
  }
  const squad = [gun, ...escort];
  assert.ok(
    escort.every((guard) => gun.navRadius > guard.navRadius),
    "the siege body is wider than the infantry it travels with",
  );

  for (const { unit, path } of assignGroupDestinations(squad, new Vector3(0, 0, -8), navigation)) {
    assert.ok(path, "the corridor carries the siege line");
    unit.setMovePath(path ?? []);
  }
  simulateSquad(squad, navigation, 40);
  assert.ok(squad.every((unit) => unit.position.z < -4), "the whole squad, gun included, is through");
  assert.ok(squad.every((unit) => unit.pathTarget === null), "and nobody is left grinding on an order");

  // The width has to buy the gun real ground: the crowd keeps its distance from
  // the wide body, which is the one place the roster's radii are expressible.
  for (const guard of escort) {
    const gap = Math.hypot(gun.position.x - guard.position.x, gun.position.z - guard.position.z);
    assert.ok(
      gap > gun.navRadius,
      `Guard ${guard.id} is standing inside the gun (${gap.toFixed(2)} < ${gun.navRadius})`,
    );
  }
});

check("Faz 7 units contesting one spot time out into arrival instead of shoving forever", () => {
  const units = new UnitSystem();
  const navigation = new RtsNavigation();
  const dt = 1 / 30;

  // Six units sent to the exact same point — the shape of every real stall,
  // since a body only ever fails to advance because another body is in the way.
  // Five of them can never stand where they were told to; the timeout is what
  // stops them spending the rest of the match pushing for it.
  const goal = new Vector3(0, 0, 0);
  const crowd: Unit[] = [];
  for (let i = 0; i < 6; i += 1) {
    const unit = units.spawn("player", -6 + i * 2.4, 9, RTS_TEST_UNIT_STATS);
    unit.replanPath([goal.clone()]);
    crowd.push(unit);
  }
  simulateSquad(crowd, navigation, 20);
  assert.ok(
    crowd.every((unit) => unit.pathTarget === null),
    "plan §45: every contested order ends rather than grinding forever",
  );
  assert.ok(
    crowd.every((unit) => congestionSeconds(unit) === 0),
    "and the stall bookkeeping is released with it",
  );
  // Ending the order must not mean abandoning it far away: the point of the
  // crowd-arrival rule is that they pile up *on* the objective.
  assert.ok(
    crowd.every((unit) => Math.hypot(unit.position.x, unit.position.z) < 4),
    "the crowd settles on the objective it was given",
  );

  // Progress is never mistaken for congestion: an unobstructed walk keeps its
  // order all the way to the end.
  const free = units.spawn("player", 0, -20, RTS_TEST_UNIT_STATS);
  const route = navigation.plan(free.position, new Vector3(0, 0, -50)) ?? assert.fail("route missing");
  free.setMovePath(route);
  // Stopped well short of arrival: this asserts the order survives the walk, so
  // it must still be under way when the assertion runs.
  for (let i = 0; i < 30 * 2; i += 1) updateUnitMovement([free], dt, { navigation });
  assert.ok(free.position.z < -25 && free.pathTarget, "a unit making headway is still under orders");
  assert.equal(congestionSeconds(free), 0, "and never accrues a stall");
});

check("Faz 7 a unit the crowd gives no ground gives its order up instead of grinding on it", () => {
  const units = new UnitSystem();
  const navigation = new RtsNavigation();
  const dt = 1 / 30;

  // §46's jam reduced to one body. A unit's step is never refused — nothing in
  // movement can refuse it — so the only thing that ever holds a unit still is
  // `unitSeparation` handing the ground back to the crowd afterwards. This pins
  // the unit to model exactly that, because the emergent version (a squad packed
  // against the Merkez footprint) jams roughly one run in five and cannot be
  // asserted on. The tests above never reach this code at all: they pass because
  // their units genuinely arrive, so the escape hatch below is only covered here.
  const unit = units.spawn("player", 0, 0, RTS_TEST_UNIT_STATS);
  const route = navigation.plan(unit.position, new Vector3(0, 0, -30)) ?? assert.fail("route missing");
  unit.setMovePath(route);

  // Open ground always has a route, so the navigator answers every time it is
  // asked: the re-plan budget is the only thing that can end this order.
  const goals: Vector3[] = [];
  const spy: RtsNavigation = Object.assign(Object.create(navigation) as RtsNavigation, {
    plan: (start: Vector3, goal: Vector3) => {
      goals.push(goal.clone());
      return navigation.plan(start, goal);
    },
  });

  for (let i = 0; i < 30 * 20; i += 1) {
    const pinnedX = unit.position.x;
    const pinnedZ = unit.position.z;
    updateUnitMovement([unit], dt, { navigation: spy });
    unit.position.x = pinnedX;
    unit.position.z = pinnedZ;
  }

  const plans = goals.length / 2;
  assert.ok(
    goals.some((goal) => Math.hypot(goal.x, goal.z + 30) > 0.5),
    "the recovery first probes a local retreat or side-step",
  );
  assert.ok(goals.length <= 4, `recovery path queries stay bounded (${goals.length})`);

  assert.equal(unit.pathTarget, null, "plan §45: a stall ends in a stop; no order outlives the jam");
  assert.ok(plans > 0, "the stall was noticed at all — progress is measured per frame, not per step");
  assert.ok(plans <= 2, `and the re-plan budget is spent rather than refunded (${plans} re-plans)`);
});

check("Faz 7 overlapping movers briefly phase through each other, then keep their route", () => {
  const units = new UnitSystem();
  const navigation = new RtsNavigation();
  const first = units.spawn("player", 0, 0, RTS_TEST_UNIT_STATS);
  const second = units.spawn("player", 0, 0.1, RTS_TEST_UNIT_STATS);
  const goal = new Vector3(0, 0, -30);
  const firstPath = navigation.plan(first.position, goal) ?? assert.fail("first route missing");
  const secondPath = navigation.plan(second.position, goal) ?? assert.fail("second route missing");
  first.setMovePath(firstPath);
  second.setMovePath(secondPath);

  // Pin both bodies together long enough to reproduce a crowd deadlock. The
  // recovery must trigger from real overlap, not from one isolated stalled unit.
  const dt = 1 / 30;
  for (let i = 0; i < 60; i += 1) {
    const firstPosition = first.position.clone();
    const secondPosition = second.position.clone();
    updateUnitMovement([first, second], dt, { navigation });
    first.position.copy(firstPosition);
    second.position.copy(secondPosition);
  }
  assert.equal(first.isCollisionRecovering, true, "the first jammed mover gets a bounded recovery window");
  assert.equal(second.isCollisionRecovering, true, "the overlapping partner is recovered too");

  const firstPosition = first.position.clone();
  const secondPosition = second.position.clone();
  updateUnitSeparation([first, second], dt, { navigation });
  assert.deepEqual(first.position.toArray(), firstPosition.toArray(), "recovery disables only crowd separation");
  assert.deepEqual(second.position.toArray(), secondPosition.toArray(), "the partner is not pushed during recovery");

  for (let i = 0; i < 30; i += 1) updateUnitMovement([first, second], dt, { navigation });
  assert.equal(first.isCollisionRecovering, false, "the recovery window is short-lived");
  assert.equal(second.isCollisionRecovering, false, "the partner also returns to normal collision");
  assert.ok(first.pathTarget && second.pathTarget, "both units resume routes instead of losing their targets");
});

check("Faz 7 a group order onto unreachable ground stops the unit instead of walking it into rock", () => {
  const units = new UnitSystem();
  const navigation = new RtsNavigation();
  // Movement follows waypoints and does not collide with terrain — planning is
  // the only thing keeping a unit out of a rock. So an unroutable slot has to
  // surface as "no path" at order time, not as a walk through the geometry.
  navigation.setBlockers([{ min: [-6, -1, -16], max: [6, 4, -4] }]);
  const unit = units.spawn("player", 0, 8, RTS_TEST_UNIT_STATS);
  unit.setMovePath([new Vector3(0, 0, 4)]);

  const orders = assignGroupDestinations([unit], new Vector3(0, 0, -10), navigation);
  assert.equal(orders[0]?.path, null, "no route exists into the rock");
  for (const order of orders) {
    if (order.path) order.unit.setMovePath(order.path);
    else order.unit.stop();
  }
  assert.equal(unit.pathTarget, null, "the refused order clears the unit's previous one");
  simulateSquad([unit], navigation, 5);
  assert.ok(unit.position.z > 0, "and the unit never sets off into the rock");
});

check("Faz 7 a 40-unit engagement stays within frame budget", () => {
  const units = new UnitSystem();
  const navigation = new RtsNavigation();
  const all: Unit[] = [];
  // Plan §46: "25–40 birimlik çatışma kabul edilebilir performansta." Two 20-unit
  // armies walk into each other — the movement, separation and engagement passes
  // together, which is the per-frame simulation cost of a real slice fight.
  for (let i = 0; i < 20; i += 1) {
    all.push(units.spawn("player", -10 + (i % 5) * 2, 12 + Math.floor(i / 5) * 2, RTS_TEST_UNIT_STATS));
    all.push(units.spawn("enemy", -10 + (i % 5) * 2, -12 - Math.floor(i / 5) * 2, RTS_TEST_UNIT_STATS));
  }
  for (const { unit, path } of assignGroupDestinations(all.filter((u) => u.owner === "player"), new Vector3(0, 0, -12), navigation)) {
    unit.setAttackMovePath(path ?? [], new Vector3(0, 0, -12));
  }
  for (const { unit, path } of assignGroupDestinations(all.filter((u) => u.owner === "enemy"), new Vector3(0, 0, 12), navigation)) {
    unit.setAttackMovePath(path ?? [], new Vector3(0, 0, 12));
  }

  const dt = 1 / 30;
  const frames = 300;
  const started = performance.now();
  for (let i = 0; i < frames; i += 1) {
    updateUnitEngagement(units.all(), { navigation, targets: units.all() });
    updateUnitMovement(units.all(), dt, { navigation });
    updateUnitSeparation(units.all(), dt, { navigation });
    updateUnitCombat(units.all(), dt);
  }
  const msPerFrame = (performance.now() - started) / frames;
  // A generous ceiling on purpose: this is a floor-level regression guard against
  // an O(n^2) pass creeping back in, not a rendering benchmark. Simulation for 40
  // units has no business approaching a 16ms budget on its own.
  assert.ok(
    msPerFrame < 4,
    `40-unit simulation costs ${msPerFrame.toFixed(2)}ms/frame, which no longer leaves room to render`,
  );
  assert.ok(
    units.all().some((unit) => unit.health.current < unit.health.max),
    "the armies actually met — an empty field would make the timing meaningless",
  );
});

check("Faz 7 ranged attacks fire an authored Arrow while melee does not", () => {
  const units = new UnitSystem();
  const projectiles = new ProjectileSystem();
  const arrowModel = new Mesh(new BoxGeometry(0.03, 0.03, 0.75));
  projectiles.setArrowModel(arrowModel);
  const archer = units.spawn("player", 0, 0, RTS_TEST_ARCHER_STATS);
  const guard = units.spawn("player", 0, 0, RTS_TEST_UNIT_STATS);
  const archerTarget = units.spawn("enemy", 5, 0, RTS_TEST_UNIT_STATS);
  const guardTarget = units.spawn("enemy", 1, 0, RTS_TEST_UNIT_STATS);
  archer.setAttackTarget(archerTarget);
  guard.setAttackTarget(guardTarget);

  const ranged: boolean[] = [];
  updateUnitCombat([archer, guard], 0, (hit) => {
    ranged.push(hit.ranged);
    if (hit.ranged) {
      projectiles.spawn(
        hit.attacker.owner,
        hit.attacker.position,
        hit.target.position,
        undefined,
        0,
        hit.attacker.stats.projectileSpeed,
      );
    }
  });
  assert.deepEqual(ranged, [true, false], "only the Archer's hit asks for a tracer");
  assert.equal(projectiles.root.children.length, 1, "the ranged attack puts one authored Arrow in flight");
  const arrowFlight = projectiles.root.children[0] ?? assert.fail("the authored Arrow is present in flight");
  const authoredArrow = arrowFlight.children.find((child) => child.name !== "rts-arrow-wind-trail")
    ?? assert.fail("the authored Arrow mesh remains in its supplied forward axis");
  assert.equal(authoredArrow.rotation.y, 0, "the projectile does not reverse the supplied Arrow mesh");
  const windTrail = arrowFlight.getObjectByName("rts-arrow-wind-trail") ?? assert.fail("the Arrow owns its wind trail");
  assert.equal(windTrail.parent, arrowFlight, "the wind is a local Arrow child, not a separate world VFX");
  assert.ok(Number.isFinite(windTrail.position.z), "the gust root keeps an author-tunable local tail offset");
  assert.equal(windTrail.children.length, 3, "the tail is three fine wisps, not one solid cone over the shaft");
  const initialFlutter = windTrail.rotation.clone();
  projectiles.update(0.05);
  assert.equal(windTrail.parent, arrowFlight, "the gust stays parented while the Arrow flies");
  assert.notDeepEqual(windTrail.rotation.toArray(), initialFlutter.toArray(), "the local tail flutters while the Arrow flies");

  // Damage already landed at fire time, so an Arrow expiring changes nothing.
  const health = archerTarget.health.current;
  for (let i = 0; i < 60; i += 1) projectiles.update(1 / 60);
  assert.equal(projectiles.root.children.length, 0, "Arrows retire once they arrive");
  assert.equal(archerTarget.health.current, health);
  projectiles.dispose();
});

check("a shot with a flight time hurts nothing until it arrives", () => {
  const units = new UnitSystem();
  const impacts = new PendingImpactQueue();
  const gun = units.spawn("player", 0, 0, RTS_TEST_ARCHER_STATS);
  const target = units.spawn("enemy", 5, 0, RTS_TEST_UNIT_STATS);
  gun.setAttackTarget(target);
  // Derived from the same table the shot will use, so this holds at any tuning.
  const expected = gun.attack.damageAgainst(target);
  const travel = 0.8;

  const applied: number[] = [];
  const record = (hit: { change: { applied: number } }): void => void applied.push(hit.change.applied);
  updateUnitCombat([gun], 0, record, { onShot: () => travel, impacts });
  assert.equal(applied.length, 0, "firing is not hitting");
  assert.equal(target.health.current, target.health.max, "the target is untouched while the shot flies");
  assert.equal(impacts.size, 1, "the blow is parked on the shot in flight");

  impacts.update(travel * 0.5, record);
  assert.equal(target.health.current, target.health.max, "half way is still no damage");
  assert.equal(impacts.size, 1);

  impacts.update(travel * 0.5, record);
  assert.deepEqual(applied, [expected], "the blow lands once, on arrival");
  assert.equal(target.health.current, target.health.max - expected);
  assert.equal(impacts.size, 0, "an arrived shot leaves the queue");
});

check("a shell whose target dies mid-flight lands on rubble", () => {
  const units = new UnitSystem();
  const impacts = new PendingImpactQueue();
  const gun = units.spawn("player", 0, 0, RTS_TEST_ARCHER_STATS);
  const target = units.spawn("enemy", 5, 0, RTS_TEST_UNIT_STATS);
  gun.setAttackTarget(target);
  updateUnitCombat([gun], 0, undefined, { onShot: () => 0.5, impacts });
  assert.equal(impacts.size, 1);

  target.health.damage(target.health.max);
  let hits = 0;
  impacts.update(1, () => { hits += 1; });
  assert.equal(hits, 0, "a dead target is not hit again by a shot already in the air");
  assert.equal(impacts.size, 0);
});

check("the artillery's damage waits exactly as long as its ball is in the air", () => {
  const cannonballs = new CannonballSystem();
  // The queue schedules on whatever `spawn` reports, so that number has to be a
  // real, readable flight — a zero would put the hit back at the muzzle.
  const flight = cannonballs.spawn(new Vector3(0, 0, 0), new Vector3(12, 0, 0));
  assert.ok(flight > 0, `a fired shell must report a flight time, got ${flight}`);
  assert.equal(cannonballs.root.children.length, 1, "the ball is in the scene while it flies");

  // Advanced on the simulation delta in RtsApp: the same seconds the blow waits.
  for (let i = 0; i < Math.ceil((flight + 1) * 60); i += 1) cannonballs.update(1 / 60);
  assert.equal(cannonballs.root.children.length, 0, "the ball retires after impact");

  // A shot across the field waits at least as long as one at the gun's feet —
  // the delay tracks the distance rather than being one fixed pause.
  const near = cannonballs.spawn(new Vector3(0, 0, 0), new Vector3(4, 0, 0));
  const far = cannonballs.spawn(new Vector3(0, 0, 0), new Vector3(40, 0, 0));
  assert.ok(far >= near, `a longer shot cannot land sooner (${far} < ${near})`);
  cannonballs.dispose();
});

check("a shell reports its authored burst once, where and when it lands", () => {
  const cannonballs = new CannonballSystem();
  const landings: { effectId: string | null; x: number; z: number }[] = [];
  cannonballs.setImpactHandler((effectId, position) => {
    landings.push({ effectId, x: position.x, z: position.z });
  });

  const target = new Vector3(12, 0, -6);
  const flight = cannonballs.spawn(new Vector3(0, 0, 0), target, "rts-fx-explosion");
  // The whole point of holding the burst back: an explosion that fired at the
  // muzzle would go off on a wall the shell has not reached yet.
  for (let i = 0; i < Math.floor(flight * 60) - 2; i += 1) cannonballs.update(1 / 60);
  assert.deepEqual(landings, [], "nothing bursts while the shell is still in the air");

  for (let i = 0; i < 8; i += 1) cannonballs.update(1 / 60);
  assert.equal(landings.length, 1, "one shell reports exactly one landing");
  assert.equal(landings[0]!.effectId, "rts-fx-explosion", "the burst is the one the gun's data named");
  // At the impact point the caller aimed, not at the gun and not at the origin.
  assert.equal(landings[0]!.x, target.x);
  assert.equal(landings[0]!.z, target.z);

  // Pooling is the trap here: a recycled shot that kept the last gun's id would
  // burst as an explosion for a weapon whose data names none.
  cannonballs.spawn(new Vector3(0, 0, 0), new Vector3(6, 0, 0));
  for (let i = 0; i < 240; i += 1) cannonballs.update(1 / 60);
  assert.equal(landings.length, 2);
  assert.equal(landings[1]!.effectId, null, "a gun with no authored burst lands quietly");

  // A restart clears the field; shells wiped off it never landed on anything.
  cannonballs.spawn(new Vector3(0, 0, 0), new Vector3(20, 0, 0), "rts-fx-explosion");
  cannonballs.clear();
  for (let i = 0; i < 240; i += 1) cannonballs.update(1 / 60);
  assert.equal(landings.length, 2, "a cleared shell never reports a landing");
  cannonballs.dispose();
});

check("RTS grid navigation routes a unit around a static blocker", () => {
  const navigation = new RtsNavigation();
  navigation.setBlockers([{ min: [-1, -1, -1], max: [1, 3, 1] }]);
  const path = navigation.plan(new Vector3(-5, 0, 0), new Vector3(5, 0, 0));
  assert.ok(path && path.length > 2, "path detours instead of crossing the blocker");
  assert.ok(path.some((point) => Math.abs(point.z) > 1.5), "path leaves the blocked corridor");

  const units = new UnitSystem();
  const walker = units.spawn("player", -5, 0, RTS_TEST_UNIT_STATS);
  walker.setMovePath(path);
  for (let i = 0; i < 300; i += 1) updateUnitMovement([walker], 1 / 60);
  assert.ok(walker.position.distanceTo(new Vector3(5, 0, 0)) < 0.16, "follows every waypoint to goal");
  assert.equal(walker.pathTarget, null, "clears the path after reaching the goal");
});

check("RTS blockout draws no map-edge wall, and no ridge box once a Level owns the blockers", () => {
  const names = (group: { traverse(fn: (child: { name: string }) => void): void }): string[] => {
    const found: string[] = [];
    group.traverse((child) => { if (child.name) found.push(child.name); });
    return found;
  };
  // The world edge is an invisible limit: `RtsNavigation` bounds hold it, and the
  // authored landscape (slopes, cliffs, treelines) is what the player reads. Any
  // box geometry re-appearing on the rim would sit *inside* that art.
  assert.ok(
    !names(createRtsMapBlockout()).some((name) => name.includes("boundary")),
    "the blockout builds no border band geometry in either mode",
  );
  // The ridge placeholder stands for `RTS_BLOCKOUT_MAP.navigationBlockers`. A
  // Level replaces those wholesale (`resolveRtsSpatialLayout`), so drawing it
  // there would be a wall with nothing behind it.
  assert.ok(
    names(createRtsMapBlockout(RTS_BLOCKOUT_MAP, { includeRidge: true })).includes("rts-central-ridge"),
    "the legacy blockout still shows its own ridge blocker",
  );
  assert.ok(
    !names(createRtsMapBlockout(RTS_BLOCKOUT_MAP, { includeRidge: false })).includes("rts-central-ridge"),
    "a Level-driven match gets no legacy ridge box",
  );
});

check("RTS Faz 2 blockout keeps both flanks reachable around the central ridge", () => {
  assert.deepEqual(RTS_BLOCKOUT_MAP.playerStart, { x: -38, z: 38 }, "player starts in the south-west corner");
  assert.deepEqual(RTS_BLOCKOUT_MAP.enemyStart, { x: 38, z: -38 }, "enemy starts in the north-east corner");
  assert.equal(RTS_WORLD_HALF_EXTENT, 70, "the playable field is larger than the original 120-unit square");
  assert.equal(COMMAND_CENTER_CONTROL_RADIUS, 28, "starting territory leaves a larger construction ring");
  const navigation = new RtsNavigation();
  navigation.setBlockers(RTS_BLOCKOUT_MAP.navigationBlockers);
  const start = new Vector3(RTS_BLOCKOUT_MAP.playerStart.x, 0, RTS_BLOCKOUT_MAP.playerStart.z);
  const goal = new Vector3(RTS_BLOCKOUT_MAP.enemyStart.x, 0, RTS_BLOCKOUT_MAP.enemyStart.z);
  const path = navigation.plan(start, goal);
  assert.ok(path && path.length > 2, "the opposing start areas remain connected");
  const detours = path.filter((point) => Math.abs(point.x) > 12.5);
  assert.ok(detours.length > 0, "the route uses an open flank instead of crossing the ridge");
  assert.ok(
    RTS_BLOCKOUT_MAP.externalResource.x > 12 && RTS_BLOCKOUT_MAP.externalResource.z > 4,
    "the external-resource landmark is outside the player start and central ridge",
  );
});

check("RTS attack pursuit routes around the central ridge instead of crossing it", () => {
  const navigation = new RtsNavigation();
  navigation.setBlockers(RTS_BLOCKOUT_MAP.navigationBlockers);
  const units = new UnitSystem();
  const attacker = units.spawn("enemy", RTS_BLOCKOUT_MAP.enemyStart.x, RTS_BLOCKOUT_MAP.enemyStart.z, RTS_TEST_UNIT_STATS);
  const target = units.spawn("player", RTS_BLOCKOUT_MAP.playerStart.x, RTS_BLOCKOUT_MAP.playerStart.z, RTS_TEST_UNIT_STATS);
  issueAttackOrder(attacker, target, navigation);

  assert.ok(attacker.pathWaypointCount > 2, "attack order receives a flank route");
  for (let frame = 0; frame < 2_400; frame += 1) {
    updateUnitMovement([attacker], 1 / 60);
    const insideRidge = attacker.position.x > -12.5 && attacker.position.x < 12.5
      && attacker.position.z > -4.5 && attacker.position.z < 4.5;
    assert.equal(insideRidge, false, "attack pursuit never enters the central ridge");
  }
  assert.ok(attacker.position.distanceTo(target.position) <= attacker.attack.range + 0.2,
    "attacker reaches melee range through a flank");
});

check("RTS placement snap rejects occupied footprints and refreshes navigation blockers", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const house = buildings.house ?? assert.fail("house definition missing");
  assert.equal(RTS_PLACEMENT_GRID_SIZE, 2);
  const open = validateBuildingPlacement(house, 20.8, 12.9, RTS_BLOCKOUT_MAP.navigationBlockers);
  assert.deepEqual({ x: open.x, z: open.z, valid: open.valid, reason: open.reason }, {
    x: 20,
    z: 12,
    valid: true,
    reason: null,
  });

  const structures = new PlacedStructureSystem();
  const site = structures.place("player", house, open.x, open.z);
  const overlap = validateBuildingPlacement(house, 20, 12, structures.navigationBlockers());
  assert.equal(overlap.valid, false);
  assert.equal(overlap.reason, "blocked");

  const navigation = new RtsNavigation();
  navigation.setBlockers([...RTS_BLOCKOUT_MAP.navigationBlockers, ...structures.navigationBlockers()]);
  const route = navigation.plan(new Vector3(14, 0, 12), new Vector3(28, 0, 12));
  assert.ok(route && route.length > 2, "a new structure forces a detour rather than breaking navigation");
  assert.ok(route.some((point) => Math.abs(point.z - 12) > 2.5), "route leaves the structure footprint");
  assert.equal(site.object.name, "rts-construction-site-player-1");
  assert.equal(structures.cancelLatest("player"), site, "latest unbuilt foundation can be cancelled");
  assert.equal(structures.navigationBlockers().length, 0);
  structures.clear();
});

check("RTS building placement keeps the map's border band clear of footprints", () => {
  // The bug this pins: the blockout dresses the map edge with a border band, and
  // placement used to allow the full world extent — so an expansion authored near
  // the edge built a structure standing *inside* the wall. Relationships only, so
  // widening the band or the clearance keeps the test honest.
  assert.ok(
    RTS_WORLD_BUILD_HALF_EXTENT + RTS_WORLD_BORDER_BAND <= RTS_WORLD_HALF_EXTENT,
    "the buildable rim clears the whole border band",
  );
  assert.ok(RTS_WORLD_BORDER_CLEARANCE > 0, "a building never sits flush against the band");

  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const outpost = buildings.outpost ?? assert.fail("outpost definition missing");
  const half = outpost.footprint.width / 2;
  // Derived from the same constants the runtime uses: the outermost cell whose
  // footprint still fits, and the next one out.
  const grid = RTS_PLACEMENT_GRID_SIZE;
  const lastLegal = Math.floor((RTS_WORLD_BUILD_HALF_EXTENT - half) / grid) * grid;
  assert.equal(validateBuildingPlacement(outpost, lastLegal, 0, []).valid, true,
    "the outermost cell inside the rim is still buildable");
  const overBand = validateBuildingPlacement(outpost, lastLegal + grid, 0, []);
  assert.equal(overBand.valid, false);
  assert.equal(overBand.reason, "outside-map");
  // The rim is square: the same limit holds on Z, and on the negative side.
  assert.equal(validateBuildingPlacement(outpost, 0, -(lastLegal + grid), []).reason, "outside-map");
  // Navigation is deliberately *not* inset — units still reach the true edge.
  assert.ok(RTS_WORLD_BUILD_HALF_EXTENT < RTS_WORLD_HALF_EXTENT,
    "placement is inset from the world the units walk");
});

check("RTS level adapter refuses an authored build site that reaches the border band", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const resources = validateResourceBalance(
    JSON.parse(readFileSync("public/game-data/balance/resources.json", "utf8")) as unknown,
  );
  const animals = shippedAnimalBalance();
  const actor = (name: string, variables: unknown[], overrides: Record<string, string>, position: [number, number, number]) => ({
    index: 0,
    instance: { classRef: `${name}.actor.json`, position, variableOverrides: overrides },
    def: normalizeActorScriptDef({ name, parentClass: "actor", variables }),
  });
  const ownerVar = { key: "owner", label: "Owner", type: "select", default: "player" };
  const starts = [
    actor("BP_RTS_KingdomStart", [ownerVar], { owner: "player" }, [-10, 0, 10]),
    actor("BP_RTS_KingdomStart", [ownerVar], { owner: "enemy" }, [10, 0, -10]),
  ];
  const route = {
    id: "route", position: [0, 0, 0] as [number, number, number],
    spline: {
      schema: 1 as const, closed: false, defaultUp: [0, 1, 0] as [number, number, number],
      reparamStepsPerSegment: 8,
      points: [
        { id: "a", position: [0, 0, 0] as [number, number, number], pointType: "linear" as const },
        { id: "b", position: [4, 0, 0] as [number, number, number], pointType: "linear" as const },
      ],
    },
    runtime: { tags: ["rts.route:enemy:base:0"] },
  };
  const anchorVars = [ownerVar, { key: "buildingId", label: "Building", type: "text", default: "farm" }];
  const farm = buildings.farm ?? assert.fail("farm definition missing");
  const overBand = RTS_WORLD_BUILD_HALF_EXTENT - farm.footprint.width / 2 + 1;
  assert.throws(
    () => adaptRtsLevel(
      [...starts, actor("BP_RTS_BuildAnchor", anchorVars, { owner: "enemy", buildingId: "farm" }, [overBand, 0, 0])],
      [route], { buildings, resources, animals },
    ),
    RtsLevelError,
    "an anchor whose footprint reaches the band fails the level, not the match",
  );
  const inBand = RTS_WORLD_BUILD_HALF_EXTENT - farm.footprint.width / 2 - 1;
  assert.ok(
    adaptRtsLevel(
      [...starts, actor("BP_RTS_BuildAnchor", anchorVars, { owner: "enemy", buildingId: "farm" }, [inBand, 0, 0])],
      [route], { buildings, resources, animals },
    ).buildAnchors.length === 1,
    "the same anchor one unit further in is accepted",
  );
});

check("RTS simulation speed multiplies time in safe fixed-size slices", () => {
  assert.deepEqual(simulationSteps(1 / 60, 1, 1 / 15), [1 / 60]);
  const accelerated = simulationSteps(1 / 60, 8, 1 / 15);
  assert.deepEqual(accelerated, [1 / 15, 1 / 15]);
  assert.equal(accelerated.reduce((total, step) => total + step, 0), 8 / 60);
  assert.throws(() => simulationSteps(1 / 60, 3 as never, 1 / 15), /Unsupported RTS simulation speed/);
});

const shippedCaravanBalance = () => validateCaravanBalance(
  JSON.parse(readFileSync("public/game-data/balance/logistics.json", "utf8")) as unknown,
);

const shippedBuildingBalance = () => validateBuildingBalance(
  JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
);

/** Synthetic arrival stream for transfer-only fixtures that do not mount caravans. */
function instantCaravanArrivals(links: ProductionLogisticsSystem) {
  return links.snapshots()
    .filter((link) => link.status === "linked")
    .map((link) => ({
      caravanId: `fixture:${link.structureId}`,
      laneId: producerLaneId(link.structureId),
      owner: link.owner,
      carryCapacity: Number.POSITIVE_INFINITY,
    }));
}

check("V4 Faz 1: caravan tuning owns movement, not a fixed cargo size", () => {
  // Computed from both shipped tables rather than pinned, so the contract holds
  // at any tuning: the bound is whatever the weakest producer's buffer happens
  // to be after the next balance pass, and the check moves with it.
  const caravan = shippedCaravanBalance();
  assert.equal("carryCapacity" in caravan, false, "each producer now determines its own shipment threshold");
  assert.ok(caravan.moveSpeed < 2.2, "the donkey moves slower than the first visual pass");
});

check("V4 Faz 1: the caravan validator refuses data that could never make sense", () => {
  const caravan = shippedCaravanBalance();
  const refuse = (patch: Record<string, unknown>, why: string): void => {
    assert.throws(() => validateCaravanBalance({ caravan: { ...caravan, ...patch } }), GameDataError, why);
  };
  refuse({ moveSpeed: 0 }, "a caravan that never arrives starves the producer it serves");
  refuse({ walkClipSpeed: 0 }, "a walk clip with no reference speed cannot be calibrated");
  refuse({ maxHealth: 0 }, "a caravan has to be a thing that can be killed");
  refuse({ loadSeconds: -1 }, "loading cannot take negative time");
  refuse({ spawnPerProducer: 1.5 }, "half a donkey is not a caravan");
  refuse({ spawnPerProducer: 0 }, "a producer with no caravan would never ship anything");
  refuse({ armorClass: "structure" }, "a pack animal is not a building");
  refuse({ label: "" }, "the table entry has to name itself");
  // Zero is the one legal floor: a brisk tuning, not a broken one.
  assert.ok(
    validateCaravanBalance({ caravan: { ...caravan, loadSeconds: 0 } }).loadSeconds === 0,
    "an instant load is a tuning choice the validator allows",
  );
});

check("V4 Faz 1: the caravan is art from the wildlife pack, but never a row in the species table", () => {
  const animals = shippedAnimalBalance();
  // KARAR 3-B, checked rather than trusted: a `donkey` species would drag the
  // grazing/fleeing/hunting fields onto something that does none of them.
  assert.equal(animals["donkey"], undefined, "the caravan has no huntable-species row");

  const actorRef = rtsCaravanActorRef(shippedRtsContentCatalog())
    ?? assert.fail("the catalog maps no caravan Actor");
  assert.ok(existsSync(`public/${actorRef}`), `${actorRef} exists on disk`);
  assert.ok(
    rtsContentCatalogRefs(shippedRtsContentCatalog()).includes(actorRef),
    "the logistics Actor is included in the presentation preflight load set",
  );

  // The Actor points at a mesh the manifest ships, and that mesh has a sidecar —
  // the pairing the wildlife clip test then checks clip by clip.
  const actor = JSON.parse(readFileSync(`public/${actorRef}`, "utf8")) as {
    components?: { props?: { assetId?: string } }[];
  };
  const assetId = actor.components?.find((component) => component.props?.assetId)?.props?.assetId
    ?? assert.fail("the caravan Actor names no skeletal mesh");
  const manifest = JSON.parse(readFileSync("public/assets/manifest.json", "utf8")) as {
    assets: { id: string; path: string }[];
  };
  const mesh = manifest.assets.find((asset) => asset.id === assetId)
    ?? assert.fail(`the caravan Actor's mesh "${assetId}" is not in the manifest`);
  assert.ok(
    existsSync(`public/${mesh.path.replace(/\.gltf$/, ".skeleton.json")}`),
    `${mesh.path} carries the skeleton sidecar its clips are resolved through`,
  );
});

check("V4 Faz 3: a caravan follows road cells through its full continuous route", () => {
  const route = [{ x: 0, z: 0 }, { x: 2, z: 0 }, { x: 2, z: 2 }];
  const first = advanceCaravanRoute(route, startCaravanRoute(route), 2, 0.5);
  assert.deepEqual(first.state, { waypointIndex: 0, x: 1, z: 0, facing: Math.PI / 2 });
  assert.equal(first.arrived, false);
  const last = advanceCaravanRoute(route, first.state, 2, 1.5);
  assert.deepEqual(last.state, { waypointIndex: 2, x: 2, z: 2, facing: 0 });
  assert.equal(last.arrived, true, "a large simulation step cannot skip the road endpoint");
});

check("wildlife ignores people but flees once when a wolf enters its close threat circle", () => {
  const animals = shippedAnimalBalance();
  const herd = [{ id: "deer", species: "deer", x: 0, z: 0, count: 1 }];
  const calm = new WildlifeSystem(animals, herd);
  const peopleNearby = new WildlifeSystem(animals, herd);
  calm.update(0.25, []);
  peopleNearby.update(0.25, [{ x: 0, z: 0 }]);
  assert.deepEqual(
    peopleNearby.snapshots(),
    calm.snapshots(),
    "people no longer alter wildlife roaming or trigger a nearest-person scan",
  );

  const wildlife = new WildlifeSystem(animals, [
    { id: "deer", species: "deer", x: 0, z: 0, count: 1 },
    { id: "wolf", species: "wolf", x: 12, z: 0, count: 1 },
  ]);
  const deer = wildlife.animalById("deer:0") ?? assert.fail("deer missing");
  const wolf = wildlife.animalById("wolf:0") ?? assert.fail("wolf missing");
  deer.position.set(0, 0, 0);
  wolf.position.set(2.5, 0, 0);
  const predators = new PredatorSystem(new UnitSystem(), wildlife, () => "neutral");
  predators.update(0.25);
  wildlife.update(0.25);
  assert.ok(deer.speed > 0, "the deer receives the wolf's one-time close-range flee event");
  assert.ok(deer.position.x < 0, "the flee direction points away from the wolf");
});

check("V4 Faz 3: linked producers receive automatic non-population caravans", () => {
  const buildings = shippedBuildingBalance();
  const roads = new RoadGraph(validateRoadBalance(
    JSON.parse(readFileSync("public/game-data/balance/roads.json", "utf8")) as unknown,
  ));
  const centerStats = buildings.command_center ?? assert.fail("command centre definition missing");
  const farmStats = buildings.farm ?? assert.fail("farm definition missing");
  const centers = new CommandCenterSystem();
  centers.spawn("player", 0, 0, centerStats.maxHealth, centerStats);
  roads.commit(centerAccessRoadPlan(roads, { x: 0, z: 0, footprint: centerStats.footprint }));
  const structures = new PlacedStructureSystem();
  const farm = structures.place("player", farmStats, 0, 16);
  structures.advanceConstruction(farm, farmStats.constructionSeconds);
  const branch = roads.plan({ x: 0, z: 6 }, { x: 0, z: 12 }, []);
  assert.ok(branch);
  roads.commit(branch);
  const units = new UnitSystem();
  const population = new PopulationSystem("player", units, structures, 10);
  const before = population.snapshot().current;
  const links = new ProductionLogisticsSystem(structures, roads, new DepotLogisticsSystem(structures, roads, centers));
  assert.equal(links.snapshots()[0]?.status, "linked", "the farm touches the centre road ring");
  const caravans = new CaravanSystem(shippedCaravanBalance(), roads, [
    new ProducerCaravanLanes(
      shippedCaravanBalance(),
      links,
      roads,
      structures,
      centers,
      undefined,
      () => ({ carryCapacity: 30, ready: true, canReceive: true }),
    ),
  ]);
  caravans.update(shippedCaravanBalance().loadSeconds);
  caravans.update(1);
  const caravan = caravans.snapshots()[0] ?? assert.fail("the linked producer receives its automatic donkey");
  assert.equal(caravan.phase, "outbound");
  assert.ok(caravan.speed > 0, "the donkey moves after loading");
  assert.equal(population.snapshot().current, before, "a caravan never enters the Unit population roster");
  structures.clear();
  centers.clear();
});

check("V4 Faz 5: a caravan waits for a full producer load and pauses when storage is full", () => {
  const roads = roadGraphOf([[{ x: -2, z: 0 }, { x: 2, z: 0 }]]);
  const caravan = new Caravan(
    "caravan:dispatch",
    producerLaneId(1),
    "player",
    { x: -2, z: 0 },
    { x: 2, z: 0 },
    shippedCaravanBalance(),
    roads,
    60,
  );
  const waiting = { carryCapacity: 60, ready: false, canReceive: true };
  caravan.update(20, { x: -2, z: 0 }, { x: 2, z: 0 }, waiting);
  assert.equal(caravan.phase, "loading", "a partial producer buffer leaves its donkey at home");
  assert.equal(caravan.position.x, -2, "an unready load cannot start a cosmetic round trip");
  const ready = { carryCapacity: 60, ready: true, canReceive: true };
  caravan.update(shippedCaravanBalance().loadSeconds, { x: -2, z: 0 }, { x: 2, z: 0 }, ready);
  assert.equal(caravan.phase, "outbound", "a full minute-sized load releases the donkey");
  caravan.beginReturnHome({ x: -2, z: 0 });
  caravan.updateReturnHome(10);
  caravan.update(20, { x: -2, z: 0 }, { x: 2, z: 0 }, { ...ready, canReceive: false, ready: false });
  assert.equal(caravan.phase, "loading", "a full global store holds the completed return at home");
});

