check("V4 Faz 4: an occupied depot sends its caravan to the command centre", () => {
  const buildings = shippedBuildingBalance();
  const roads = new RoadGraph(validateRoadBalance(
    JSON.parse(readFileSync("public/game-data/balance/roads.json", "utf8")) as unknown,
  ));
  const centerStats = buildings.command_center ?? assert.fail("command centre definition missing");
  const depotStats = buildings.depot ?? assert.fail("depot definition missing");
  const farmStats = buildings.farm ?? assert.fail("farm definition missing");
  const centers = new CommandCenterSystem();
  centers.spawn("player", 0, 0, centerStats.maxHealth, centerStats);
  roads.commit(centerAccessRoadPlan(roads, { x: 0, z: 0, footprint: centerStats.footprint }));
  const branch = roads.plan({ x: 0, z: 6 }, { x: 0, z: 18 }, []);
  assert.ok(branch);
  roads.commit(branch);
  const structures = new PlacedStructureSystem();
  const depot = structures.place("player", depotStats, 4, 12);
  const farm = structures.place("player", farmStats, 0, 22);
  structures.advanceConstruction(depot, depotStats.constructionSeconds);
  structures.advanceConstruction(farm, farmStats.constructionSeconds);
  const depots = new DepotLogisticsSystem(structures, roads, centers);
  const openLinks = new ProductionLogisticsSystem(
    structures,
    roads,
    depots,
  );
  assert.equal(openLinks.snapshots()[0]?.depotStructureId, depot.id, "the nearest usable depot beats the farther command centre");
  const occupation = new LogisticsOccupationSystem(depots);
  occupation.setOccupier(depot.id, "enemy");
  const links = new ProductionLogisticsSystem(
    structures,
    roads,
    depots,
    undefined,
    occupation,
  );
  assert.equal(links.snapshots()[0]?.status, "linked", "the centre remains a legal endpoint");
  const caravans = new CaravanSystem(shippedCaravanBalance(), roads, [
    new ProducerCaravanLanes(shippedCaravanBalance(), links, roads, structures, centers, occupation),
  ]);
  caravans.update(0);
  const caravan = caravans.snapshots()[0] ?? assert.fail("linked producer has a caravan");
  const centerRoad = roadCellTouchingFootprint(roads, 0, 0, centerStats.footprint.width, centerStats.footprint.depth)
    ?? assert.fail("the centre road ring has no endpoint");
  const depotRoad = roadCellTouchingFootprint(roads, depot.x, depot.z, depot.stats.footprint.width, depot.stats.footprint.depth);
  assert.deepEqual(
    { x: caravan.destinationX, z: caravan.destinationZ },
    centerRoad,
    "the unusable depot is skipped in favour of the centre road",
  );
  assert.notDeepEqual({ x: caravan.destinationX, z: caravan.destinationZ }, depotRoad, "the caravan does not stop at the occupied depot");
  structures.clear();
  centers.clear();
});

check("RTS road graph finds obstacle-free cells, charges new segments, and keeps alternate connectivity", () => {
  const balance = validateRoadBalance(
    JSON.parse(readFileSync("public/game-data/balance/roads.json", "utf8")) as unknown,
  );
  // Structural contract only: the presentational `visual` block is live-tuned by
  // designers, so pinning its exact numbers here just makes the suite flap. Its
  // own parsing/shape is covered by the painted-road tests.
  // cellSize is not tuning: placement, footprints and the road grid all assume
  // the same 2-unit cell, so changing it is a code change wearing a data hat.
  assert.equal(balance.cellSize, 2);
  assert.ok(balance.woodCostPerCell > 0, "a paved cell costs wood");
  assert.ok((balance.autoConnect?.maxCells ?? 0) > 0, "a building near the network links itself");
  assert.ok(balance.visual && typeof balance.visual.width === "number", "visual tuning still parses");
  const roads = new RoadGraph(balance);
  const blockers = [{ min: [-1, -1, -1], max: [1, 3, 1] }];
  const detour = roads.plan({ x: -6, z: 0 }, { x: 6, z: 0 }, blockers);
  assert.ok(detour, "road graph finds a flank around a blocked cell");
  assert.ok(detour.cells.every((cell) => cell.x !== 0 || cell.z !== 0), "route avoids the occupied road cell");
  assert.equal(detour.woodCost, detour.newCells.length * balance.woodCostPerCell);
  roads.commit(detour);
  assert.equal(roads.connected({ x: -6, z: 0 }, { x: 6, z: 0 }), true);
  assert.ok(roads.all().some((segment) => segment.kind === "corner"), "detour produces corner segments");
  const corner = roads.all().find((segment) => segment.kind === "corner");
  assert.deepEqual(corner?.connections.length, 2, "a visual corner has exactly two exits");
  assert.ok(corner?.connections.some((direction) => direction === "north" || direction === "south"));
  assert.ok(corner?.connections.some((direction) => direction === "east" || direction === "west"));
  assert.equal(roads.components().length, 1);
  assert.equal(roads.edgeCount(), roads.all().length - 1, "the detour is one acyclic component");

  const isolated = roads.plan({ x: 30, z: 30 }, { x: 34, z: 30 }, blockers);
  assert.ok(isolated);
  roads.commit(isolated);
  assert.equal(roads.components().length, 2, "disconnected roads remain separate graph components");
  assert.equal(roads.version, 2);

  const overlap = roads.plan({ x: -6, z: 0 }, { x: 6, z: 0 }, blockers);
  assert.ok(overlap);
  assert.equal(overlap.woodCost, 0, "existing road cells are never charged twice");

  const redundant = new RoadGraph(balance);
  for (const [start, end] of [
    [{ x: -4, z: 0 }, { x: 4, z: 0 }],
    [{ x: -4, z: 0 }, { x: -4, z: 4 }],
    [{ x: -4, z: 4 }, { x: 4, z: 4 }],
    [{ x: 4, z: 4 }, { x: 4, z: 0 }],
  ] as const) {
    const plan = redundant.plan(start, end, []);
    assert.ok(plan);
    redundant.commit(plan);
  }
  assert.equal(redundant.remove([{ x: 0, z: 0 }]), 1);
  assert.equal(redundant.connected({ x: -4, z: 0 }, { x: 4, z: 0 }), true, "an alternate branch preserves connectivity after a road cut");
});

check("RTS a caravan route uses only committed road cells", () => {
  const roads = roadGraphOf([[{ x: -6, z: 0 }, { x: 6, z: 0 }]]);
  const route = roads.route({ x: -6, z: 0 }, { x: 6, z: 0 });
  assert.ok(route, "committed endpoints have a route");
  const committed = new Set(roads.all().map((cell) => `${cell.x}:${cell.z}`));
  assert.ok(route.every((cell) => committed.has(`${cell.x}:${cell.z}`)), "a caravan never crosses bare ground");
});

check("RTS a caravan route is deterministic", () => {
  const roads = new RoadGraph({
    cellSize: 2,
    woodCostPerCell: 4,
    visual: ROAD_PAINT_VISUAL,
    buildingPad: BUILDING_PAD_VISUAL,
  });
  const cells = [
    { x: 0, z: 0 }, { x: 2, z: 0 }, { x: 4, z: 0 },
    { x: 0, z: 2 }, { x: 4, z: 2 },
    { x: 0, z: 4 }, { x: 2, z: 4 }, { x: 4, z: 4 },
  ];
  roads.commit({ cells, newCells: cells, woodCost: 0 });
  assert.deepEqual(
    roads.route({ x: 0, z: 0 }, { x: 4, z: 4 }),
    roads.route({ x: 0, z: 0 }, { x: 4, z: 4 }),
    "equal-length road branches resolve to the same route",
  );
});

check("RTS a severed road leaves a caravan without a route", () => {
  const roads = roadGraphOf([[{ x: -4, z: 0 }, { x: 4, z: 0 }]]);
  assert.ok(roads.route({ x: -4, z: 0 }, { x: 4, z: 0 }), "the intact road is traversable");
  assert.equal(roads.remove([{ x: 0, z: 0 }]), 1, "the bridge tile is removed");
  assert.equal(roads.route({ x: -4, z: 0 }, { x: 4, z: 0 }), null, "the disconnected endpoint has no route");
});

check("RTS a road routes around a standing tree and straight through once it is felled", () => {
  const balance = validateRoadBalance(
    JSON.parse(readFileSync("public/game-data/balance/roads.json", "utf8")) as unknown,
  );
  const roads = new RoadGraph(balance);
  const forests = new ForestSystem([
    { id: "on-route", forestId: "grove", x: 0, z: 0, capacity: 40, variant: "pine" },
  ]);
  const units = new UnitSystem();
  const structures = new PlacedStructureSystem();
  const kingdoms = new KingdomRegistry(["player"], units, structures, { wood: 500 }, 20);
  const construction = new RoadConstructionService(roads, kingdoms, () => forests.liveTreeBlockers());
  const detour = construction.plan({ x: -6, z: 0 }, { x: 6, z: 0 });
  assert.ok(detour, "a road still connects across a grove");
  assert.ok(detour.cells.every((cell) => cell.x !== 0 || cell.z !== 0), "the route bends around the standing tree");
  // Fell the tree; its cell stops reserving road space.
  forests.reserveNearest(1, { resourceId: "wood", x: 0, z: 0, radius: 4 });
  forests.harvest({ workerId: 1, sourceId: "on-route", amount: 40, deltaSeconds: 1 });
  const through = construction.plan({ x: -6, z: 0 }, { x: 6, z: 0 });
  assert.ok(through, "a road plans across the cleared cell");
  assert.ok(through.cells.some((cell) => cell.x === 0 && cell.z === 0), "the felled tree no longer diverts the road");
});

check("RTS a road bends around a live stone deposit and paves straight through a depleted one", () => {
  const balance = validateRoadBalance(
    JSON.parse(readFileSync("public/game-data/balance/roads.json", "utf8")) as unknown,
  );
  const resourceBalance = validateResourceBalance(
    JSON.parse(readFileSync("public/game-data/balance/resources.json", "utf8")) as unknown,
  );
  const roads = new RoadGraph(balance);
  const nodes = new ResourceNodeSystem({
    ...resourceBalance,
    stone: { ...resourceBalance.stone!, externalNode: { capacity: 10, perWorkerPerMinute: 5 } },
  }, [{ id: "on-route", resourceId: "stone", kind: "external", x: 0, z: 0 }]);
  const units = new UnitSystem();
  const structures = new PlacedStructureSystem();
  const kingdoms = new KingdomRegistry(["player"], units, structures, { wood: 500 }, 20);
  const construction = new RoadConstructionService(roads, kingdoms, () => nodes.liveNodeBlockers());

  const detour = construction.plan({ x: -6, z: 0 }, { x: 6, z: 0 });
  assert.ok(detour, "a road still connects past a deposit");
  assert.ok(detour.cells.every((cell) => cell.x !== 0 || cell.z !== 0), "the route bends around the deposit tile");
  // The reserve is deliberately one tile wide, matching a tree's: the extractor
  // stands beside the deposit, so its footprint and the road that serves it both
  // need the neighbouring tiles to stay pavable.
  assert.ok(
    detour.cells.some((cell) => Math.abs(cell.x) <= 2 && Math.abs(cell.z) <= 2),
    "the road still runs within touching distance of a quarry built beside the deposit",
  );

  // Mine the deposit dry from beside it; like a felled tree, it stops reserving.
  assert.equal(nodes.extract("stone", 6, 0, 8, undefined, 10), 10);
  const through = construction.plan({ x: -6, z: 0 }, { x: 6, z: 0 });
  assert.ok(through, "a road plans across the emptied deposit");
  assert.ok(
    through.cells.some((cell) => cell.x === 0 && cell.z === 0),
    "a depleted deposit no longer diverts the road",
  );
});

check("RTS a quarry is built beside its deposit, never on it, and an old road cannot strand it", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const roadBalance = validateRoadBalance(
    JSON.parse(readFileSync("public/game-data/balance/roads.json", "utf8")) as unknown,
  );
  const resourceBalance = validateResourceBalance(
    JSON.parse(readFileSync("public/game-data/balance/resources.json", "utf8")) as unknown,
  );
  const nodes = new ResourceNodeSystem(resourceBalance, [
    { id: "test-stone", resourceId: "stone", kind: "safe", x: 0, z: 0 },
  ]);
  const units = new UnitSystem();
  const structures = new PlacedStructureSystem();
  const centers = new CommandCenterSystem();
  // Far enough that the centre's own 8x8 footprint never touches the extractor's,
  // so "blocked" below can only mean the road tile.
  centers.spawn("player", 0, 10);
  const navigation = new RtsNavigation();
  navigation.setBlockers(centers.navigationBlockers());
  const kingdoms = new KingdomRegistry(["player"], units, structures, { food: 0, wood: 500 }, 20);
  const territory = new TerritoryControlSystem(() => centers.all().map((center) => ({
    owner: center.owner, x: center.position.x, z: center.position.z, radius: COMMAND_CENTER_CONTROL_RADIUS,
  })));
  territory.refresh();
  const roads = new RoadGraph(roadBalance);
  const roadConstruction = new RoadConstructionService(roads, kingdoms, () => []);
  const construction = new StructureConstructionService(
    buildings,
    structures,
    kingdoms,
    navigation,
    () => [...centers.navigationBlockers(), ...structures.navigationBlockers()],
    territory,
    () => {},
    () => {},
    (stats, x, z) => stats.economy?.requiresResourceNode
      && !nodes.canExtractAt(stats.economy.resourceId, x, z, stats.economy.gatherRadius ?? 0, stats.footprint)
      ? "missing-resource-node"
      : null,
    // Roads and live deposits both reserve build space, exactly as the game
    // wires them.
    () => [...roads.occupancyBlockers(), ...nodes.liveNodeBlockers()],
  );

  // The deposit itself is not build space: a quarry centred on it is refused as
  // occupied ground, the same answer a lumber camp gets on a trunk. That is the
  // whole rule — nothing is ever built over a deposit, so nothing can bury one
  // or hide the depletion stages that show how much is left.
  assert.equal(construction.validate("player", "quarry", 0, 0)?.reason, "blocked");

  // Pave the deposit's own tile — the shape the router refuses to produce, but
  // which older saves and hand-drawn routes already contain. It used to strand
  // the deposit for good, because the extractor had to *contain* the point it
  // covered. Built beside instead, the quarry no longer cares.
  const onDeposit = roads.plan({ x: 0, z: 0 }, { x: 0, z: 0 }, []);
  assert.ok(onDeposit);
  roads.commit(onDeposit);
  const beside = construction.validate("player", "quarry", 6, 0);
  assert.equal(beside?.reason, null, "a quarry beside the deposit is legal with the road still paved");

  // §44 Yol Silme still erases without refund, and the ground it frees is
  // buildable — the tile is ordinary ground, not the deposit's.
  assert.equal(roadConstruction.demolish([{ x: 0, z: 0 }]), 1);
  assert.equal(roads.all().length, 0, "the erased tile leaves the network");
  const built = construction.build("player", "quarry", 6, 0);
  assert.ok(built.built, "the quarry is built beside its deposit");
  // The Quarry is the only thing the wallet paid for: the tile above was paved
  // straight onto the graph, and erasing it refunds nothing — the §44 rule this
  // whole check exists for. Derived from the table so a retune stays true.
  assert.equal(
    kingdoms.get("player").wallet.amount("wood"),
    500 - (buildings.quarry?.cost.wood ?? 0),
    "erasing a road refunds nothing",
  );
});

check("RTS road erase picks the hovered tile and warns only when losing it splits the network", () => {
  const balance = validateRoadBalance(
    JSON.parse(readFileSync("public/game-data/balance/roads.json", "utf8")) as unknown,
  );
  const roads = new RoadGraph(balance);
  const units = new UnitSystem();
  const structures = new PlacedStructureSystem();
  const kingdoms = new KingdomRegistry(["player"], units, structures, { wood: 500 }, 20);
  let commits = 0;
  const construction = new RoadConstructionService(roads, kingdoms, () => [], () => { commits += 1; });
  const spine = construction.build("player", { x: -4, z: 0 }, { x: 4, z: 0 });
  assert.ok(spine.built);
  assert.equal(commits, 1);

  // The pick snaps a ground point to its committed tile, and reports bare ground.
  assert.deepEqual(roads.cellAt({ x: 0.7, z: -0.4 }), { x: 0, z: 0 }, "a ground point resolves to its road tile");
  assert.equal(roads.cellAt({ x: 0, z: 20 }), null, "bare ground has no tile to erase");

  // A straight run: the interior is a bridge, the two ends are not.
  assert.equal(roads.wouldDisconnect({ x: 0, z: 0 }), true, "cutting mid-run splits the spine");
  assert.equal(roads.wouldDisconnect({ x: -4, z: 0 }), false, "a dead end cuts nothing off");

  // Close a loop around the middle; the same tile stops being a bridge.
  assert.ok(construction.build("player", { x: -2, z: 0 }, { x: -2, z: 4 }).built);
  assert.ok(construction.build("player", { x: -2, z: 4 }, { x: 2, z: 4 }).built);
  assert.ok(construction.build("player", { x: 2, z: 4 }, { x: 2, z: 0 }).built);
  assert.equal(roads.wouldDisconnect({ x: 0, z: 0 }), false, "a loop closes around the gap");

  const before = roads.all().length;
  assert.equal(construction.demolish([{ x: 0, z: 0 }]), 1);
  assert.equal(roads.all().length, before - 1);
  assert.equal(roads.connected({ x: -4, z: 0 }, { x: 4, z: 0 }), true, "the loop keeps both ends linked");
  // Erasing bare ground changes nothing and must not fire the repaint hook.
  const quiet = commits;
  assert.equal(construction.demolish([{ x: 0, z: 20 }]), 0);
  assert.equal(commits, quiet, "an erase that removed nothing does not refresh visuals");
});

check("RTS auto-connect paves a free access road from a building placed short of the network", () => {
  const balance = validateRoadBalance(
    JSON.parse(readFileSync("public/game-data/balance/roads.json", "utf8")) as unknown,
  );
  const router = (roads: RoadGraph) => (start: RoadCell, end: RoadCell) => roads.plan(start, end, []);

  // A horizontal road spine along z = 0; a 6x6 footprint centred at z = 8 sits
  // two cells clear of it, so nothing touches its footprint yet.
  const roads = new RoadGraph(balance);
  const spine = roads.plan({ x: -6, z: 0 }, { x: 6, z: 0 }, []);
  assert.ok(spine);
  roads.commit(spine);
  const footprint = { x: 0, z: 8, width: 6, depth: 6 };
  assert.equal(
    roadCellTouchingFootprint(roads, footprint.x, footprint.z, footprint.width, footprint.depth),
    null,
    "the building starts unlinked, a couple of cells off the spine",
  );

  const plan = planAutoRoadConnection(roads, footprint, router(roads), { maxNewCells: 6 });
  assert.ok(plan, "an access road is planned to the nearest spine cell");
  assert.ok(plan.newCells.length > 0 && plan.newCells.length <= 6, "only the short gap is paved");
  roads.commit(plan);
  const touching = roadCellTouchingFootprint(roads, footprint.x, footprint.z, footprint.width, footprint.depth);
  assert.ok(touching, "after the auto road commits, a tile touches the footprint");
  assert.equal(
    roads.connected(touching, { x: 0, z: 0 }),
    true,
    "the access road joins the building to the existing spine as one component",
  );

  assert.equal(touching.x, footprint.x, "the access road meets the building on its centre axis, not a corner");

  // Centring holds even when the nearest road is off to one side: a spine that
  // only runs to the left of the building must still leave it from the centre of
  // its face (x = 0) and turn to reach the road, not clip the near corner.
  const offside = new RoadGraph(balance);
  const offsideSpine = offside.plan({ x: -12, z: 0 }, { x: -6, z: 0 }, []);
  assert.ok(offsideSpine);
  offside.commit(offsideSpine);
  const offsidePlan = planAutoRoadConnection(offside, footprint, router(offside), { maxNewCells: 6 });
  assert.ok(offsidePlan, "an access road still reaches an off-to-the-side spine");
  offside.commit(offsidePlan);
  const offsideTouch = roadCellTouchingFootprint(offside, footprint.x, footprint.z, footprint.width, footprint.depth);
  assert.ok(offsideTouch);
  assert.equal(offsideTouch.x, footprint.x, "the road exits the building centre before turning toward the side spine");

  // Idempotent: a building already on the network gets no second road.
  assert.equal(
    planAutoRoadConnection(roads, footprint, router(roads), { maxNewCells: 6 }),
    null,
    "a building already touching a road is left alone",
  );

  // Range cap: the same building far from the spine is deemed off-grid.
  const far = new RoadGraph(balance);
  const farSpine = far.plan({ x: -6, z: 0 }, { x: 6, z: 0 }, []);
  assert.ok(farSpine);
  far.commit(farSpine);
  assert.equal(
    planAutoRoadConnection(far, { x: 0, z: 40, width: 6, depth: 6 }, router(far), { maxNewCells: 6 }),
    null,
    "a building beyond the cell budget gets no free highway",
  );

  // Nothing to connect to, and a disabled budget, both no-op.
  assert.equal(
    planAutoRoadConnection(new RoadGraph(balance), footprint, router(new RoadGraph(balance)), { maxNewCells: 6 }),
    null,
    "an empty road graph offers no target",
  );
  assert.equal(
    planAutoRoadConnection(roads, { x: 0, z: 16, width: 6, depth: 6 }, router(roads), { maxNewCells: 0 }),
    null,
    "maxNewCells of 0 disables the feature",
  );
});

/**
 * Ground ownership split down the z axis: everything at x < 0 is the player's,
 * everything at x > 0 the enemy's, and the x = 0 column is unclaimed. Enough to
 * stand a border in the middle of a road grid without a TerritoryControlSystem
 * (which needs three.js).
 */
function splitOwnership(version = 1) {
  return {
    version,
    ownerAt: (x: number): "player" | "enemy" | "neutral" => (x < 0 ? "player" : x > 0 ? "enemy" : "neutral"),
  };
}

check("RTS roads belong to the ground they cross, so two kingdoms keep two networks", () => {
  const balance = validateRoadBalance(
    JSON.parse(readFileSync("public/game-data/balance/roads.json", "utf8")) as unknown,
  );
  const roads = new RoadGraph(balance, splitOwnership());
  // One continuous paved line straight across the border.
  const spine = roads.plan({ x: -8, z: 0 }, { x: 8, z: 0 }, []);
  assert.ok(spine, "paving is planned without a perspective, as the map author would");
  roads.commit(spine);

  assert.equal(roads.ownerAt({ x: -8, z: 0 }), "player", "ground west of the line is the player's");
  assert.equal(roads.ownerAt({ x: 8, z: 0 }), "enemy", "ground east of it is the enemy's");
  assert.equal(roads.ownerAt({ x: 0, z: 0 }), "neutral", "the seam belongs to nobody");

  // The cells are physically adjacent, so an ownership-blind read still sees one
  // network — that is the pre-existing answer and the one debug views want.
  assert.equal(roads.components().length, 1, "physically the pavement is continuous");
  assert.equal(roads.connected({ x: -8, z: 0 }, { x: 8, z: 0 }), true);

  // Asked as either kingdom, the far side is unreachable: own and unclaimed
  // ground is passable, the opponent's is not.
  assert.equal(roads.connected({ x: -8, z: 0 }, { x: 8, z: 0 }, "player"), false,
    "the player cannot travel onto enemy-held pavement");
  assert.equal(roads.connected({ x: 8, z: 0 }, { x: -8, z: 0 }, "enemy"), false,
    "and the enemy cannot travel onto the player's");
  assert.equal(roads.route({ x: -8, z: 0 }, { x: 8, z: 0 }, "player"), null);
  assert.ok(roads.route({ x: -8, z: 0 }, { x: 0, z: 0 }, "player"), "unclaimed ground stays usable by both");
  assert.ok(roads.route({ x: 8, z: 0 }, { x: 0, z: 0 }, "enemy"), "which is what keeps a haul road to a trade site alive");

  // Each side sees only the stretch it may use, as one island of its own.
  const playerCells = roads.components("player").flatMap((component) => component.cells);
  assert.ok(playerCells.every((cell) => cell.x <= 0), "the player's network stops at the seam");
  assert.ok(roads.components("enemy").flatMap((component) => component.cells).every((cell) => cell.x >= 0));

  // And a route may not be *planned* through ground its owner does not hold,
  // which is what stops a new road welding the two networks together.
  assert.equal(roads.plan({ x: -8, z: 4 }, { x: 8, z: 4 }, [], "player"), null,
    "the player cannot pave across the border");
  assert.ok(roads.plan({ x: -8, z: 4 }, { x: 0, z: 4 }, [], "player"), "but may pave up to it");
});

check("RTS auto-connect joins its own network, never the neighbour's road across the border", () => {
  const balance = validateRoadBalance(
    JSON.parse(readFileSync("public/game-data/balance/roads.json", "utf8")) as unknown,
  );
  const roads = new RoadGraph(balance, splitOwnership());
  // The enemy's spine runs down its own side, two cells east of the seam.
  const enemySpine = roads.plan({ x: 4, z: -8 }, { x: 4, z: 8 }, []);
  assert.ok(enemySpine);
  roads.commit(enemySpine);

  // The player drops a 6x6 building hard against the border. The enemy road is
  // the nearest pavement by a wide margin — and must still be refused.
  const footprint = { x: -2, z: 0, width: 6, depth: 6 };
  const router = (start: RoadCell, end: RoadCell) => roads.plan(start, end, [], "player");
  assert.equal(
    planAutoRoadConnection(roads, footprint, router, { maxNewCells: 6, owner: "player" }),
    null,
    "with no road of its own to reach, the building simply stays unlinked",
  );

  // Give the player a spine of its own, further away than the enemy's.
  const playerSpine = roads.plan({ x: -10, z: -8 }, { x: -10, z: 8 }, []);
  assert.ok(playerSpine);
  roads.commit(playerSpine);
  const plan = planAutoRoadConnection(roads, footprint, router, { maxNewCells: 8, owner: "player" });
  assert.ok(plan, "the farther own-side spine is the one it connects to");
  assert.ok(plan.cells.every((cell) => cell.x <= 0), "no cell of the access road lands on enemy ground");
  roads.commit(plan);
  assert.equal(
    roads.connected({ x: -10, z: 0 }, { x: 4, z: 0 }, "player"),
    false,
    "the two settlements' networks stay separate after the building lands",
  );
});

check("RTS road paint takes each kingdom's own age layer, not whoever aged up last", () => {
  const balance = validateRoadBalance(
    JSON.parse(readFileSync("public/game-data/balance/roads.json", "utf8")) as unknown,
  );
  const ageLayers = balance.visual.ageLayers ?? assert.fail("road visual must map ages to paint layers");
  const settlementLayer = ageLayers.settlement ?? assert.fail("settlement road layer missing");
  const townLayer = ageLayers.town ?? assert.fail("town road layer missing");
  assert.notEqual(settlementLayer, townLayer, "the ages are meant to look different");

  const roads = new RoadGraph(balance, splitOwnership());
  const spine = roads.plan({ x: -8, z: 0 }, { x: 8, z: 0 }, []);
  assert.ok(spine);
  roads.commit(spine);

  // Only the player has reached the Town age; the enemy is still a settlement.
  const layerFor = (owner: string): string => (owner === "player" ? townLayer : settlementLayer);
  const spline = roadGraphToLandscapeSpline(roads.all(), {
    cellSize: balance.cellSize,
    origin: [0, 0, 0] as [number, number, number],
    visual: balance.visual,
    layerForOwner: layerFor,
  });

  const pointById = new Map(spline.points.map((point) => [point.id, point]));
  const layersByOwner = new Map<string, Set<string>>();
  for (const segment of spline.segments) {
    const start = pointById.get(segment.startPointId) ?? assert.fail("segment references a missing point");
    const owner = roads.ownerAt({ x: start.position[0], z: start.position[2] });
    const seen = layersByOwner.get(owner) ?? new Set<string>();
    seen.add(segment.paint?.layerId ?? "");
    layersByOwner.set(owner, seen);
  }
  assert.deepEqual([...layersByOwner.get("player") ?? []], [townLayer], "the player's stretch is cobbled");
  assert.deepEqual([...layersByOwner.get("enemy") ?? []], [settlementLayer], "the enemy's stays dirt");
  assert.deepEqual([...layersByOwner.get("neutral") ?? []], [settlementLayer],
    "and unclaimed ground keeps the base layer");
});

check("RTS command-centre road rings form the only active logistics network", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const balance = validateRoadBalance(
    JSON.parse(readFileSync("public/game-data/balance/roads.json", "utf8")) as unknown,
  );
  const centerStats = buildings.command_center ?? assert.fail("command centre definition missing");
  const depotStats = buildings.depot ?? assert.fail("depot definition missing");
  const farmStats = buildings.farm ?? assert.fail("farm definition missing");
  const centers = new CommandCenterSystem();
  centers.spawn("player", 0, 0, centerStats.maxHealth, centerStats);
  const roads = new RoadGraph(balance);
  roads.commit(centerAccessRoadPlan(roads, { x: 0, z: 0, footprint: centerStats.footprint }));
  for (const cell of [{ x: 6, z: 0 }, { x: -6, z: 0 }, { x: 0, z: 6 }, { x: 0, z: -6 }]) {
    assert.ok(roads.cellAt(cell), `the centre ring exposes the ${cell.x},${cell.z} side`);
  }

  const structures = new PlacedStructureSystem();
  const depot = structures.place("player", depotStats, 20, 0);
  const farm = structures.place("player", farmStats, 20, 10);
  structures.advanceConstruction(depot, depotStats.constructionSeconds);
  structures.advanceConstruction(farm, farmStats.constructionSeconds);
  depot.storageCapacity = depotStats.progression?.settlement[0]?.storageCapacity ?? null;
  const isolatedRoute = roads.plan({ x: 16, z: 0 }, { x: 16, z: 10 }, []);
  assert.ok(isolatedRoute);
  roads.commit(isolatedRoute);

  const depots = new DepotLogisticsSystem(structures, roads, centers);
  const production = new ProductionLogisticsSystem(structures, roads, depots);
  const capacity = new ResourceCapacitySystem(structures, depots);
  assert.equal(depots.snapshots()[0]?.status, "unlinked-main-network");
  assert.equal(production.snapshots()[0]?.status, "unlinked-main-network");
  // Both figures come from the tables the runtime reads: the centre's own
  // starter store, and the depot tier the fixture just applied.
  const centreFood = COMMAND_CENTER_STORAGE_CAPACITY.food ?? 0;
  const depotFood = depotStats.progression?.settlement[0]?.storageCapacity?.food ?? 0;
  assert.equal(capacity.capacityFor("player").food, centreFood, "an isolated depot cannot add global capacity");

  const connection = roads.plan({ x: 6, z: 0 }, { x: 16, z: 0 }, []);
  assert.ok(connection);
  roads.commit(connection);
  assert.equal(depots.snapshots()[0]?.status, "linked");
  assert.equal(production.snapshots()[0]?.status, "linked", "a producer may deliver through the centre network");
  assert.equal(
    capacity.capacityFor("player").food,
    centreFood + depotFood,
    "the connected depot adds its tier capacity to the centre store",
  );
  assert.equal(structures.destroy(depot), true);
  assert.equal(production.snapshots()[0]?.status, "linked", "the connected centre remains a delivery endpoint without a depot");
  assert.equal(capacity.capacityFor("player").food, centreFood, "the centre retains its own opening storage after a depot is lost");
  structures.clear();
});

check("RTS full storage leaves linked production in its local buffer until capacity is freed", () => {
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const roadBalance = validateRoadBalance(
    JSON.parse(readFileSync("public/game-data/balance/roads.json", "utf8")) as unknown,
  );
  const depotStats = buildings.depot ?? assert.fail("depot definition missing");
  const farmStats = buildings.farm ?? assert.fail("farm definition missing");
  const units = new UnitSystem();
  for (let index = 0; index < 3; index += 1) units.spawn("player", -2 + index * 2, 17, RTS_TEST_WORKER_STATS);
  const structures = new PlacedStructureSystem();
  const depot = structures.place("player", depotStats, 0, 0);
  const farm = structures.place("player", farmStats, 0, 10);
  structures.advanceConstruction(depot, depotStats.constructionSeconds);
  structures.advanceConstruction(farm, farmStats.constructionSeconds);
  depot.storageCapacity = depotStats.progression?.settlement[0]?.storageCapacity ?? null;
  const navigation = new RtsNavigation();
  navigation.setBlockers(structures.navigationBlockers());
  const production = new EconomyProductionSystem(units, structures, navigation, () => false);
  const roads = new RoadGraph(roadBalance);
  const route = roads.plan({ x: 4, z: 0 }, { x: 4, z: 10 }, []);
  assert.ok(route);
  roads.commit(route);
  // Opened one unit short of the ceiling the same system computes, so the run
  // below has exactly one unit of room and everything after it must stay in the
  // farm's local buffer. Derived, because the ceiling is centre + depot tier and
  // both are balance data.
  const storage = new ResourceCapacitySystem(structures);
  const foodCeiling = storage.capacityFor("player").food ?? 0;
  const kingdoms = new KingdomRegistry(["player"], units, structures, { food: foodCeiling - 1 }, 20);
  const links = new ProductionLogisticsSystem(structures, roads, new DepotLogisticsSystem(structures, roads));
  const transfers = new LogisticsTransferSystem(production, links, kingdoms, storage);
  for (let frame = 0; frame < 900; frame += 1) {
    updateUnitMovement(units.all(), 1 / 60);
    production.update(1 / 60);
    transfers.update(instantCaravanArrivals(links));
  }
  assert.equal(kingdoms.get("player").wallet.amount("food"), foodCeiling, "delivery stops at the depot-backed limit");
  assert.ok((production.snapshots("player")[0]?.localBuffer ?? 0) > 0, "excess output remains locally buffered");
  structures.clear();
  units.clear();
});

check("RTS completed depots become road-graph nodes only when a road touches their footprint", () => {
  const balance = validateRoadBalance(
    JSON.parse(readFileSync("public/game-data/balance/roads.json", "utf8")) as unknown,
  );
  const buildings = validateBuildingBalance(
    JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown,
  );
  const depotStats = buildings.depot ?? assert.fail("depot definition missing");
  const structures = new PlacedStructureSystem();
  const depot = structures.place("player", depotStats, 0, 0);
  structures.advanceConstruction(depot, depotStats.constructionSeconds);
  const farmStats = buildings.farm ?? assert.fail("farm definition missing");
  const farm = structures.place("player", farmStats, 0, 10);
  structures.advanceConstruction(farm, farmStats.constructionSeconds);
  const roads = new RoadGraph(balance);
  const logistics = new DepotLogisticsSystem(structures, roads);
  const productionLogistics = new ProductionLogisticsSystem(structures, roads, logistics);
  assert.deepEqual(logistics.snapshots().map(({ status }) => status), ["unlinked"]);
  assert.deepEqual(productionLogistics.snapshots().map(({ status }) => status), ["unlinked-road"]);

  const route = roads.plan({ x: 4, z: 0 }, { x: 4, z: 8 }, []);
  assert.ok(route);
  roads.commit(route);
  assert.deepEqual(logistics.snapshots(), [{
    structureId: depot.id,
    owner: "player",
    x: 0,
    z: 0,
    roadCell: { x: 4, z: 0 },
    componentId: 1,
    status: "linked",
  }]);
  assert.deepEqual(productionLogistics.snapshots(), [{
    structureId: farm.id,
    owner: "player",
    resourceId: "food",
    roadCell: { x: 4, z: 6 },
    componentId: 1,
    depotStructureId: depot.id,
    status: "linked",
  }]);
  const occupation = new LogisticsOccupationSystem(logistics);
  occupation.setOccupier(depot.id, "enemy");
  const occupiedLink = new ProductionLogisticsSystem(structures, roads, logistics, undefined, occupation);
  assert.equal(occupiedLink.snapshots()[0]?.status, "depot-occupied");
  occupation.setOccupier(depot.id, null);
  const neutralTerritory = new TerritoryControlSystem(() => []);
  neutralTerritory.refresh();
  const outsideControl = new ProductionLogisticsSystem(structures, roads, logistics, neutralTerritory);
  assert.equal(outsideControl.snapshots()[0]?.status, "outside-control");
  neutralTerritory.dispose();
  structures.clear();
});

check("RTS logistics transfers linked buffers globally and stops when the road is cut", () => {
  const buildings = validateBuildingBalance(JSON.parse(readFileSync("public/game-data/balance/buildings.json", "utf8")) as unknown);
  const balance = validateRoadBalance(JSON.parse(readFileSync("public/game-data/balance/roads.json", "utf8")) as unknown);
  const farmStats = buildings.farm ?? assert.fail("farm definition missing");
  const depotStats = buildings.depot ?? assert.fail("depot definition missing");
  const units = new UnitSystem();
  for (let index = 0; index < 3; index += 1) units.spawn("player", -2 + index * 2, 17, RTS_TEST_WORKER_STATS);
  const structures = new PlacedStructureSystem();
  const depot = structures.place("player", depotStats, 0, 0);
  const farm = structures.place("player", farmStats, 0, 10);
  structures.advanceConstruction(depot, depotStats.constructionSeconds);
  structures.advanceConstruction(farm, farmStats.constructionSeconds);
  const navigation = new RtsNavigation();
  navigation.setBlockers(structures.navigationBlockers());
  const production = new EconomyProductionSystem(units, structures, navigation, () => false);
  const roads = new RoadGraph(balance);
  const depots = new DepotLogisticsSystem(structures, roads);
  const links = new ProductionLogisticsSystem(structures, roads, depots);
  const kingdoms = new KingdomRegistry(["player", "enemy"], units, structures, { food: 0, wood: 0 }, 20);
  const wallet = kingdoms.get("player").wallet;
  const transfer = new LogisticsTransferSystem(production, links, kingdoms);

  for (let frame = 0; frame < 900; frame += 1) {
    updateUnitMovement(units.all(), 1 / 60);
    production.update(1 / 60);
    transfer.update(instantCaravanArrivals(links));
  }
  assert.equal(wallet.amount("food"), 0, "unlinked output remains local");
  assert.ok((production.snapshots()[0]?.localBuffer ?? 0) > 0);
  const route = roads.plan({ x: 4, z: 0 }, { x: 4, z: 10 }, []);
  assert.ok(route);
  roads.commit(route);
  for (let frame = 0; frame < 120; frame += 1) {
    wallet.advance(1 / 60);
    updateUnitMovement(units.all(), 1 / 60);
    production.update(1 / 60);
    transfer.update(instantCaravanArrivals(links));
  }
  assert.ok(wallet.amount("food") > 0, "linked output reaches global stock");
  assert.equal(production.snapshots()[0]?.localBuffer, 0, "linked buffer flushes every tick");
  const beforeCut = wallet.amount("food");
  roads.clear();
  for (let frame = 0; frame < 120; frame += 1) {
    wallet.advance(1 / 60);
    production.update(1 / 60);
    transfer.update(instantCaravanArrivals(links));
  }
  assert.equal(wallet.amount("food"), beforeCut, "road loss stops global credit");
  assert.ok((production.snapshots()[0]?.localBuffer ?? 0) > 0, "disconnected output returns to local storage");
  structures.clear();
  units.clear();
});

